INSERT INTO `lessons` (`id`, `module_id`, `order`, `title`, `lesson_type`, `content`, `video_url`, `reading_time_minutes`, `xp_reward`, `created_at`) VALUES
(1, 1, 1, '1-Ma\'ruza: Boshlang\'ich ta\'lim pedagogikasi fanining mazmuni, predmeti va ilmiy-tadqiqot metodlari', 'lecture', '1-2-MAVZU: BOSHLANG\'ICH TA\'LIM PEDAGOGIKASI FANINING MAZMUNI, PREDMETI, METODOLOGIYASI, ILMIY-TADQIQOT\n\nOBYEKTI, METODLARI.\n\nReja:\n\n1. Boshlang\'ich ta\'lim pedagogikasi fanining maqsad va vazifalari.\n\n2. Boshlang\'ich ta\'lim pedagogikasi fanining asosiy tushunchalari.\n\n3.Ilmiy-pedagogik tadqiqot metodlari.\n\nTayanch tushunchalar: pedagogika, didaktika, metodika, ta\'lim, tarbiya boshlang\'ich ta\'lim, individ, shaxs, yosh davri, o\'smirlik, o\'spirinlik, tadqiqot metodlari, omillar.\n\nBoshlang\'ich ta\'lim pedagogikasi fanining maqsad va vazifalari. Pedagogika (yunoncha paidagogike bo\'lib, paidagogos “bola” va “yetaklayman”) ijtimoiy tarbiyaning umumiy qonuniyatlari, muayyan jamiyatda yagona ijtimoiy maqsadga muvofiq yosh avlodni tarbiyalash hamda unga ta\'lim berishning mohiyati va muammolarini o\'rganadigan fan. Pedagogika ijtimoiy fanlar tizimiga kiruvchi fan sanalib, yosh avlod hamda kattalarni milliy istiqlol g\'oyalari asosida tarbiyalash, unga ta\'lim berish muammolarinio\'rganadi.\n\nPedagogika fani shaxsni rivojlantirishning ikki muhim jihati – uni o\'qitish va tarbiyalashga asosiy e\'tiborni qaratganligi bois didaktika (ta\'lim nazariyasi) va tarbiya nazariyasi fanning muhim tarkibiy qismlari hisoblanadi.\n\nDidaktika (yunoncha didaktikos “o\'rgatuvchi”) ta\'limning nazariy jihatlari, ta\'lim jarayonining mohiyati, tamoyillari, qonuniyatlari, o\'qituvchi va o\'qituvchi faoliyatlari, ta\'limning maqsadi, mazmuni, shakl, metod, vositalari, natijasi, ta\'lim jarayonini takomillashtirish yo\'llari va hokazo muammolarni tadqiq etadi.\n\nTarbiya nazariyasi – pedagogikaning muhim tarkibiy qismlaridan biri bo\'lib, tarbiya jarayoni mazmuni, shakl, metod, vosita va usullari, uni tashkil etish muammolarini o\'rganadi.\n\nPedagogika fani shaxsni shakllantirishdek ijtimoiy buyurtmani bajarish asosida jamiyat taraqqiyotini ta\'minlashga alohida hissa qo\'shadi. Pedagogika fani maqsadi va vazifalarining belgilanishida ijtimoiy munosabatlar mazmuni, davlat va jamiyat qurilishi, uning hayotida etakchi o\'rin tutuvchi g\'oyalar mohiyati muhim ahamiyatga ega.\n\nO\'zbekiston Respublikasida demokratik, insonparvar hamda huquqiy jamiyatni barpo etish sharoitida mazkur fan yuksak ma\'naviy va axloqiy talablarga javob beruvchi yuqori malakali kadrni tarbiyalash tizimini ishlab chiqish, milliy istiqlol g\'oyasi asosida ta\'lim va tarbiya nazariyasini ijodiy rivojlantirish vazifasini hal etadi. Bu jarayonda quyidagi vazifalarni bajarishga e\'tibor qaratiladi:\n\n1. Ma\'naviy va axloqiy talablarga javob beruvchi yuqori malakali kadrni tarbiyalashga yo\'naltirilgan pedagogik jarayonning mohiyatini o\'rganish.\n\n2. Shaxsni har tomonlama kamol toptirish qonuniyatlarinianiqlash.\n\n3. Ijtimoiy taraqqiyot darajasidan kelib chiqqan holda, rivojlangan xorijiy mamlakatlar ta\'lim tizimi tajribasini o\'rganish asosida uzluksiz ta\'lim tiziminitakomillashtirish.\n\nTa\'lim muassasalari hamda, ularda faoliyat olib borayotgan pedagoglar faoliyati mazmuniniasoslash.\n\nIlg\'or pedagogik tajribalarni umumlashtirish va amaliyotga joriyetish.\n\nPedagoglarni pedagogika nazariyasiga oid bilimlar hamda ta\'lim-tarbiya usullari bilan qurollantirish.\n\nTa\'lim-tarbiya birligi hamda ijtimoiy tarbiya yo\'nalishlari o\'rtasidagi o\'zaro aloqadorlikni ta\'minlashning pedagogik shart-sharoitlarinio\'rganish.\n\nO\'qitish hamda tarbiyalash jarayonining samarali texnologiyalarini yaratish.\n\nOila tarbiya ni muvaffaqiyatli tashkil etish yuzasidan ota-onalar uchun ilmiy- metodik tavsiyalarni ishlabchiqish.\n\nBizga yaxshi ma\'lumki, har bir fan o\'zining tayanch tushunchalari, qonuniyatlari, tamoyillari, qoidalari tizimiga ega. Aynan mana shu holat uning fan sifatida e\'tirof etilishini kafolatlaydi. Fanning mohiyatini ochib beruvchi eng muhim, asosiy tushuncha kategoriya deb ataladi. Pedagogika fanining asosiy kategoriyalari shaxs kamolotini ta\'minlash, ta\'lim va tarbiya samaradorligiga erishishga haratilgan jarayonlarning umumiy mohiyatini yoritadi. Eng muhim kategoriyalar sirasiga quyidagilar kiradi: shaxs, tarbiya, ta\'lim (o\'qitish, o\'qish), bilim, ko\'nikma, malaka, ma\'lumot, rivojlanish.\n\n2.Boshlang\'ich ta\'lim pedagogikasi fanining asosiy tushunchalari.\n\nShaxs – psihologik jihatdan taraqqiy etgan, shaxsiy xususiyatlari va xatti-harakatlari bilan boshqalardan ajralib turuvchi, muayyan xulq-atvor va dunyoqarashga ega bo\'lgan jamiyat a\'zosi.\n\nTarbiya - muayyan, aniq maqsad hamda ijtimoiy-tarixiy tajriba asosida yosh avlodni har tomonlama o\'stirish, uning ongi, xulq-atvori va dunyoqarashini tarkib toptirishjarayoni.\n\nTa\'lim –o\'quvchilarni nazariy bilim, amaliy ko\'nikma va malakalar bilan qurollantirish, ularning bilish qobiliyatlarini o\'stirish va dunyoqarashlarini shakllantirishga yo\'naltirilgan jarayon.\n\nBilim – shaxsning ongida tushunchalar, sxemalar, ma\'lum obrazlar ko\'rinishida aks etuvchi borliq haqidagi tizimlashtirilgan ilmiy ma\'lumotlar majmui.\n\nKo\'nikma – shaxsning muayyan faoliyatni tashkil eta olish qobiliyati.\n\nMalaka –muayyan harakat yoki faoliyatni bajarishning avtomatlashtirilgan shakli.\n\nMa\'lumot – ta\'lim-tarbiya natijasida o\'zlashtirilgan va tizimlashtirilgan bilim, hosil qilingan ko\'nikma va malakalar hamda tarkib topgan dunyoqarash majmui.\n\nRivojlanish – shaxsning fiziologik va intellektual o\'sishida namoyon bo\'ladigan miqdor va sifat o\'zgarishlar mohiyatini ifoda etuvchi murakkab jarayondir.\n\nShaxs kamolotini ta\'minlash, uning intellektual, ma\'naviy-axloqiy hamda jismoniy jihatdan rivojlanishiga erishishda turli yosh davrlari, har bir davrning o\'ziga xos jihatlari, shuningdek, bolaning fiziologik, psihologik holatini inobatga olish maqsadga muvofiqdir. Shu bois yaxlit pedagogik jarayon muayyan turkumni tashkil etuvchi pedagogik fanlar tomonidan o\'rganiladi. Ularquyidagilardir:\n\nUmumiy pedagogika –ta\'lim va tarbiya jarayonining umumiy qonuniyatlari, tamoyillari, amalga oshirish shakl, metod, vositalarini o\'rganadi.\n\nMaktabgacha ta\'lim pedagogikasi – maktabgacha ta\'lim yoshidagi bolalarni tarbiyalash, ularni intellektual, ma\'naviy-axloqiy va jismoniy jihatdan kamolotga etkazish masalalarinio\'rganadi.\n\nKorreksion (maxsus) pedagogika – rivojlanishida turli psihologik va fiziologik nuqsonlari bo\'lgan bolalarni tarbiyalash va o\'qitish bilan bog\'liq muammolarnio\'rganadi.\n\nO\'z navbatida korrektsion pedagogika uch qismnga bo\'linadi: surdopedagogika, oligofrenopedagogika, tiflopedagogika.\n\nMetodika – xususiy fanlarni o\'qitish xususiyatlarinio\'rganadi.\n\nPedagogika tarixi – ta\'lim va tarbiyaning yuzaga kelishi, taraqqiy etishi, muayyan tarixiy davrlarda etakchi o\'rin egallagan pedagogik fikrlar taraqqiyoti masalalarinio\'rganadi.\n\nPedagogik texnologiya – ta\'lim va tarbiya jarayonida zamonaviy pedagogik texnologiyalarni qo\'llash, texnologik yondashuv asosida ta\'lim va tarbiya jarayonining samaradorligini oshirish muammolarini o\'rganadi.\n\nPedagogik mahorat – bo\'lajak o\'qituvchilarning kasbiy mahoratlarini oshirish, takomillashtirish muammolarini o\'rganadi.\n\nIjtimoiy pedagogika – ijtimoiy munosabatlar jarayonida pedagogik g\'oyalarning tutgan o\'rni va roli, shaxsni kasbiy va ijtimoiy faoliyatga yo\'naltirish muammolarinio\'rganadi.\n\n3.Pedagogik ilmiy-tadqiqot metodlari. Pedagogika fani rivoji muayyan pedagogik muammolarni tadqiq etish maqsadida olib borilgan tadqiqot ishlarining g\'oyasi, mazmuni hamda natijalari hisobiga ta\'minlanadi. Ijtimoiy va ishlab ciqarish jarayonining keskin rivojlanishi shaxsni har tomonlama kamol toptirish imkonini beruvchi omil hamda pedagogik shart- sharoitlarni aniqlash, jamiyat va shaxs ma\'naviyatiga ziyon etkazuvchi holatlarni bartaraf etishni taqozo qiladi. Tarbiya jarayonlarining mohiyatini anglash ularni keng yoki tor doirada o\'rganish, mavjud ko\'rsatkichlar vositasida ularning sodir bo\'lish sabablarini o\'rganish, zarur chora- tadbirlarni belgilash ilmiy izlanishlarni tashkil etish zaruriyatini yuzaga keltiradi. Pedagogik izlanishlarning samarali kechishi bir qator obyektiv va sub\'ektiv omillarga bog\'liq. Mazkur jarayonda maqsadga muvofiq keluvchi, maqbul. Ayni vaqtda samarali bo\'lgan metodlarni tanlay olish ham muhimdir. Shaxsni tarbiyalash, unga muayyan yo\'nalishlarda chuqur, puxta ilmiy bilimlarni berishga berish tamoyillari, obyekti va sub\'ektiv omillarini aniqlovchi pedagogik jarayonning ichki mohiyati, aloqa va qonuniyatlarini maxsus tekshirish va bilish usullaridir.\n\nZamonaviy sharoitda, pedagogik yo\'nalishda, tadqiqotlarni olib borishda quyidagi metodlardan foydalanilmoqda:\n\nPedagogik kuzatishmetodi.', 'xBIzptn-30I', 15, 25, '2026-11-06 09:32:34'),
(2, 1, 2, '1-Amaliyot: Ilmiy-tadqiqot metodlarini qo\'llash va pedagogik kuzatuv kundaligini yuritish', 'practice', '# 1-AMALIYOT: ILMIY-TADQIQOT METODLARINI QO\'LLASH VA PEDAGOGIK KUZATUV KUNDALIGINI YURITISH\n\n### 🎯 Mashg\'ulotning asosiy maqsadi:\nNazariy bilimlarni bevosita sinf amaliyotida, simulyatsion dars bosqichlari va pedagogik keyslar orqali qo\'llash ko\'nikmalarini shakllantirish.\n\n### 📋 Amaliy ish bosqichlari:\n1. **Didaktik maqsadni belgilash:** Boshlang\'ich sinf o\'quvchilarining yosh xususiyatlariga mos vazifalar tanlash.\n2. **Interfaol metodlarni qo\'llash:** Mavzuga mos klaster, aqliy hujum, keys-stadi yoki loyiha metodini dars bosqichlariga kiritish.\n3. **Refleksiv tahlil:** Dars yakunida o\'quvchilarning o\'zlashtirish darajasini va o\'qituvchining o\'z faoliyatini xolisona baholash.\n\n### 💡 Metodik ko\'rsatma:\nUshbu amaliy mashg\'ulot M.B. Muxamadaliyeva tomonidan ishlab chiqilgan **operatsion-faoliyatli** va **refleksiv** komponentlarni rivojlantirishga qaratilgan bo\'lib, bo\'lajak o\'qituvchining darsni mustaqil loyihalay olish mahoratini oshiradi.\n', 'xBIzptn-30I', 20, 35, '2026-11-06 09:32:34'),
(3, 1, 3, '2-Ma\'ruza: Boshlang\'ich maktabda pedagogik jarayonning zamonaviy tendensiyalari', 'lecture', '2-mavzu: Boshlang\'ich maktabdan pedagogik jarayoning zamonaviy tendesiyalari.\n\nReja\n\nTa\'lim mazmuning mohiyati va uning tarixiy tasnifi.\n\nPedagogik texnologiyani amaliyotga tatbiq etishning konseptual-pedagogik bosqichilari.\n\nO\'quv jarayonida o\'quvchilar bilimini nazorat va hisobga olishning vazifalari 4.O\'quvchilarning bilim, ko\'nikma va malakalarini baholash mezonlari.\n\nTayanch tushunchalar: pedagogik jarayon, bilim, ko\'nikma, va malaka, baxo,baholash, mezon, nazorat.\n\nTa\'lim mazmuning mohiyati va uning tarixiy tasnifi. Ta\'limning eng muhim ijtimoiy vazifasi – ijtimoiy talablarga mos keluvchi shaxsni shakllantirishdir. Ta\'lim jarayoni insoniyatning ruhiy va moddiy madaniyatining aks ettiruvchi qismi faoliyat usullari va tizimlashtirilgan ilmiy bilimlarni egallash asosida yuzagakeladi.\n\nTa\'limning mazmuni deganda, o\'quvchilarning o\'qish jarayonida egallashi lozim bo\'lgan hamda tizimga solingan bilim, ko\'nikma va malakalarning aniq belgilangan doirasi tushuniladi.\n\nTa\'lim mazmuni uchun bir nechta asosiy qoidalar mavjud, jumladan:\n\nta\'lim mazmuni ilmiy asosga yo\'nalganbo\'ladi;\n\nta\'lim mazmuni fanda faqatgina faktlar va nazariy qoidalar tarzida ochibberiladi;\n\no\'quv materiali fanlarning zamonaviy holatiga mos bo\'ladi, hayotiy qarashlarni shakllantirishga imkonberadi;\n\nhar bir o\'quv fani bo\'yicha ta\'lim mazmuni shu yoki boshqa fanlar tizimiga mantiqan mos bo\'ladi;\n\nta\'lim mazmuni alohida o\'quv fanlari orasidagi o\'zaro aloqadorlikkaasoslanadi;\n\nmaktab, o\'rta-maxsus kasb hunar ta\'limida ta\'lim texnik va mehnat ta\'limi bilan birga qo\'shib olib boriladi, o\'quvchilarni kasbga yo\'naltirishga imkon beradi;\n\nta\'lim bilimlarni egallashda qiyinchiliklarni yengib o\'tishda irodalilikni shakllantirishga o\'rgatadi;\n\nta\'lim mazmuni o\'quvchilarning yosh imkoniyatlariga mosbo\'ladi.\n\nTa\'lim mazmuniga nisbatan ikki xil yondoshuv mavjud: 1) bilimga yo\'naltirilgan. 2) shaxsga yo\'naltirilgan yondoshuv.\n\nTa\'lim muassasalaridagi o\'qitish mazmuniga qo\'yilayotgan talab mazkur mamlakatning ishlab chiqqan strategiyasida aniqlanadi. Bu strategiya “Kadrlar tayyorlash milliy dasturi” da yozilgan bo\'lib, unda taxlim tizimi tubdan isloh qilindi, yuqori darajali kadrlar tayyorlashning uzluksiz tizimini egallagan mamlakatlardagi kabi yo\'lga qo\'yil ko\'zda tutilgan.\n\nHozirgi davrda bizning respublikamizda ta\'lim mazmunini aniqlashda quyidagi g\'oyalarga asoslaniladi: insonparvarlashuv, differentsiallashuv, integratsiyalash hamda axborot texnologiyalaridan keng foydalanish.\n\nTa\'lim mazmunini insonparvarlashtirish deganimiz ta\'lim muassasasi bolaga ehtibor bilan qarashini, ya\'ni bolaning shaxsini hurmat qilish, iularning qiziqishlarini, qobiliyatlarini hisobga olish yotadi. Shuning bilan birga o\'quvchilarning o\'quv soatini qisqartirish ortiqcha ishlardan saqlaydi. Insonparvarlashuv ijtimoiy va tabiiy va ilmiy fanlarning “insonga xizmat” qilishini talab etadi. Ta\'lim mazmunini insonparvarlashtirishda asosiy rolni til va adabiyot, ruhiy-insonparvarlik tarbiya, jamiyatshunoslik fanlari asosiy rolg\' o\'ynaydi.\n\nTa\'lim mazmunini differentsiallashuvi- o\'quv tashkil etishdagi ikkinchi yetakchi g\'oya. Differentsiyallashuv-bu hozirgi davrda ta\'lim berishning umumiy tendentsiyasi. Bizning respublikamizda ta\'lim berishni differentsiallashtirish maqsadida fanlarni chuqurlashtirib o\'qitiladigan sifnlar, maktablar ochilgan.\n\nTa\'lim mazmunini integratsiyalashuvi g\'oyasi bir-biriga yaqin fanlarni qo\'yib, integrativ fanlarni yaratishni maqsad qilib qo\'yadi. Integrativ fanlar o\'quvchilarga olamning tugal manzarasini hosil qilishda ulkan rol o\'ynaydi. Bundan tashqari o\'tiladigan darslarning sonini qisqartiradi.\n\nTa\'lim mazmuni normativ xujjatlar: o\'quv rejasi, o\'quv dasturi va darsliklarda ko\'rsatilgan.\n\nO\'quv rejasi: davlat xujjatidir. O\'quv rejasi barcha ta\'lim muassasalarida so\'zsiz amal qilinishi lozim bo\'lgan davlat xujjatidir.\n\nO\'quv rejasi tegishli ta\'lim vazirligi tomonidan tasdiqlanadi. O\'quv rejasida:\n\no\'quv-yilining boshlanishi va tugash vaqti, beriladigan tahtillarning kuni, ta\'lim muassasasida o\'tilishi kerak bo\'lgan fanlarningtizimi;\n\no\'rganilayotgan fanlarning ro\'yxati va bo\'linishi (taqsimqilinishi);\n\nfanlarning asosiy va fakulg\'tativlargabo\'linishi;\n\nhar bir sinfda o\'quv fanlarini o\'rganishda haftalik va-yillik taqsim qilinishi soati ko\'rsatilganbo\'ladi.\n\nO\'quv dasturi o\'quv rejasi asosida har bir o\'quv fani uchun tuziladi. O\'quv dasturi har bir o\'quv fanini o\'qitish uchun ajratilgan bilim hajmi, tizimi va g\'oyaviy-siyoiy yo\'nalishini aniqlab beradigan xujjatdir.\n\nO\'quv dasturida o\'quv-yili davomida har qaysi sinfda alohida fanlar bo\'yicha o\'quvchilarga beriladigan ilmiy bilim, ko\'nikma va malakalarning hajmi belgilab beriladi. Dasturda har qaysi o\'quv fanlarining mazmuni izchillik bilan yoritiladi va ta\'lim mavzular orqali ko\'rsatiladi. Ma\'lum mavzu yuzasidan o\'quvchi o\'zlashtirishi lozim bo\'lgan bilim, ko\'nikma va malakalar qsqacha ifodalab beriladi.\n\nO\'quv dasturi uch qismga bo\'linadi:\n\ntushuntirish xati (o\'rganilayotgan fanning) maqsad vavazifalari;\n\nmazmuniy (asosiy)qism;\n\nbilim, ko\'nikma va malakalarni baholashda metodik ko\'rsatma, ta\'limning ko\'rsatma\'li va texnik vositalari soni, tavsiya etilgan adabiyotlarro\'yxati;\n\nDarslik – o\'quv adabiyotlarining asosiy turi. Unda fan va madaniyatning zamonaviy yutuqlari darajasi, aniq sohadagi bilimlar asosida tizimli ravishda bayon etiladi.\n\nDarslik ta\'lim asosiy maqsad va vazifalariga, aniq yoshdagi ijtimoiy guruhning rivojlanishiga va tarbiyalanishiga javob beradi.\n\nDarslik o\'quvchilarning ikkinchi “muallimi”. Chunki u avvalo o\'quvchi uchun zarur qo\'llanmadir.Har bir o\'quv fanining mazmuni darslikda batafsil yoritiladi. Darslik tegishli fanga oid ilmiy bilim asoslarini dasturga va didaktika talablariga muvofiq ravishda bayon qiluvchi kitobdir. Darslik bilan bir qatorda ayrim o\'quv fanlari yuzasidan o\'quv qo\'llanmalari tuziladi. Masalalar va mashqlar to\'\'lami, atlaslar, xrestomatiyalar, lug\'at kitoblari va hokazolar.\n\n4. Davlat ta\'lim standartlari Davlat ta\'lim standarti O\'zbekiston Respublikasi o\'z mustaqilligini qo\'lga kiritilgandan so\'ng yaratildi. DTS O\'zbekiston Respublikasi “Ta\'lim to\'g\'risida”gi Qonuni va “Kadrlar tayyorlash Milliy Dasturi” normativ xujjatlari asosida yaratilgan. Standart o\'lchov, andoza, qoli\', mezon ma\'nosini beradi. DTS ta\'limning mazmuniga hamda sifatiga qo\'yiladigan talablarni belgilaydi. DTS ta\'lim oluvchilarning bilim, ko\'nikma va malakalarining sifatiga qo\'yiladigan minima\'l darajadagi talabni aniqlaydi.DTS larni bajarish O\'zbekiston Respublikasining barcha ta\'lim muassasalari uchun majburiydir.\n\n2. Pedagogik texnologiyani amaliyotga tatbiq etishning konseptual-pedagogik bosqichilari.\n\nMa\'lumki, har qanday texnologiya ta\'limning yangi mazmunini shakllantiruvchi ta\'lim tamoyillariga asoslanadi va ta\'lim oluvchi shaxsini tarbiyalash, unda mehnat va muayyan yo\'nalishlarda kasbiy ko\'nikmalarni hosil kilishga yo\'naltiriladi. Ta\'lim jarayonining faol sub\'ektlari o\'qituvchi va o\'quvchilar bo\'lib, ularning hamkorligidagi faoliyatlari muayyan mavzu (yoki fanlar asoslari) bo\'yicha kam kuch va vaziyatini tavsiflaydi.\n\nO\'qituvchining faol, samarali faoliyat ko\'rsatishiga yo\'naltirilgan ta\'lim jarayonining metodik ishlanmasidan farqli ravishda, ta\'limning pedagogik texnologiyasi ta\'lim oluvchilarga qaratiladi, shuningdek, ularning shaxsiy va o\'qituvchi bilan birgalikdagi faoliyatini hiisobga olgan holda o\'quv materialini o\'zlashtirishga sharoit yaratadi. pedagogik texnologiyaning yetakchi muammosi talaba shaxsini rivojlantirish orqali ta\'lim maqsadiga erishishni ta\'minlashdan iboratdir.\n\nPedagogik texnologiya turini tanlash dars va mashg\'ulotda qaysi darajadagi bilim va ko\'nikmalarni o\'zlashtirishni nazarda tutilganiga bog\'liqdir.\n\nTa\'lim-tarbiya jarayoni butun mashg\'ulot davomida o\'quvchilarning faolligi va qiziquvchanligini muntazam ravishda rivojlantirib borish maqsadini ko\'zda tutadi, o\'quv omillarini yaratishga asoslangan pedagogik texnologiya talabalarni o\'quv yoki o\'quv ishlab chiqarish faoliyatiga tezkor jalb qilish imkonini beradi. Aks hoda, zaif, yetarli darajada tushunarli bo\'lmagan yoki aniq natijani ko\'zlanmagan topshiriqlar mashg\'ulotning samarasiz yakunlanyshiga olib keladi.', 'PDLXPWO98LM', 15, 25, '2026-11-06 09:32:34'),
(4, 1, 4, '2-Amaliyot: Zamonaviy dars tahlili va pedagogik tendensiyalar xaritasini shakllantirish', 'practice', '# 2-AMALIYOT: ZAMONAVIY DARS TAHLILI VA PEDAGOGIK TENDENSIYALAR XARITASINI SHAKLLANTIRISH\n\n### 🎯 Mashg\'ulotning asosiy maqsadi:\nNazariy bilimlarni bevosita sinf amaliyotida, simulyatsion dars bosqichlari va pedagogik keyslar orqali qo\'llash ko\'nikmalarini shakllantirish.\n\n### 📋 Amaliy ish bosqichlari:\n1. **Didaktik maqsadni belgilash:** Boshlang\'ich sinf o\'quvchilarining yosh xususiyatlariga mos vazifalar tanlash.\n2. **Interfaol metodlarni qo\'llash:** Mavzuga mos klaster, aqliy hujum, keys-stadi yoki loyiha metodini dars bosqichlariga kiritish.\n3. **Refleksiv tahlil:** Dars yakunida o\'quvchilarning o\'zlashtirish darajasini va o\'qituvchining o\'z faoliyatini xolisona baholash.\n\n### 💡 Metodik ko\'rsatma:\nUshbu amaliy mashg\'ulot M.B. Muxamadaliyeva tomonidan ishlab chiqilgan **operatsion-faoliyatli** va **refleksiv** komponentlarni rivojlantirishga qaratilgan bo\'lib, bo\'lajak o\'qituvchining darsni mustaqil loyihalay olish mahoratini oshiradi.\n', 'PDLXPWO98LM', 20, 35, '2026-11-06 09:32:34'),
(5, 1, 5, '3-Ma\'ruza: An\'anaviy va innovatsion ta\'limning qiyosiy tahlili', 'lecture', '3-MAVZU: An\'anaviy va innovatsion ta\'limning qiyosiy tahlili.\n\nReja:\n\n1. Innavatsion ta\'limning qirralari\n\n2. O\'qituvchini innovatsion ta\'limga tayyorlash usullari\n\n3. An\'anaviy ta\'lim va innovatsion ta\'limning farqli tomonlari\n\nTayanch tushunchalar: Jamoa, everistik, innovatsiya, gumanistik pedagogika, innovatsion pedagogika.\n\nMavjud ijtimoiy-iqtisodiy o\'zgarishlar ta\'lim jarayoniga innovatsion yondashuvga kirib borishini taqozo etmoqda. o\'qitish muammolari nafaqat pedagoglar, sotsiologlar, balki faylasuflar, psixologlarning ham diqqatini o\'ziga qaratmoqda. «Innovatsiya» tushunchasi o\'zining asosiy mazmunmohiyatiga ko\'ra yangiliklarni kiritish, ularni tarqatishni emas, balki bu faoliyat bilan bog\'liq bo\'lgan ta\'limdagi faoliyat o\'zgarishlarini, fikrlash yo\'llarini ham o\'z ichiga oladi. Innovatsion ta\'lim o\'quvchini jamiyatda o\'zgarishlarini qabul qila oladigan, ijodkor, ishbilarmon qilib tarbiyalaydi. Innovatsion ta\'limning asosiy mohiyati quyidagi lardan iborat: ta\'limning ochiq istiqbol, qadriyatlami baholay olish, yangi vaziyatlarga kirisha olish. Innovatsion ta\'lim qirralari quyidagi jadvalda keltirilgan:\n\nBu holat o\'qituvchidan pedagogik faoliyatdagi innovatsion xulqni talab etadi. V.A.Slastenin va L.S.Podimovalarning ishlarida keltirilgan psixologik nazariyaga oid ma\'lumotlarga ko\'ra o \'qituvchilarning innovatsion faoliyatiga xalaqit beruvchi quyidagi sabablar mavjud:\n\n1. Pedagog tomonidan tanaffuslarning maqsadi tushuntirilmasligi. Noaniqlik va ikkifikrlilik o\'qituvchida yangilikka nisbatan qo\'rqinch hissini uyg\'otadi.\n\n2. Yangilikning kiritilishi va amalga oshirilishida pedagoglarning ishtirok etmasligi.\n\n3. Jamoada mavjud an\'analarni hamda ishlash uslibining o\'zgarishi.\n\n4. Yangiliklarga subyektiv yondashuv.\n\n5. Ish hajmining ortishi. Bu holatning bo\'lish xavfi asosan tajriba rahbarining faoliyati oldindan rejalashtirilganligi.\n\n6. Yangilikni olib kiruvchi nisbatan ishonchsizlik, hurmatning talab darajasida emasligi. Afsuski, o\'qituvchilar asosan yangilik mazmuniga emas, balki uning muallifiga e\'tibor qaratishadi. Agar bu muallif jamoada hurmatga, e\'tiborga ega boMmasa, bu o\'zining salbiy ta\'sirini ko\'rsatadi. V.A.Slastenin va L.S.Podimovalarning pedagogning kasbiy tayyorgarligi, uning qarashlarining innovatsion tizimi, yangiliklarni ular tomonidan tavsiya etilgan texnologik xarita quyidagi modellar yordamida aniqlashtiriigan:\n\nKasbiy tayyorgarlikning 1-bosqichida o\'qituvchini innovatsion faoliyatga tayyorlash\n\nKasbiy tayyorgarlikning 2-bosqichida o \'qituvchining innovatsion faoliyatga tayyorgarligi\n\nTa\'lim o \'qituvchining innovatsion tayyorgarligi bilan bog\'liq, ko\'p darajali ta\'lim agar OTM da shaxsga yo\'naltirilgandagina o \'z samarasini beradi. Afsuski, hozircha o\'quv dasturlari faqatgina bilim, malaka va ko\'nikmalarning hajmini ko\'rsatib, o\'ziga xos tinglovchilarning individual xususiyatlaridan qat\'i nazar o\'zlashtirilishi majburiy bo\'lgan o \'ziga xos axborot tizimidan iborat bo\'lmoqda. Ularning ko\'pchiligida innovatsion faoliyatning asosini tashkil qiluvchi shaxsiy sifatlarinirivojlantirishga kam e\'tibor qaratilgan. Shuning uchun ham mahoratni egallash uzoq-yillarga (oliygohni bitirgandan so\'ng) cho\'ziladi va ko\'pgina hollarda katta qiyinchiliklar, ko\'p mehnat evaziga erishiladi. Bundan xulosa shuki, talabalarning qobiliyatlarini differensiatsiyalashga xizmat qiladigan, shaxsiy xususiyatlarini yuzaga chiqaradigan o\'rganuvchi muhit qanchalik erta yaratilsa, yangiliklarni kiritish jarayoni shunchalik tezlashadi va osonlashadi. Shaxsga yo\'naltirilgan ta\'limning tashkil etilishi o\'quv dasturlarini ishlab chiqish imkoniyatini beradi.\n\nOliy ta\'limmuassasasi ta\'limining turli bosqichlarida tayanch tayyorgarligiga nisbatan talablaming qo\'yilishi turlicha tavsiflanadi. Shaxs rivojlanishiga ta\'sir etishiga ko\'ra o\'quv dasturining baholanishiga munosabat bildiradi. Psixologik-pedagogik fanlarda bo\'lajak o\'qituvchi-innovatorning shaxsiy sifatlari: tashabbuskorlik, mustaqillik, refiektivlik, natijaning yaxshilanishi, o\'z imkoniyatlarini adekvat baholash, tanqidiy tahlil shakllanadi. Psixologik tadqiqotlar shuni ko\'rsatadiki, OTM bitiruvchilari faqatgina bilim, ko\'nikma va malakalari bilangina farq qilmaydilar. Bir xil ta\'lim muassasalarini tugatgan bitiruvchilar turli kasbiy tayyorgarlikka ega bo\'lib, bu holat ularning kasbiy o\'sish darajalarini ham belgilaydi. Yaxshi o\'zlashtirilmagan bilimlami o\'z ustida ishlab to\'ldirish mumkin, lekin kasbiy ijodkorlikni tarbiyalash ancha qiyin kechishini qayd etish lozim. Buning uchun ta\'limiy dasturlar talab etiladi. Agar bilim yetarli bo\'lmasa, uni o\'qib-o\'rganish mumkin, biror kasbiy ijodkorlik haqida bunday ish qilish qiyin kechadi. Inson xulqida bunday sifatlarni shakllantirish uchun maxsus dasturlar asosida ularni modellashtirish va qabul qilishni amalga oshirish mumkin. Bizningcha, bu jarayonda unchalik qiyin bo\'lmagan psixotreninglar, innovatsion o\'yinlar, refleksiv amaliyotlar o\'qitishning asosiy vositalari bo\'lishi darkor. Ilmiy bilimlami o\'zlashtirish mobaynida yuqorida keltirilgan metodologik yondashuvlar xilma-xildir. Bunday holatlarning bo\'lishi saralash, ta\'minlash asosida amalga oshadi. Tabiyat, jamiyat qonuniyatlarini o\'rganish metodologik yondashuvning xilma-xilligini aniqlaydi. Aytish lozimki, ilmiy metodologiyada hech bir yondashuv rad etilmaydi va hech biri asosiy o\'ringa chiqmaydi. Ularning har biri yordamida umumiy tarzda obyektiv borliq qonuniyatlarini o\'rganish mumkin.\n\nZamonaviy hisoblangan interaktiv metodlar barcha olimalar tomonidan ishlab chiqildi va uning an\'anaviy metodlardan ko\'ra effektivligi isbotlab berildi. Interektiv lotincha so\'z bo\'lib o\'zi faoliyat yurituvchi degan ma\'noni anglatadi. Zamonaviy texnologiyalar til o\'rganishning mustaqil fikrlashi va nutq yuritishiga qaratilagan metod ekanligiga amin bo\'ldik. Ma\'lum bo\'lishicha, zamonaviy texnologiyalar asosida o\'tiladigan Britaniya universitetlarida talabalar dars maqsadi va vazifalarini o\'zlari belgilashadi va o\'zlari tanlagan mavzu bo\'yicha bahslashib, xulosalar chiqarishadi .Ko\'rinib turibdiki ,dars jarayonida o\'quvchilar tashkilotchi ya\'ni lider vazifasini bajarishmoqda.Shunday qilib til o\'rganuvchining mustaqilligini ta\'minlash, ularning tilni puxta egallashi va erkin nutq yurita olishi bilan belgilanadi.Buni quyidagi ko\'rsatmalar orqali ko\'rsatish mumkin.\n\nKompyuterda nazorat kabi ishlar osonlikcha olib boriladi va guruhdagi til o\'rganuvchi soni bilan bog\'liq ayrim tashkiliy muammolarni yechadi. Kompyuter ta\'lim jarayonida an shunday imkoniyatlarni vujudga keltiradi. Shuning uchun ham ,ta\'lim jarayonida kompyuter bilan ishlash qulayliklarini yaratish va uni o\'quv rejasiga kiritish kabi muammolarni yechishda qiyinchilikarni yengishimiz zarur. Multimedia xonalari til o\'rganuvchiga video va audio konferensiyalarida ham ishtirok etish imkoniyatini yaratdi. Har bit o\'quvchi o\'zining kompyuterida ishlab turib, biron bir mavzu yuzasidan konferensiya o\'takazadi. Multimedia xonasidan foydalanish til o\'rgatishning hamma bosqichlarida samaralidir. Hozirgi kunda ingliz tilini kompyuter yordamida o\'grayish texnologiya emas balki \"san\'at\" bo\'lib qolmoqda.Lekin bu holni o\'zgartirish zarur ,ya\'ni ingliz tilini kompyuter orqali o\'rgatish \"san\'at\"emas , balki texnologiya bo\'lishi kerak.\n\nShuni aytish mumkinki hozirgi kunda o\'quvchilarni zamonaviy pedagogik texnologiyalar ya\'ni interaktiv metodlar asosida o\'qitish dolzarb masalaga aylangan.Interaktiv metodlarning an\'anaviy metodlardan farqi shundaki bunda o\'quvchining o\'zi mustaqil holda erkin fikr yuritadi ,o\'qituvchi bilan hamkorlikda ishlaydi.An\'anaviy metod esa o\'quvchining faktalarini esda saqlash qobilyati va uning hajmiga asoslanadi. An\'anaviy ta\'lim metodlari bugungi kunda kamchiliklarga ham egaki bu o\'quv jarayonida noan\'anaviy ta\'lim metodlarlarini qo\'llash extiyojlarini paydo qiladi. Bu kamchiliklar quyidagilardir:\n\n• O\'quvchilar passiv ishtirokchilar bo\'lib qoladilar, dars mashģulotlari markazida hamda asosiy boshqaruvchilik rolida o\'qituvchining turganiligi bunday passivlikka olib keladi.\n\n• O\'qituvchining tòla nazorati barcha o\'quvchilar uchun motivatsiyani vujudga keltiramaydi. Chunki o\'quvchilar tomonidan amalga oshirilayotgan barcha xattiharakatlar qat\'iy talab asosida sodir bo\'ladi.Bu o\'quvchida ijodiy tashabbusni uyğotmaydi.\n\n•Eslab qolsih darajasi hamma o\'quvchilarda bir hil bo\'lmasligi sababli ,sinf bo\'yicha o\'zlashtirish darajasi past bo\'lib qolishi mumkin.Ya\'ni,an\'anaviy ta\'limda mashğulotga va bilish jarayoniga o\'quvchilarni qiziqtiruvchi har xil uslublarni, xotirani mustahkamlovchi o\'yinli texnologiyalarni qo\'llash imkoniyatlardan foydalanilmasligi mazkur oqibatlarni keltirib chiqaradi.\n\n•Mustaqil o\'rganish va mustaqil qarorlar qabul qilish uchun sharoitlar yaratilmaydi talabani ijodiy fikrlashga undovchi kuchning mavjud emasligi tabiiy ravishda yangi ğoyalarni ishlab chiqish uchun sharoitlarni yuzaga keltirmaydi. O\'qitishning noan\'anaviy madellarini shartli ravishda uchga ajratish mumkin. Bu modellar asosan o\'quvchi shaxsiga qaratilgan bo\'lib, ularni boshqacha qilib markazda o\'quvchi turgan ta\'lim modellari deb ham atashadi.\n\nModellashtirish-real hayotda va jamiyatda yuz berayotgan hodisa va jarayonlarni ixchamlashtirilgan va soddalashtirilgan ko\'rinishini sinf xonada yaratish va ularda o\'quvchilarni shaxsan qatnashishi va faoliyati evaziga ta\'lim olishini ko\'zda tutuvchi metod . Xamkorlikda o\'rganish modeli\n\n– O\'quvchilarning mustaqil guruhlarda ishlashi evaziga ta\'lim olishini ko\'zda tutadigan metod. O\'rganishning tadqiqot modeli- O\'quvchilarni muayyan muammoni yechishga yo\'naltirilgan mustaqil tadqiqot olib borishini ko\'zda tutuvchi metod. Noan\'anaviy ( ta\'lim jarayoni markazida o\'quvchi bo\'lgan) o\'qitish metodlarining afzalliklari:\n\n• o\'qitish mazmunini yaxshi o\'zlashtirishga olib kelishi;\n\n• o\'z vaqtida aloqalarning ta\'minlanishi;\n\n• tushunchalarni amaliyotda qo\'llash uchun sharoitlar yaratilishi;\n\n•o\'qitish usullarining turli xil kòrinishlari taklif etilishi;\n\n• motivatsiyaning yuqori darajada bo\'lishi;\n\n• o\'tilgan materiallarni yaxshi eslab qolinishi;\n\n• Muloqatga kirishish ko\'nikmasining takomillashishi;\n\n•o\'z -o\'zini baholashning o\'sishi;\n\n•o\'quvchilarning predmetning mazmuniga, o\'qitish jarayoniga bo\'lgan ijobiy munosabati;\n\n•mustaqil fikrlay oladigan o\'quvchining shakllanishiga yordam berishi;\n\n•nafaqat mazmunini o\'zlashtirishga yordam bermay, balki tanqidiy va mantiqiy fikrlashni ham rivojlantirishi;\n\n•muommolarni yechish ko\'nikmalarining shakllanishi.\n\nXamkorlikda o\'rganish modeli Modellashtirish O\'rganishning tadqiqot modeli\n\nTadqiqotlar shuni ko\'rsatadiki, an\'anaviy dars shaklini saqlab qolgan holda,unga turli-tuman o\'quvchilar faoliyatini faollashtirilgan metodalar bilan boyitish o\'quvchilarning o\'zlashtirish darajasini ko\'tarilishiga olib kelar ekan. Buning uchun dars jarayoni oqilona tashkil qilinishi o\'qituvchi tomonidan o\'quvchilarning qiziqishini orttirib, ularning ta\'lim jarayonida faolligi muttasil rağbatlantirib turilishi, o\'quv materialini kichik-kichik bo\'laklarga bo\'lib, ularning mazmunini ochishda bahs, munozara, aqliy hujum,kichik guruhlarda ishlash, tadqiqot, rolli o\'yinlar metodlarini qo\'llash, rang-barang qiziqtiruvchi misollarning keltirilishi, o\'quvchilarni amaliy mashqlarni mustaqil bajarishiga undash, rang-barang baholash usullaridan foydalanish, ta\'lim vositalaridan joyida va vaqtida foydalanish talab etiladi.\n\nSavol va topshiriqlar\n\n1. «Innovatsiya» atamasini siz qanday tushunasiz?\n\n2. Innovatsion o\'quv jarayonini yo\'lg a qo\'yishda nimalar talab qilinadi?\n\n3. Gum anistik pedagogikani, ko\'pincha, innovatsion pedagogika deb atashadi. Bu haqda sizning fikringiz qanday?', 'XTaN9jt_AFo', 15, 25, '2026-11-06 09:32:34'),
(6, 1, 6, '3-Amaliyot: \'Venn diagrammasi\' vositasida an\'anaviy va innovatsion ta\'lim modellarini qiyoslash', 'practice', '# 3-AMALIYOT: \'VENN DIAGRAMMASI\' VOSITASIDA AN\'ANAVIY VA INNOVATSION TA\'LIM MODELLARINI QIYOSLASH\n\n### 🎯 Mashg\'ulotning asosiy maqsadi:\nNazariy bilimlarni bevosita sinf amaliyotida, simulyatsion dars bosqichlari va pedagogik keyslar orqali qo\'llash ko\'nikmalarini shakllantirish.\n\n### 📋 Amaliy ish bosqichlari:\n1. **Didaktik maqsadni belgilash:** Boshlang\'ich sinf o\'quvchilarining yosh xususiyatlariga mos vazifalar tanlash.\n2. **Interfaol metodlarni qo\'llash:** Mavzuga mos klaster, aqliy hujum, keys-stadi yoki loyiha metodini dars bosqichlariga kiritish.\n3. **Refleksiv tahlil:** Dars yakunida o\'quvchilarning o\'zlashtirish darajasini va o\'qituvchining o\'z faoliyatini xolisona baholash.\n\n### 💡 Metodik ko\'rsatma:\nUshbu amaliy mashg\'ulot M.B. Muxamadaliyeva tomonidan ishlab chiqilgan **operatsion-faoliyatli** va **refleksiv** komponentlarni rivojlantirishga qaratilgan bo\'lib, bo\'lajak o\'qituvchining darsni mustaqil loyihalay olish mahoratini oshiradi.\n', 'XTaN9jt_AFo', 20, 35, '2026-11-06 09:32:34'),
(7, 1, 7, '4-Ma\'ruza: Boshlang\'ich ta\'lim fanlarini o\'qitishda innovatsion yondashuv', 'lecture', '4- MAVZU: Boshlang\'ich ta\'lim fanlarini o\'qitishda innovatsion yondashuv\n\nReja:\n\nInnovatsiya tushunchasining mazmuni\n\nBoshlang\'ich ta\'limda innovatsiya\n\nBoshlang\'ich ta\'limda innovatsiyalarni tatbiq etish tajribalari\n\nTayanch tushunchalar: ta\'lim, boshlang\'ich, tarbiya, innovatsiya, mazmun, bilim, shakl, tushuncha, ko\'nikma, malaka, yondashuv.\n\nInnovatsiya tushunchasining mazmuni. ―Innovatsiya‖ so\'zi lotincha bo\'lib, yangidan kiritilgan tushunchalar, tartib – qoidalar, texnologiyalar va yangiliklarni anglatadi. Ta\'limda innovatsiya atamasi an\'anaviy va ommaviy amaliyotdagi o\'qitish hamda tarbiya jarayoniga kiritilgan yangiliklarni bildiradi, innovatsiya ko\'rsatkichi aynan ana Shu yangiliklar ko\'lami bilan belgilanadi. Ta\'lim va tarbiya jarayonida innovatsiya quyidagi tushunchalarni qamrab oladi:\n\nInnovatsion vaziyat – bu pedagogik yangiliklarni yaratish, o\'zlashtirish va tatbiq etishga qaratilgan vaziyat;\n\nInnovatsion muhit – pedagogik yangiliklarning vujudga kelishi, ularning jadal o\'zlashtirilishi va amaliyotga tatbiq qilinishi;\n\nInnovatsion pedagogik loyiha – qabul qilingan va qismlarga ajratilgan yangi pedagogik g\'oyalar hamda fikrlar;\n\nInnovatsion pedagogik reja – tasdiqlangan yangicha asosdagi o\'quv loyihasi;\n\nInnovatsion pedagogik g\'oya - tizimlashtirilgan yangi o\'quv jarayoni prognoztikasi va ma\'lumotlar majmui;\n\nInnovatsion ta\'lim - ta\'lim sohasiga kiritilgan va kiritilayotgan yangiliklar hamda yangilangan ta\'lim jarayoni;\n\nInnovatsion texnologiya – pedagogik taraqqiyotni ta\'minlashga\n\nqaratilgan yangi tashkiliy faollik vositalari, usullari va metodlari;\n\nInnovatsion o\'qitish – yangicha o\'qitish tizimi hamda o\'quvchi va talabalarni yangi kiritilgan texnologiyalar asosida o\'qitish jarayoni.\n\nMazkur tushunchalarning majmui ta\'limda innovatsiya hodisasini ifodalaydi. Ayni paytda ta\'lim tizimida quyidagilarga o\'zgartirishlar kiritilsa innovatsiya hisoblanadi:\n\nta\'limni va ta\'lim boshqaruvining maqsadi, mazmuni, shakllari, metodlari hamda texnologiyalariga kiritilsa;\n\no\'quv-bilish jarayoni va pedagogik usullarga kiritilsa;\n\nta\'lim darajasini baholash va nazorat qilishga kiritilsa;\n\nta\'limni moliyalashga kiritilsa;\n\no\'quv – metodik ta\'minotga kiritilsa;\n\ntarbiyaviy ishlar tizimiga kiritilsa;\n\no\'quv rejasi va dasturlarga kiritilsa;\n\no\'qituvchi va o\'quvchi faoliyatiga kiritilsa.\n\nMazkur o\'zgartirishlar kiritish jarayoni ta\'lida innovatsiya mazmunini ifodalaydi. Ayni paytda, innovatsiya rivojlanib boruvchi jarayon hisoblanadi. Buning ma\'nosi Shuki, ba\'zi innovatsion yondaShuvlar vaqtinchalik va ba\'zilari esa doimiy xususiyatga ega bo\'ladi. Shu jihatdan innovatsion texnologiyalarni o\'zgarib va yangilanib boruvchi vositalar majmui sifatida tasavvur qilishi kerak. Bularning barchasi ta\'lim tizimida innovatsiyalarning quyidagi uch shaklga ega ekanligini ko\'rsatadi:\n\nmutlaq yangiliklar;\n\nnisbiy yangiliklar;\n\nvaqtinchalik yangiliklar.\n\nShu sababli ta\'lim tizimiga kiritilayotgan innovatsion yondaShuvlar, g\'oyalar, fikrlar, usullar va texnologiyalarni aniqlashda ularning ana Shu mezonlariga e\'tibor berish kerak.\n\nBoshlang\'ich ta\'limda innovatsiya. O\'zbekiston boshlang\'ich ta\'lim tizimiga innovatsiyalarni tatbiq etish jarayoni 2017-yildan boshlab kuchaytirildi. Bundan maqsad boshlang\'ich ta\'lim jarayonining samaradorligiga tezkor erishishdir. Shu sababli bizning yondaShuvimizga ko\'ra, boshlang\'ich ta\'limga innovatsiyani kiritishda uning tajribadan o\'tgan tiplariga asoslanish maqsadga muvofiq bo\'ladi. Hozirgi zamon jahon pedagogikasida quyidagi innovatsion tiplarning tajribadan o\'tganligi e\'tirof etiladi:\n\nBirinchi tip. Bu tipga binoan boshlang\'ich ta\'limning quyidagi jihatlariga yangilik kiritilishi kerak:\n\nboshlang\'ich ta\'limning maqsadi va mazmuniga;\n\nboshlang\'ich ta\'limning vositalari, metodlari va texnologiyalariga;\n\nboshlang\'ich ta\'limning o\'qitish va tarbiyalash jarayoni shakllari va vositalariga;\n\no\'quvchilarning, o\'qituvchilarning va maktab ma\'muriyatining faoliyatiga.\n\nIkkinchi tip. Mazkur tipga ko\'ra, boshlang\'ich ta\'limning quyidagi jihatlariga yangiliklar kiritilishi kerak:\n\njoylardagi va markazlardagi boshlang\'ich ta\'lim muassasalarining o\'zaro aloqalarini bog\'lash;\n\nboshlang\'ich ta\'limdagi barcha faoliyatni (o\'qitish, tarbiyalash va h.k.) yagonalashtirish;\n\nboshlang\'ich ta\'lim tizimini yagona va tipik modulga aylantirish;\n\nUchinchi tip. Bu tipga ko\'ra, boshlang\'ich ta\'limda quyidagilarga yangiliklar kiritilishi kerak:\n\nan\'anaviy boshlang\'ich ta\'lim mazmunini butunlay o\'zgartirish;\n\nboshlang\'ich ta\'limga turli xorijiy tajribalarni kiritish;\n\nboshlang\'ich ta\'limning asoslarni o\'zgartirish.\n\nTo\'rtinchi tip. Bu tipga ko\'ra, boshlang\'ich ta\'lim jarayoniga quyidagi omillar hisobga olinib yangiliklar kiritilishi kerak:', 'Vcn6Y1tw1-M', 15, 25, '2026-11-06 09:32:35'),
(8, 1, 8, '4-Amaliyot: 1-4-sinflar uchun innovatsion kirish bosqichi dars ishlanmasini tuzish', 'practice', '# 4-AMALIYOT: 1-4-SINFLAR UCHUN INNOVATSION KIRISH BOSQICHI DARS ISHLANMASINI TUZISH\n\n### 🎯 Mashg\'ulotning asosiy maqsadi:\nNazariy bilimlarni bevosita sinf amaliyotida, simulyatsion dars bosqichlari va pedagogik keyslar orqali qo\'llash ko\'nikmalarini shakllantirish.\n\n### 📋 Amaliy ish bosqichlari:\n1. **Didaktik maqsadni belgilash:** Boshlang\'ich sinf o\'quvchilarining yosh xususiyatlariga mos vazifalar tanlash.\n2. **Interfaol metodlarni qo\'llash:** Mavzuga mos klaster, aqliy hujum, keys-stadi yoki loyiha metodini dars bosqichlariga kiritish.\n3. **Refleksiv tahlil:** Dars yakunida o\'quvchilarning o\'zlashtirish darajasini va o\'qituvchining o\'z faoliyatini xolisona baholash.\n\n### 💡 Metodik ko\'rsatma:\nUshbu amaliy mashg\'ulot M.B. Muxamadaliyeva tomonidan ishlab chiqilgan **operatsion-faoliyatli** va **refleksiv** komponentlarni rivojlantirishga qaratilgan bo\'lib, bo\'lajak o\'qituvchining darsni mustaqil loyihalay olish mahoratini oshiradi.\n', 'Vcn6Y1tw1-M', 20, 35, '2026-11-06 09:32:35');
INSERT INTO `lessons` (`id`, `module_id`, `order`, `title`, `lesson_type`, `content`, `video_url`, `reading_time_minutes`, `xp_reward`, `created_at`) VALUES
(9, 2, 9, '5-Ma\'ruza: Hozirgi davrda jahon mamlakatlari masofaviy ta\'lim tizimi', 'lecture', '5-MAVZU: Hozirgi davrda jahon mamlakatlari masofaviy ta\'lim tizimi.\n\nREJA: \n1. Rivojlangan xorijiy davlatlardagi masofaviy ta\'lim, maktab va maorif taraqqiyotining asosiy yo\'nalishlari.\n\n2.Yaponiyada ta\'lim—tarbiya va uning o\'ziga xos xususiyatlari.\n\n3. Germaniyada ta\'lim tizimini rivojlanishi.\n\n4. Buyuk Britaniyada ta\'lim tizimini rivojlanishi.\n\n5.Rivojlangan xorijiy davlatlar va mustakil o\'zbekiston Respublikasi ta\'lim tizimidagi o\'zaro uyg\'unlik masalalari. Jahonning yuksak darajada taraqqiy etgan davlatlarda ta\'lim-tarbiya ishlarining yo\'lga qo\'yilishi, maktablarda amalga oshirilganini o\'rganish orqali biz mustaqil respublikamiz milliy ta\'lim tizimlarini yangitdan tashkil qilishda, ta\'lim tarbiyada, maktab ishini tashkil etishda eskirib, o\'z dolzarbligini yo\'qotib borayotgan faoliyat shakllari va usullaridan tezroq xalos bo\'lish, uni munosib tarzda yangilashda qo\'shimcha boy manbalarga ham ega bo\'lamiz. Zotan, hozirgi zamon ta\'limida davlat va jamiyat talabi va manfaatlari aks etib turishi kerak. Ilmiy-texnika taraqqiyoti, yangi texnologik revolyutsiya sharoitida muvaffaqiyatli faoliyat ko\'rsata oladigan jamiyat a\'zolarini yetishtirib berish, yosh avlodni kasb-xunarga yo\'naltirish hamda o\'rta ta\'limning ko\'p variantli uchinchi bosqichini joriy etish, ta\'lim-tarbiya berishda eng ilg\'or pedagogik vositalarni qo\'llash, ta\'limda tashabbuskorlik va ijodkorlikka keng yo\'l ochish, uning eng maqbul tizimlarini yaratish kabi chet el tajribalarini o\'rganish maqsadga muvofiqdir. Bugungi kunda keng ko\'lamdagi islohotlarni o\'z boshidan kechirayotgan bizning ta\'limimiz uchun bu katta axamiyatga ega.\n\nKeyingi-yillarda chet el ta\'limi bo\'yicha ko\'pgina maqolalar, broshyuralar, qo\'llanmalar chop etildi, unga bag\'ishlab seminarlar, anjumanlar, o\'quvlar, uchrashuvlar o\'tkazildi.\n\nBu bizning ta\'lim tizimlarimizda, chet ellarda o\'quv tarbiya ishlarining qo\'yilishiga etibor va qiziqishning tez sur\'atlar bilan o\'sib borayotganligidan dalolatdir. Xalq ta\'limi tizimlarida chet el ta\'limini o\'rganish bilan shug\'ullanuvchi muassasalar ham tashkil topmoqda. Xalq ta\'limi vazirligidan tashqari bu masala bilan Respublika o\'quv-metodika markazida, pedagogika fanlari ilmiy tadqiqot instituti tarkibida maxsus bo\'limlar faoliyat ko\'rsatmoqda, malaka oshirish markaziy instiutida bir qator kafedralar ish bilan shug\'ullanmoqdalar.\n\nChet el ta\'limi tizimlaridan bizning mutaxassislarni voqif qilishda BMTning O\'zbekistondagi vakolatxonasi, elchixonalar, AQSHning Tinchilik Korpusi mutaxassislari, Germaniya xalqaro rivojlanish fondi, AKSELS markazi, Adenauer jamg\'armasi, Frantsiya madaniyat markazi, Britaniya Kengashi, Gyote instituti, «Silm A. SH.» firmasi, YuNESKO va YuNISEFning vakolatxonalari va boshqa ko\'plab tashkilotlar yaqindan yordam bermokdalar. Darxaqiqat rivojlangan xorijiy davlatlarda ta\'limning, mamlakat ichki siyosatiga faol tasir etadigan ijtimoiy jarayon ekanligi, e\'tirof qilingan xaqiqatdir. SHu tufayli xam chet mamlakatlarida maktab extiyojini iqtisodiy ta\'minlashga ajratilayotgan mablag\' miqdori-yildan-yilga oshib bormoqda. Yaponlarda, masalan, «maktab muvaffaqiyat va farovonlik timsoli»gina bo\'lib qolmay, «u insonlarni yaxshilaydi», degan fikr ishonch va e\'tiqodga aylangan. Ta\'lim to\'g\'risidagi g\'amxo\'rlik taniqli siyosatchilarning xam xamisha diqqat e\'tiborida bo\'lgan. SHuning uchun xam AQSHning sobiq Prezidenti R.Reyganni, Buyuk Britaniya Bosh vaziri M.Techcherni, Frantsiya Prezidenti F. Mitteranlarni maktab isloxotining tashabbuskorlari deb, bejiz aytishmaydi. F.Mitteran maktabni «Jamiyatni xarakatlantiruvchi kuch» deb xisoblagan.\n\nRivojlangan mamlakatlarda pedagogik tadqikotlarni amalga oshiradigan ko\'p sonli ilmiy muassasalar ishlab turibdi. Germaniyada ularning soni 2 mingdan ortiq. Frantsiya, AQSH, Yaponiya ta\'lim-tarbiya nazariyasi muammolari bilan yuzlab davlat va xususiy tashkilotlar, universitetlar, pedagogik tadqiqot markazlari shug\'ullanmokdalar. Ular faoliyatini esa xalkaro ta\'lim markazlari, masalan, AQSHda xalkaro ta\'lim instituti muvofiklashtirib bormokda. Ko\'pchiligining faoliyati o\'quv dasturini takomillashtirish va qayta qurishga qaratilgan. 80 —-yillardan boshlab Buyuk Britaniyada xam AQSHdagi singari o\'rganilishi majburiy bo\'lgan fanlar doirasi kengaytirildi. Ingliz tili va adabiyoti, matematika va tabiiy fanlar o\'quv setkasining yadrosini tashkil etadigan bo\'ldi. Qolgan predmetlarni tanlab olish o\'quvchilar va ota — onalar ixtiyoridadir. «Yangi dunyo»ning pedagogik g\'oyalari Frantsiya va Germaniya ta\'limiga xam sezilarli ta\'sir etayotir. Germaniya to\'liqsiz o\'rta maktablarida asosiy predmetlar bilan bir qatorda tanlab olinadigan ximiya, fizika, chet tillari kiritilgan o\'quv dasturlari xam amalga oshirilayotir.Bu o\'quv dasturi tobora to\'liqsiz o\'rta maktab doirasidan chikib, o\'rta maktablar va gimnaziyalarni xam qamrab olmokda. Yaponiya maktablari ikkinchi jaxon urushidan keyinoq Amerika ta\'limi yo\'lidan bordi. Lekin shunga karamay, bu ikki mamlakat o\'kuv dasturida bir kator farklar ko\'zga tashlanadi. Yaponiyada o\'kuv dasturlari jiddiy murakkablashtirilgan, asosiy fanlar majmui ancha keng, bir kator yangi maxsus va fakulьtativ kurslar kiritilgan. Masalan, umumiy ta\'lim maktablarining yangi musika ta\'limi o\'quv dasturiga milliy va jaxon mumtoz musikasini o\'rganish xam kiritilgan. Shuni ta\'kidlash lozimki, iktisodiy rivojlangan davlatlarda 60-80-yillarda tabiiy ilmiy ta\'lim dasturi tarkybiga fizika, ximiya, biologiya, bazi xollarda astranomiya, geologiya, mineralogiya, fiziologiya, ekologiya elementlari kiritilib, u AQSH va Frantsiyada 4-yil, Buyuk Britaniyada 6-yil, Germaniyada 2-yil o\'kitiladi. O\'kuv predmetlarini integratsiyalash jarayonida yangi-yangi kurslar paydo bo\'la boshladi. Frantsiyada 70-80-yillarda to\'liksiz o\'rta maktablar o\'kuv dasturidagi tabiiy-ilmiy va gumanitar turkumiga eksperimental, iqtisodiy gumanitar kurslar kiritiladi. Hozirgi paytlarda rivojlangan mamlakatlar o\'kuv dasturiga integratsiyalashtirilgan kurslarni kiritish to\'la amalga oshirildi. Frantsiya maktablarida ularga 6-10 foiz, Buyuk Britaniya maktablarida 15 foiz o\'quv soatlari ajratildi. Maktablarda amalga oshirilayotgan isloxotlar ta\'lim ishini tabaqalashtirish muammolarini keltirib chikardi. Iqtisodiy rivojlangan xorijiy mamlakatlarda ta\'limni tabakalashtirish eng dolzarb masalaga aylangan. ukuvchilarni tabaqalashtirib o\'qitish xorijiy mamlakatlarda asosan boshlang\'ich ta\'lim kursidan keyin amalga oshiriladi. Masalan, Frantsuz pedagoglari ta\'lim jarayonida sinf o\'kuvchilarini uch tabakaga ajratib o\'qitishni afzal ko\'radilar.\n\nBular quyidagilar:\n\n1.Gomogenlar — matematika va gumanitar yo\'nalishda ish olib borsa bo\'ladigan o\'kuvchilar. \n2.Yarim gomogen — tabiiy turkumdagi fanlarni o\'zlashtira olishga moyil o\'kuvchilar. \n3.Gegeron — barcha predmetlarni xar xil saviyada o\'zlashtiradigan o\'quvchilar va xokazo. \nTabaqalashtirish jarayoninig yangi muxim yo\'nalishi to\'ldiruvchi ta\'limni rivojlantirish bo\'lib qolmokda. To\'ldiruvchi maktablar paydo bo\'lishining sababi, AQSH va G\'arbiy Yevropada o\'zlashtirmovchi xamda ulgurmovchi o\'quvchilarning ko\'payib borayotganligi, funktsional savodsizlik avj olayotganligidir. 80 —-yillarda AQSH o\'quvchilarinig 50 —-yillarga nisbatan reyting ko\'rsatkichi 973 dan 893 ga tushdi. Fransiyada har uch litseychidan biri bu salbiy xolatni bartaraf etish to\'ldiruvchi ta\'lim zimmasiga tushadi. To\'ldiruvchi ta\'lim maktabgacha tarbiya muassasalarida, maktab va litseylarda amalga oshirilmoqda. AQSH da bu xizmatga ommaviy axborot vositalarinig imkoniyatlari xam safarbar etilgan, Milliy telekompaniya maxsus o\'quv kanali orqali 130 soatlik o\'quv ko\'rsatuvlari tashkil etildi. O\'quv jarayonlarini tabaqalashtirib olib borish bo\'yicha chet mamlakatlarining ko\'pchiligida tadqiqotlar davom ettirilmoqda. Rivojlangan davlatlarda iqtidorli bolalarga e\'tibor tobora ortib bormoqda.\n\nKeyingi davrlarda o\'z tengdoshlariga nisbatan qobiliyatda bir necha barobor ilgarilab ketgan bolalar ko\'plab topilmoqda. Ular o\'kuvni juda erta boshlab ta\'lim kurslarini o\'zlashtirishda katta shov — shuvlarga sabab bo\'ladigan darajada muvaffaqiyatlarga erishadilar. \nShunday iqtidorlar maktabi G\'arbda 60-yillardayoq paydo bo\'lgan edi. Bunday maktablarning o\'kuv dasturlari bolalar qobiliyati va imkoniyatini to\'la ro\'yobga chiqarishni ta\'minlab berish darajasida murakkab tuzilgan. Iqtidorli bolalarga qarama - qarshi qutbda turgan aqli zaif o\'quvchilarning taqdiri xam chet ellik xamkasblarni tobora tashvishlantirmoqda, bunday xolni kelib chiqish sabablarini o\'rganish, oldini olish bo\'yicha ko\'pgina profilaktik ishlar olib borilmoqda va ular uchun maxsus maktablar ochilmoqda. Lekin statistik ma\'lumotlar bunday bolalar soni tobora oshib borayotganligini ko\'rsatayotir.\n\n70--yillarda AQSH da kelajak maktabi umummilliy loyixasini amalga oshirishga kirishildi. Bu eksperiment mazmuni o\'qituvchi buyrug\'i bilan ish tutish, ko\'proq o\'quvchilarga mustaqil ishlash imkoniyatini berishdan iborat. Ta\'lim tarkibi sinfda ishlash, mustaqil mashg\'ulot, o\'qituvchi konsulьtatsiyasini o\'z ichiga oladi. \nGermaniya maktablarida sinfda o\'quvchilar sonini kiskartirish sari yo\'l tutilgan. Bunday o\'quvchilarning xar biriga individual paketlar (topshiriqlar) tarqatiladi. Toshiriqlarni o\'quvchi mustaqil bajaradi, lozim bo\'lganda u o\'qituvchidan konsulьtatsiya oladi.\n\nYuqorida bayon qilinganlardan ko\'zda tutilgan maqsadlari:\n\n-maktablarning insonparvarlik, umuminsoniylik yo\'nalishlarinikuchaytirish. \n-o\'quvchi shaxsini shakllantirishning eng samarali yo\'llarini qidirib topish. \n-tarbiyaning yangi formalarida- o\'quvchilar kengashi, maktab kengashlaridan, tarbiyaviy o\'yinlardan foydalanish.\n\n-Maktab o\'kuv dasturlarini ixtisoslashtirish, fanlarning o\'zaro aloqasini mustaxkamlash, takomillashtirish.\n\n-Maktabni mehnat, insoniy faoliyat bilan yakinlashtirish, kasbga yo\'naltirish ishlarini qayta tashkil etish.\n\n-Tabaqalashtirib o\'qitishni yo\'lga qo\'yish, maxsus o\'kuv muassasalarini (ham talantlar, ham aqliy, jismoniy zaif o\'quvchilar uchun) rivojlantirish.\n\n-Yangi, ya\'ni o\'quv texnik vositalarini ta\'limdagi salmogni oshirish, o\'qituvchilar korpusida kompyuter ta\'limini yo\'lga ko\'yish.\n\n-Pedagogik g\'oyalarni amalga oshirishda keng qamrovli eksperiment — tadqiqotlarni amalga oshirishdan iboratdir.\n\nCHet el ta\'limidagi bunday ibratli jihatlarni Vatanimiz ta\'lim tizimlarida qo\'llash yosh, mustaqil Resublikamizda o\'quv — tarbiya ishlarini islox qilish jarayonini tezlashtiradi.\n\n2. Yaponiyada ta\'lim — tarbiya va uning o\'ziga xos xususiyatlari. \nYaponiya ta\'limining shakllanishi 1867 —1868-yillarda boshlangan. Yaponiya o\'z oldiga ikki vazifani: birinchi — boyish, ikkinchi - G\'arb texnologiyasini Yaponiya ishlab chiqarishiga kiritish masalasiin qo\'yadi va bu ishni amalga oshirish uchun birinchi galda ta\'lim tizimini tubdan o\'zgartirish kerakligi aytildi. \n1872-yili «Ta\'lim haqidagi qonun» qabul qilindi. Bunda Yapon ta\'limi G\'arb ta\'limi bilan uig\'unlashtirildi. 1908-yilda Yaponiyada boshlang\'ich ta\'lim majburiy 6-yillikka aylantiriddi. 1893-yili kasb yo\'nalishidagi dastlabki kollej paydo bo\'ldi. \n1946-yili qabul qilingan Konstitutsiya fuqarolarning ta\'lim soasidagi huquq va burchlarini belgilab berdi. Unda barcha bolalar bepul umumiy ta\'lim olishlari belgilab ko\'yilgan. \nYaponiyada hozirgi zamon ta\'lim tizimlarinig tarkibi quyidagicha: Bolalar bog\'chalari, boshlang\'ich maktab, kichik o\'rta maktab, yuqori o\'rta maktab, oliy ta\'lim tizimlariga kiruvchi o\'quv yurtlaridan iborat.\n\n3.Germaniyada ta\'lim tizimini rivojlanishi. Ta\'kidlab o\'tish joizki , Germaniyaning bozor iqtisodiyotga o\'tish yo\'li bizning Respublikamizdagiga o\'xshab ketadi. Ikki German davlati birlashgandan keyin sobik Germaniya Demokratik Respublikasida ta\'limni isloh kilish bo\'yicha olib borilayotgan ishlar ham bizning sharoitimizga makbul keladi. Germaniyaning hozirgi davr maorifidagi asosiy muammosi sobik GDRdagi ta\'limni bir xil milliy me\'yorga solishdan iboratdir. Avvalambor shuni ta\'kidlash kerakki, Germaniyada ta\'lim davlat va jamiyat tomonidan ardoklanayotgan soha bo\'lib, u mamlakatning iqtisodiy jihatdan taraqqiy ettan mamlakatlar ichida kuchli oltilikka kirgan. Germaniya ta\'lim tizimlarining bayoni kuyidagicha: Germaniyada ta\'lim tizimi: Maktabgacha tarbiya tizimi Germaniya ta\'lim tizimida ham muhim 60S15ICH hisoblanadi. Uning 100-yildan orti15 tarixi bor. Bolalar bogchalari ta\'limning kuyi bosqichi hisoblansada, lekin u davlat tizimi tarkibiga kirmaydi. Bog\'chalarni mablag\' bilan ta\'minlash turli jamoat tashkilotlari, hayriya birlashmalari, korxonalar, hususiy shaxslar, diniy muassaslar zimmasidadir. Ota-onalar bolalar bog\'chalariga o\'z farzandlarini tarbiyalanganliklari uchun ancha mikdorda pul to\'laydilar. 3 yoshdan 6 yoshgacha bolalarning 80% bog\'chalarga qatnaydi. Germaniyada odatda bolalar bog\'chada tushgacha tarbiyalanadilar. Kunning yarmida esa uyda, oilada bo\'ladilar. Germaniyada kuni uzaytirilgan bog\'chalar ham bor. Majburiy ta\'lim 6 yoshdan 18 yoshgacha bo\'lgan bolalarga tegishli. Bu jarayon 12-yil davom etadi. Bundan 9-yillik (ba\'zi joylarda 10-yil) maktabda to\'la xaftalik o\'kishni bitiradi, keyin hunar-texnika bilim yurtida to\'la bo\'lmagan haftalik o\'kishda o\'qiydi. Uqish davlat maktablarida tekin. Maktab o\'quvchilariga o\'kuv ko\'llanmasi, asosan darsliklar tekin ta\'minlanadi. ^ususiy maktablar ozrok. O\'tsyash 6 yoshdan boshlanib, 4-yil davom etadi (fakat Berlinda 6-yil). Boshlang\'ich maktabdan so\'ng o\'quvchilar yo\'nalish bosqichidagi maktabga o\'tadilar. Bu yerda 5-6 sinf bosqichdagi yo\'nalish maktablarda maxsus dastur asosida o\'qiydilar. Keyin navbatdagi maktab tipiga ko\'chadilar: Bular: -asosiy, maxsus maktab, real bilim yurtlari. Deyarli 30% bola asosiy maktabga o\'tadi. 9 yoki 10-yillik o\'kish tugatilgandan keyin kasbiy tayyorgarlikka o\'tiladi. Maxsus maktablarda nuqsonga ega bo\'lgan bolalar o\'kiydi. Real bilim yurtlari asosiy maktab va yuqori maktabi o\'rtasida turadi. Qoidaga ko\'ra bu yerda o\'kysh b-yil davom etadi (5-10 sinfgacha) va to\'la ma\'lumot berish bilan tugallanadi. Bilim yurtini tugatganlar o\'rta maxsus o\'kuv yurtiga yoki yuqori bosqichdagi hunar-texnika maktabiga kirib o\'$ksh hukukiga ega bo\'ladi. germaniyada gimnaziyalar ham mavjud. Ular 5-13 sinflarni o\'z ichiga oladi. 11-13 sinflar oliy o\'kuv yurtlariga tayyorlash vazifasini ham bajaradi. \n Rivojlangan xorijiy davlatlardagi ta\'lim-tarbiya va maktab xaqida yuqorida \nbayon qilingan eng yaxshi tajribalarni o\'z ta\'lim tizimidagi o\'zaro ta\'lim tizimlarimizda joriy qilish Respublikamiz uz mustaqilligini qulga kiritgandan keyin boshlandi. Bu soxada bizga YuNISEF, YuNESKO kabi Xalqaro tashkilotlar, xorijiy davlatlarning o\'zbekistondagi elchixonalari amaliy yordam bermoqdalar. Respublikamizdagi ta\'lim muassasalari ta\'limni takomillashtirish bo\'iicha xorijiy davlatlar bilan xamkorlikning barcha shakllaridan foydalanayotirlar. Respublikamiz Oliy majlisining 1 - chaqiriq 1X-sesiyasida ta\'limga oid ikki muxim xuyaokat — «Ta\'lim to\'g\'risida»gi Qonun va «Kadrlar tayyorlash milliy dasturi»ning qabul qilinishi mamlakat ta\'limini jaxon andozalariga, rivojlangan xorijiy davlatlardagi ta\'lim-tarbiya va maktab saviyasiga olib chiqishda ulkan voqea bo\'ldi. Bizning maktabimiz jaxonda eng ilg\'or maktablar bo\'lib qolishiga Respublika raxbariyati va xukumati tomonidan xamma shart sharoit yaratilmoqda. Bizning ta\'lim tizimlarimiz xam jaxonda e\'tirof etilgan ta\'lim tizimlaridan biridir. SHu tufayli xam AQSH, Yaponiya, Germaniya, frantsiya, Buyuk Britaniya kabi rivojlangan mamlakatlar ta\'limining ustalari bilan o\'tkazilgan uchrashuvlar va muloqotlarda Respublikamiz ta\'limi tizimiga yuqori baxo berildi. Shuni ta\'kidlash lozimki, Respublikamiz xalq ta\'limi xodimlari oldida xozirgi kunda eng muxim vazifa - mustaqil o\'zbekistonning xozirgi ta\'lim tizimlarini istiqlol ruxi bilan takomillashtirish, uni o\'zimizning mumtoz pedagogika an\'analari bilan boyitish, chet el pedagogikasidagi ilgor jixatlarni o\'zlashtirish, yangi - yangi samarali o\'quv predmetlarini ta\'lim tarkibiga kiritish bilan jaxon davlat standartlari darajasiga olib chiqishdir. Buning uchun esa bizning iqtisodiy rivojlangan xorijiy davlatlardagi quyidagi ilg\'or tajribalarni ta\'lim tizimimizda qo\'llay bilishimiz maqsadga muvofiqdir. Chunonchi:\n\nYaponiya ta\'limidagi:\n\na) bolani maktabga puxta tayyorlash\n\nb)kichkintoylar ta\'lim va tarbiyasiga ota-onalar mas\'uliyatini \nkuchaytirish\n\nv)o\'quvchilarni nafosat, jismoniy kamolatiga berilayotgan \ne\'tibor;\n\ng) o\'qituvchi kadrlarga yuksak talabchanlik;\n\nd) yosh talant soxiblari bilan olib borilayotgan izchil ishlar.\n\nGermaniya ta\'limidagi:\n\na)tabaqalashtirib o\'kitishga berilayotgan jiddiy e\'tibor; \nb)o\'quvchilarning mehnat ta\'limini mustahkamlash;\n\nv)kasbgayo\'naltirish\n\nFRANSIYA TA\'LIMIDAGI:\n\na) maktabgacha tarbiyadanoq o\'quvni predmetlashtirib tashkil etish; \nb)boshlang\'ich ta\'limni uch bosqichda puxta amalga oshirish; \nv) o\'quvni didaktik vositalar bilan ta\'minlashga berilayotgan kattae\'tibor; \ng) o\'kuv muassasalarining turli firmalar, kontsernlar, korxonalar \nmustahkam aloqalari va boshqa ibratli jihatlar bizning ta\'limga ham ko\'chsa, bizning pedagogikamiz olga qarab dadil qadam bosgan bo\'lar edi. Albatta, ta\'limga har qanday yangilik, o\'zgartirish jiddiy \ntahlillar, tajribalar asosida kirib keladi. «Zo\'rlab tiqishtirish» \nbizning uslubiyot emas.Ayni paytda ta\'limni bir saviyada kotib \nqolishiga ham yo\'l ko\'yib bo\'lmaydi.SHu sababli ham, har bir pedagog, \nhar bir tadqiqotchi maorifimiz uchun jon kuydiradigan, elim \ndeb, yurtim deb kuyib yonadigan bo\'lmog\'i, «o\'z shaxsiy \nmanfaatlarim uchun davlat menga nima berdi emas, balki men davlat ravnaqi uchun nima qildim» degan mulohazalar yuritadigan iqtidorli kadrlarni tayyorlashimiz kerak\n\nMustaqil ish uchun savollar\n\nMasofaviy ta\'lim nima?\n\nYevropa ta\'lim tizimining afzaliklari nimada?\n\nYaponiyada masofaviy ta\'lim qanday amalga oshiriladi?\n\nGermaniya masofaviy ta\'limi bilan o\'zbekiston masofaviy ta\'limining o\'xshash va farqli tomonlari nimada?\n\nFoydalanilgan adabiyotlar:\n\n1.Pedagogy and Practice: Teaching and Learning in SecondarySchools.\n\n2.Michael Uljens.School Didactics and Learning: A School Didactik Model Framing an Analysis of Pedagogikal Implications of Learning Theory2008-y.\n\n3.John Dewey,How we think(1910).Martin,Jay.The Education of John Dewey.(2003) Columbia University Press.Gutek Gerald L.(2009)New Perspectives on Philosophy and education .Pearson EducationInc.\n\n4.R.A.Mavlonova, O.To\'rayeva, K.M.Holiqberdiyev. Pedagogika.DarsIik T:.O\'qituvchi 2008-yil', 'LTXMBF7yBy0', 15, 25, '2026-11-06 09:32:35'),
(10, 2, 10, '5-Amaliyot: Masofaviy va raqamli ta\'lim platformalari (LMS, interfaol ilovalar) bilan ishlash', 'practice', '# 5-AMALIYOT: MASOFAVIY VA RAQAMLI TA\'LIM PLATFORMALARI (LMS, INTERFAOL ILOVALAR) BILAN ISHLASH\n\n### 🎯 Mashg\'ulotning asosiy maqsadi:\nNazariy bilimlarni bevosita sinf amaliyotida, simulyatsion dars bosqichlari va pedagogik keyslar orqali qo\'llash ko\'nikmalarini shakllantirish.\n\n### 📋 Amaliy ish bosqichlari:\n1. **Didaktik maqsadni belgilash:** Boshlang\'ich sinf o\'quvchilarining yosh xususiyatlariga mos vazifalar tanlash.\n2. **Interfaol metodlarni qo\'llash:** Mavzuga mos klaster, aqliy hujum, keys-stadi yoki loyiha metodini dars bosqichlariga kiritish.\n3. **Refleksiv tahlil:** Dars yakunida o\'quvchilarning o\'zlashtirish darajasini va o\'qituvchining o\'z faoliyatini xolisona baholash.\n\n### 💡 Metodik ko\'rsatma:\nUshbu amaliy mashg\'ulot M.B. Muxamadaliyeva tomonidan ishlab chiqilgan **operatsion-faoliyatli** va **refleksiv** komponentlarni rivojlantirishga qaratilgan bo\'lib, bo\'lajak o\'qituvchining darsni mustaqil loyihalay olish mahoratini oshiradi.\n', 'LTXMBF7yBy0', 20, 35, '2026-11-06 09:32:35'),
(11, 2, 11, '6-Ma\'ruza: Boshlang\'ich ta\'lim fanlarini o\'qitishda zamonaviy pedagogik texnologiyalar', 'lecture', '4-MA\'RUZA. BOSHLANG\'ICH TA\'LIM FANLARINI O\'QITISHDA INNOVATSION YONDASHUV.\n\nRespublikamizda olib borilayotgan ta\'lim-tarbiya islohotlari, mutaxassis kadrlar salohiyotini oshirishga qaratilgan bo\'lib, oliy o\'quv yurtlarida pedagoglarning metodik mahoratini oshirish muhim ahamiyat kasb etadi. O\'qituvchilarimiz bu vaziyatdan chiqishda ularni o\'z faoliyatiga tanqidiy yondashib, psixologik jihatdan qayta ko\'rib chiqib, ularni yangi sharoitda bolalarga samimiy munosabatda bo\'lish, ularni rivojlantirishda shaxsiy yondashuv, hamkorlik, hamijodkorlik, individuallashish asosida, ularni ta\'lim - tarbiya jarayoniga motivatsiya hosil qilish orqali ta\'lim jarayonida faol ishtirokini taminlashga barcha kuchlarini va etiborlarini qaratishni talab etadi. Agar o\'qituvchi o\'zining faoliyatni kuzatib borsa, tahlil qilsa, o\'ziga baho bera olsa, o\'z faoliyatiga tuzatishlar, yangiliklar kirita olish imkoniyatiga ega bo\'ladi. Shu sababli ham respublikamizda interfaol metodlarni o\'quv jarayoniga qo\'llash keng joriy etilmog\'i kerak. Bu o\'z navbatida o\'quv jarayonini insonparvarlashtirish, demokratiyalashtirish, liberilizatsiyalashni tashkil etishni taqozo etmoqda.\n\nQisqa qilib aytganda, o\'quv jarayoni markazida o\'quvchi shaxsi, uning extiyoji bo\'lmog\'i lozim. O\'quv jarayoni uning hoxish, istagiga qaratilgan, yo\'naltirilgan bo\'lmog\'i talab etiladi. SHaxsga qaratilgan ta\'lim o\'quvchini o\'quv – biluv faoliyatini tashkil etishning harakatlantiruvchi, qiziqish, extiyojini, hoxish, istaklarini ro\'yobga chiqaruvchi kuch bo\'lib xizmat qiladi.\n\nInnovatsiya: Yangilanish, o\'zgarish; Biror – bir yangilikni kiritish; Yangilikni o\'zlashtirish jarayoni.\n\nInnovatsiya – (inglizcha Innovation – yangilik kiritish) – tizim ichki tuzilishini o\'zgartirish, amaliyot va nazariyaning muhim qismi. Innovatsion jarayonning mazmuniy tomonini o\'z ichiga oladi (ilmiy g\'oyalar va ularning texnologiyalarini amaliyotga kiritish). Demak, 30 faqatgina innovatsion jarayonlarni pedagogik tizimga bog\'lash yoki kiritish orqaligina ta\'limda yuqori darajalarga erishish mumkin. Bunda yangiliklarni sekinlik bilan, bosqichma – bosqich kiritish, uni qanchalik foyda keltirishini atroflicha o\'ylab, o\'lchab amalga kiritish maqsadga muvofiqdir. Innovatsiyalarni pala – partish, tartibsiz, oldindan natija olishni mo\'ljallamay amalga oshirish zarar keltirishi ham mumkin. Zero, innovatsiya chuqurroq bilim olish, o\'rganish, o\'zlashtirish, keng hajmdagi bilimlarni olishga qaratilmog\'i yaxshi natijalar berishi mumkin. Bular doimiy pedagogik muammo bo\'lib kelayotgan: o\'quv – tarbiyaviy faoliyat motivatsiyasini oshirish, dars jarayonlarida o\'quv materialni hajmini oshirish, o\'quv jarayonini jadallashtirish, vaqtni tejash, ko\'proq ilg\'or metodlardan foydalanish, o\'quv – tarbiyaviy ishlarda interfaol usullardan foydalanish, ilg\'or texnologiyalarni qo\'llash, axborot – kommunikatsion texnologiyalarni joriy qilishdan iborat. Yuqori natijalar beradigan yangi g\'oyalar, yangi nazariy bilimlar beruvchi, insonni rivojlanishiga olib keluvchi, tom ma\'nodagi innovatsiyalarni yaratish, izlash, joriy etish talab etiladi. Ko\'plab umumiy va xususiy loyihalarni tahlil etib, pedagogik nazariya va amaliyotga tadbiq etilish xususiyat va holatlarini o\'rganish asosida umum pedagogik innovatsiyalarni shunday ko\'rinishda bo\'lishini belgilash mumkin: Juda yangi bo\'lmasada, doimiy faol bo\'lgan, o\'zining g\'oyasi – ahamiyati jixatdan eskirmagan, o\'quv – tarbiya jarayoni texnologiyalarini, o\'quv jarayonini optimallashtirish nazariyasi va amaliyotini; Gumannistik pedagogika va uning nazariy va amaliy jihatlari texnologiyalarini; Pedagogik tizim jarayonidagi boshqaruvlarni yangi g\'oya, yondashuvlar asosida tashkil etilishi; Yangi g\'oyalarga asoslangan texnologiyalar, axborot vositalari va ommaviy kommunikatsiyalarga suyanish kabilar kiradi.\n\nInnovatsiyani (yangiliklarni) bosh va asosiy yo\'nalishlari qilib pedagogik sistemadagi:\n\nPedagogik sistemaning bir butunligiga;\n\nO\'quv muassasalari;\n\nPedagogik nazariya;\n\nO\'qituvchi;\n\nTa\'lim oluvchilar;\n\nPedagogik texnologiya;\n\nMazmun;\n\nSHakl, metod, vosita;\n\nBoshqaruv;\n\nMaqsad va natijalarni ko\'rsatib o\'tish mumkin.\n\nCHuqur o\'zgarishlarni amalga oshirish orqali pedagogik tizimga tasir etish asosida innovatsiyani amaliyotga joriy qilish mumkin. Rus olimi YU.K.Bobanskiyning keyingi 10-yilliklar orasida fanda yangi va muhim yo\'nalish bo\'lib, innovatsion jarayon va novatsiyalar nazariyasi paydo bo\'ldi, deydi. Bu nazariya o\'qituvchining bevosita mehnat faoliyatiga bog\'liqdir. O\'quv – tarbiyaviy ishlarni takomillashtirishning yana bir yo\'li o\'quv jarayonini insonparvarlashtirishdir.\n\nDarsni insonparvarlashtirish:\n\nHamkorlik;\n\nO\'quvchiga g\'amxo\'rlik;\n\nO\'quvchini hurmat qilish;\n\nEzozlash;\n\nKechirimli bo\'lish;\n\nO\'z – o\'zini rivojlantirishga muhit yaratish;\n\nPsixologik sog\'lom muhit yaratish;\n\nIjodiy muhit;\n\nDo\'stona munosabatda ish yuritish;\n\nO\'quvchini extiyoji, qiziqishi, shaxsiy fazilati, iqtidorini, ichki imkoniyatlarini ishga solish. Umuman o\'quv jarayonida pedagogik munosabatlarni insonparvarlashtirish, demokratlashtirish, liberizatsiya etishni.O\'zining shaxsiy – kasbiy sifatlari va fazilatlarini tahlil qilishi, bu boradagi kamchiliklarni aniqlashi va ularga barham berish yo\'llarini izlashi; Pedagogik jarayonda do\'stona, samimiy muhit, hamkorlik, hamijodkorlik va g\'amxo\'rlik vaziyatda ish faoliyatini olib borish; O\'quvchi, talaba shaxsini xurmat qilish va ezozlash yo\'llarni egallashi, o\'qitish jarayonida ijodiy va qulay ijtimoiy – psixologik muhitni yaratish ko\'nikma va malakalarini egallagan bo\'lishi; O\'quvchilarni rag\'batlantirish va uni yangi metodlarini qo\'llash ko\'nikmalarini; O\'zining pedagogik va o\'quvchilarning bilish faoliyatidagi kamchiliklarga barham berishning samarali usullarini egallagan bo\'lishi kerak. Albatta, yuqoridagi ishlarni amalga oshirish ta\'lim sifati va samarodorligi oshirishni kafolatlaydi. Buning uchun o\'qituvchilarning bilimlarini va pedagogik mahoratlarini takomillashtirib borishlari doimiy, uzluksiz holda olib borilishi talab etiladi. Innovatsion faoliyatda ish yuritish uchun yuksak madaniy – insonparvarlik asosida ta\'limga yondashishi talab etiladi. Insonparvarlik pedagogikasi shaxs va uni rivojlanishiga qaratilgandir. Uning belgilari: malumotlarni egallab olish va malum doiradagi mahorat va ko\'nikmalar hosil qilish uchun texnik, jismoniy, aqliy rivojlanishiga diqqatni qaratilishidir. Mustaqil fikrlovchi va harakat qiluvchi shaxsni shakllantirishga qaratilgan kuchlarni to\'plash, har qanday hayotiy va o\'quv vaziyatlarda asoslangan qarorlarni tanlay olib, qaror qabul qila olishdir. O\'quv jarayonini qayta qurish va yo\'naltirishga zaruriy tashkiliy sharoitlarni yaratish. O\'quv jarayonini insonparvarlashtirish yondashuvi asosida haqiqiy insoniy munosabatlarni o\'rnatish orqali avtoritar pedagogikadan voz kechib borish demakdir. SHaxsga shunday muhit, sharoit yaratish kerakki, u yuqori sifatli bilim, ko\'nikma, malaka olsin va manaviy – marifiy, tarbiyaviy ishlarga befarq qolmasligi kerak. Insonparvar pedagogika maktabni o\'quvchiga moslashuvi, qulay sharoit, ijodiy muhit yaratib, “psixologik himoya” bilan taminlashni talab etadi. Insonparvarlik maktabi amaliyotini innovatsion faoliyatning aniq uslublarini ishlab chiqishni taqozo etadi.\n\nUlar:\n\nO\'quv – tarbiya jarayonini differentsiyalash;\n\nO\'quv – tarbiya jarayonlarini har bir shaxs xislat – qobiliyatlariga qarab muvofiqlashtirish;\n\nHar bir tarbiyalanuvchini uning qiziqishini rivojlantirish uchun kerakli sharoitlarni yaratib berish;\n\nGotogen sinf, sinflar va shunga o\'xshashlarni tashkil etish;\n\nO\'quv – tarbiya faoliyatni qulayligi;\n\nPsixologik xavfsizlik, o\'quvchilarni himoyalash;\n\nO\'quvchilarning kuchiga va imkoniyatlarga ishonish;\n\nO\'quvchini qanday bo\'lsa, shunday qabul qilish;\n\nTa\'lim – tarbiya muvaffaqiyatini taminlash;\n\nMaktab yo\'nalishini maqsadga qarab o\'zgartirish;\n\nInsonparvarlik ta\'limini kuchaytirish.\n\nInnovatsion, interfaol ta\'lim o\'qituvchi va o\'quvchiga doimiy ijodiy izlanish, uzluksiz o\'z shaxsini rivojlantirish, takomillashtirish imkonini beradi. Yuqorida aytganimizdek, o\'quvchi shaxsiga, uning qiziqish, hoxish, istagiga, extiyojiga qaratilmog\'i kerak. Yani ta\'limni individuallashtirishga qaratilmog\'i talab etiladi. Endi ta\'limni individuallashtirish deganda nimani tushunish kerak? degan savolga javob beraylik. Demak, ta\'lim – tarbiya sifati va samaradorligi o\'quvchining ta\'lim mazmunini o\'zlashtirishga yo\'naltirilgan mustaqil mutoala bilan samarali shug\'ullanishi, mustaqil fikr yuritishi va tafakkur faoliyati bilan bog\'liq. Interfaol metodlarda dars jarayonini olib borishda o\'quvchilarda quyidagi xususiyatlarning rivojlanishini ko\'rsatish mumkin: O\'quvchi o\'qitilibgina qolmay, mustaqil o\'qish, o\'rganish, ishlashga, o\'zlashtirishga o\'rgatiladi.O\'quvchilarni mustaqil ravishda tahlil qilish orqali o\'zlashtirishga, ijodiy mulohaza yuritishga, shaxsiy xulosalar asosida erkin fikr yuritishga o\'rgatiladi. Bizga yot fikrlarga qarshi fikr yurita olish, o\'z nuqtai nazarini himoya eta olish ko\'nikmalari shakllantiriladi.O\'quvchiga bilimlar tayyor holda berilmasdan, bilimlarni darsliklardan, axborot – resurs markazlaridan, internetdan, turli boshqa manbalardan izlash, topish, qayta ishlash orqali ijodiy mushohada yuritish imkoniyati yaratiladi. O\'quvchining darsliklar bilan ishlash, o\'qish, o\'rganish, konspekt yozish, qo\'shimcha adabiyotlar va manbalardan foydalanib, mustaqil o\'zlashtirish ko\'nikmalarini egallashga o\'rgatiladi. Sinfdagi barcha o\'quvchilarni o\'z qobiliyatlari darajasida o\'zlashtirishlari kafolatlanadi. O\'quvchining o\'zlashtirganligini, olgan bilimlarini kundalik hayotda, amaliy faoliyatda foydalana olish ko\'nikma va malakalari bilan belgilanadi. O\'qituvchi - o\'quvchilar interfaol metodlar asosida ishlashni o\'rganib, uni o\'z o\'quv - biluv faoliyatlariga olib kira olsalar, barcha o\'quvchilar deyarli bir xil natijalarga erishadilar. Interfaol metodda dars jarayoni tashkil etilganda: O\'quvchilarning o\'zaro faolligi oshadi, hamkorlik, hamijodkorlikda ishlash ko\'nikmalari shakllanadi. O\'quv reja, dastur, ta\'lim mazmuni, darslik, standart, meyor, qo\'llanmalar bilan ishlash malakalari shakllanadi. Ta\'lim mazmunini, matnini mustaqil mutoala qilish, ishlash, o\'zlashtirish kundalik shaxsiy ishlariga aylanadi. O\'quvchi erkin fikr bildirish, o\'z fikrini himoya qilish, isbotlay olish, tasdiqlay olishga odatlanadi. Eng muhimi o\'quv jarayonida didaktiv motivlar vujudga keladi. YAni o\'quvchining extiyoji, hoxish, istagi qondiriladi, dars qiziqarli kechayotganligi sababli, vaqt o\'tayotganini bilmay qoladi. O\'quv – biluv jarayonida o\'quvchining shaxsiy manfaatdorligi oshadi. Bu holat o\'quvchini o\'quv maqsadlariga intilishi va erishishida yuqori bosqichga ko\'taradi. Darslarni interfaol metodlarda tashkil etishning afzalliklari.\n\nO\'qitish mazmunini yaxshi o\'zlashtirishga olib keladi. O\'z vaqtida o\'quvchi – o\'qituvchi – o\'quvchilar orasida ta\'limiy aloqalar o\'rnatiladi. O\'qitish usullari ta\'lim jarayonida turli xil ko\'rinishlarda kechadi (yakka, juft, guruh, katta guruh). O\'quv jarayoni o\'qish extiyojini qondirish bilan yuqori motivatsiyaga ega bo\'ladi. O\'zaro axborot berish, olish, qayta ishlash orqali o\'quv materiali yaxshi esda qoladi. O\'quv jarayonida o\'quvchining o\'zi o\'ziga baho berishi, tanqidiy qarashi rivojlanadi. O\'quvchi uchun dars qiziqarli o\'qitilayotgan predmet mazmuniga aylanadi. O\'qish jarayoniga ijodiy yondashuv, ijobiy fikr namoyon bo\'ladi. Har bir o\'quvchining o\'zi mustaqil fikr yurita olishiga, izlanishga, mushohada qilishga olib keladi. Interfaol usulda o\'tilgan darslarda o\'quvchi faqat ta\'lim mazmunini o\'zlashtiribgina qolmay, balki o\'zining tanqidiy va mantiqiy fikrlarini ham rivojlantiradi.\n\nYangi munosabatlarning o\'ziga xos jihati an\'anaviy ta\'limdagidan farq qilib, o\'quvchitalabalarning mustaqilligi va o\'quv faoliyatini taqiqlamasdan, balki belgilangan maqsadga yo\'naltirish, o\'quv faoliyatini hamkorlikda tashkil etish, ularni faoliyatga ongli ravishda yo\'llash, biror-bir faoliyatni buyruq orqali amalga oshirmasdan, balki samarali tashkil etish orqali o\'quvchitalabalarda fan asoslarini o\'rganishga bo\'lgan qiziqishlarini orttirish, shaxsning ehtiyoji, qiziqishi va imkoniyatlarini chegaralamasdan erkin tanlash huquqini berish sanaladi.\n\nPedagogik texnologiya texnologik yondashuvga asoslanadi. Texnologik yondashuv deganda tayyor mahsulot (ishlab chiqarish texnologiyasiga o\'xshash) olish uchun ishlab chiqarish jarayonlarida qo\'llaniladigan usul va metodlar to\'\'lami tushunilib, qo\'yilgan maqsadlarga erishishda kutilgan natijalarni kafolatlaydigan usul metodlari majmuasi tushuniladi. Agar metod bilish yo\'li, tadqiqot yo\'li yoki biror faoliyatdagi ma\'lum amaliyot va nazariy bilimlar sohasini egallashni harakatlar, usullar majmuasi deb tushunsak, pedagogik texnologiyaning ta\'lim usuli, ma\'lum ma\'noda ta\'lim-tarbiya jarayonlari, vositalari, shakl va metodlari majmuasini anglatadi.\n\nPedagogik texnologiyani an\'anaviy o\'qitish metodikasidan farqlovchi belgilari ko\'\'. pedagogik texnologiya an\'anaviy metodikadan, avvalo ,maqsadlarning qo\'yilishi va unga erishishi bilan farqlanadi. pedagogik texnologiya usuli tarkibiy qismiga ta\'limning umumiy maqsadlari (o\'qituvchi va talabaning maqsadlari)ni ishlab chiqish, ta\'lim maqsadlarini nazorat (test) to\'shiriqlarida o\'tkazish, maqsadga erishish usullari kiradi.', '5jRaSgMIPmw', 15, 25, '2026-11-06 09:32:36'),
(12, 2, 12, '6-Amaliyot: \'Aqliy hujum\', \'Klaster\' va \'Insert\' metodlari asosida dars ishlanmasi', 'practice', '# 6-AMALIYOT: \'AQLIY HUJUM\', \'KLASTER\' VA \'INSERT\' METODLARI ASOSIDA DARS ISHLANMASI\n\n### 🎯 Mashg\'ulotning asosiy maqsadi:\nNazariy bilimlarni bevosita sinf amaliyotida, simulyatsion dars bosqichlari va pedagogik keyslar orqali qo\'llash ko\'nikmalarini shakllantirish.\n\n### 📋 Amaliy ish bosqichlari:\n1. **Didaktik maqsadni belgilash:** Boshlang\'ich sinf o\'quvchilarining yosh xususiyatlariga mos vazifalar tanlash.\n2. **Interfaol metodlarni qo\'llash:** Mavzuga mos klaster, aqliy hujum, keys-stadi yoki loyiha metodini dars bosqichlariga kiritish.\n3. **Refleksiv tahlil:** Dars yakunida o\'quvchilarning o\'zlashtirish darajasini va o\'qituvchining o\'z faoliyatini xolisona baholash.\n\n### 💡 Metodik ko\'rsatma:\nUshbu amaliy mashg\'ulot M.B. Muxamadaliyeva tomonidan ishlab chiqilgan **operatsion-faoliyatli** va **refleksiv** komponentlarni rivojlantirishga qaratilgan bo\'lib, bo\'lajak o\'qituvchining darsni mustaqil loyihalay olish mahoratini oshiradi.\n', '5jRaSgMIPmw', 20, 35, '2026-11-06 09:32:36'),
(13, 2, 13, '7-Ma\'ruza: Innovatsiyalarni ta\'lim jarayoniga tatbiq etish mexanizmlari', 'lecture', '7-MA\'RUZA. INNOVATSIYALARNI TA\'LIM JARAYONIGA TATBIQ\n\nETISHNING TASHKILIY PEDAGOGIK ASOSLARI\n\nReja:\n\nMamlakatimizda innovatsiyalarni joriy etishga ehtiyojlarni tug\'ilishi. Innovatsion jarayonlarning yaratilish bosqichlari.\n\nInnovatsiyalarni yaratish, to\'plash, tanlash, qo\'llash tizimini yaratilishi. Fanda o\'qituvchi innovatsion faoliyatining shakllanish bosqichlarini yaratilishi.\n\nMaktabni innovatsion boshqaruv modeli.\n\nMaktabni rivojlantirish dasturi. Rivojlantirish muhitida maktab ichki ishini tashkil etish.\n\nZamonaviy, ilg\'or innovatsion texnologiyalarni o\'zlashtirish va o\'quv jarayoniga tadbiq etish.\n\nMaktab hayotini insonparvarlashtirish, demokratlashtirish va liberallashtirish. Boshqaruv madaniyati printsiplari.\n\nTayanch so\'z va iboralar: interfaol, interfaollik, interfaol ta\'lim interfaol ta\'limga xos belgilar, interfaol ta\'lim tamoyillari, interfaol ta\'lim texnologiyalari (TT), interfaol metodlar, strategiya, grafik organayzer.\n\n“Innovatsiya” tushunchasi bundan 100-yil avval madaniyatshunoslik va lingvistikada madaniy diffuziya, ya\'ni bir madaniy arealning boshqa hududga tarqalishini asoslab berish jarayonida paydo bo\'lgan.\n\n“Innovatsion jarayonlar” tushunchasining to\'liq tavsifi XX asrning boshlarida, aniqrog\'i 1911-yilda iqtisodiyotchi I.SHumpeter tomonidan iqtisodiy tizimlardagi o\'zgarishlarni tahlil qilishning “yangi kombinatsiyasi”ni tahlil qilish jarayonida taqdim etilgan.\n\n1930-yilllarda I.SHumpeter va G.Menshlar yangi texnologiya yoki mahsulotdagi ilmiy kashfiyotni tavsiflovchi “innovatsiya” tushunchasini fanga kiritishgan. 1970-yillarda zamonaviy postindustrial dunyoning rivojlanish vektorini aniqlab beruvchi “innovatsion jamiyat” tushunchasining paydo bo\'lishi yangiliklar kiritish haqidagi fanning murakkab, keng tarqalgan sohaga aylanishiga sabab bo\'ldi.\n\nPedagogik innovatsion jarayonlar G\'arbiy Yevropada 1950-yillarda, Rossiyada \n1980-yillarda hamda O\'zbekistonda 2000-yillarda maxsus o\'rganish predmetiga aylandi. Bugungi kunda pedagogik innovatsiya ta\'lim sohasidagi innovatsion jarayonlarning uch asosiy elementi: pedagogik yangiliklarni yaratish; ularni amaliyotga joriy etish va o\'zlashtirish; qo\'llash va keng yoyishning birligi va o\'zaro aloqadorligi haqidagi fan sifatida e\'tirof etiladi.\n\nBugungi kunda esa, mazkur yo\'nalishda qator ishlar amalga oshirilmoqda. Hozirgi vaqtda Respublikamizda innovatsion loyihalar tizimining yo\'lga qo\'yilganligi, innovatsiya, innovatsion jarayon, innovatsion faoliyat, innovatsion boshqarish sohalarida qator tadqiqot ishlarining amalga oshirilganligi buning yorqin misolidir.\n\nPedagogik innovatsiya deganda, pedagogik yangiliklarni yaratish, ularning pedagogik jamoa tomonidan o\'zlashti-rilishi va baholanishi, ulardan amaliyotda foydalanish jarayonlarini o\'rganish tushuniladi.\n\nPedagogik innovatsiya bu – pedagogik innovatsiyalarning yuzaga kelishi va rivojlanishi qonuniyatlarini o\'rganadigan, shuningdek pedagogik ana\'nalar bilan kelajakdagi ta\'lim loyihalarining o\'zaro aloqadorligini ta\'minlaydigan fandir.\n\n2. Pedagogik innovatsiyaning obyekti – bu innovatsiyalarning yuzaga kelishi, rivojlanishi hamda o\'quvchilarga ta\'lim-tarbiya berishda sifat o\'zgarishlariga olib keluvchi innovatsiyalarning o\'zlashtirilishi jarayoni.\n\nPedagogik innovatsiyaning predmeti – bu ta\'lim amaliyotida pedagogik yangiliklarni ishlab chiqish, kiritish va o\'zlashtirish bilan bog\'liq pedagogik shart-sharoitlar, vosita va qonuniyatlar yig\'indisi.\n\nPedagogik innovatsiyaning maqsadi pedagogik yangilik-larni yaratilishi, ularning baholanishi hamda pedagoglar jamoasi tomonidan o\'zlashtirilishi, shu bilan birga uni amaliyotda qo\'llash va foydalanish yo\'llarini tadqiq etishdan iborat.\n\nPedagogik innovatsiyaning metodologiyasini pedagogik yangiliklarni yaratish, o\'zlashtirish va qo\'llash haqidagi ta\'limotning tuzilishi va o\'zlashtirilishiga xos bilim va faoliyat tizimi tashkil etadi.\n\nPedagogik innovatsiyaning nazariy bloklari\n\nPedagogik neologiya (ilmiy-pedagogik jarayon, uning o\'ziga xosliklari va asosiy natijalari haqidagi ilmiy va tajribaviy ma\'lumotlar tizimlashtiriladigan pedagogikadagi yangilik haqidagi ta\'limot).\n\nQiyosiy pedagogik aksiologiya (pedagogika nazariyasi va amaliyotida yuzaga keladigan pedagogik yangiliklarni baholash va o\'zlashtirishning o\'ziga xosliklarini ochib beruvchi fan).\n\nInnovatsion praksiologiya (pedagogik yangiliklarni amaliyotda qo\'llashni o\'zlashtirish).\n\n3. Pedagogik innovatsiyaning asosiy tushunchalari:\n\n1) innovatsiya;\n\n2) pedagogik yangilik, yangilik kiritish;\n\n3) innovatsion jarayon;\n\n4) innovatsion faoliyat;\n\n5) innovatsion salohiyat.\n\n“Innovatsiya” tushunchasi lotin tilidan olingan bo\'lib (in-ga, novus-yangi), “yangilanish”, “o\'zlashtirish”, “qandaydir yangilikni kiritish”, “yangini joriy qilish”, “yangilik kiritish” ma\'nolarini beradi. O\'z navbatida “yangi” so\'zi ushbu tushunchaning asosiy yadrosini tashkil etadi. Odatda¸ yangilanish tushunchasi ta\'limda ko\'p hollarda o\'zgartirish tushunchasi bilan sinonimdir. Agar ushbu o\'zgartirish keng qamrovli bo\'lsa va butun ta\'lim tizimini o\'zgartirsa, unda «islohot» tushunchasi bilan izohlanadi. Lekin barcha o\'zgarishlarni yangilik deb qarash to\'g\'ri bo\'lmaydi. CHunki yangilik o\'zida avval boshidanoq qo\'yilgan vazifalarning yangilanishini maqsad qilib qo\'yadi.\n\nPedagogik innovatsiyaning asosiy ko\'rsatkichi uning boshlang\'ich rivojiga bog\'liq bo\'lib, pedagogikadagi yangilik – bu faqatgina g\'oya, yondashuv, metod, texnologiya, shunchaki taqdim etilgan va hali foydalanilmagan holatdagi emas, balki bu innovatsion jarayonning majmuaviy va alohida tarkibiy qismidir, u esa o\'zida o\'zgaruvchan sharoitlarda va holatlarda ta\'lim-tarbiya masalalarini yetarlicha samarali hal etishni ifoda etadi.\n\nInnovatsiya esa – bu ma\'lum bir bosqich asosida rivoj-lanadigan jarayondir. U bir nechta ma\'nodagi tushunchalarni beradi:\n\n1. Innovatsiya bu – ta\'limning yangi mazmuni, shakl va metodlarini ishlab chiqish.\n\n2. Yaratilgan pedagogik tizimni joriy etish va ommalashtirish.\n\n3. Ta\'lim muassasani boshqarish va rivojlantirishning yangi texnologiyasini ishlab chiqish.\n\n4. Tajriba-sinov obyekti sifatida.\n\n5. Yaxlit pedagogik jarayonni innovatsiyalash.\n\n6. Yangiliklarning qo\'llanilish darajasini yangi mahsuldorliklar bilan o\'zgartirish bosqichi.\n\nTa\'lim sohasidagi mavjud yoki yangi ehtiyojlarni qondirish uchun pedagogik yangiliklarni yaratish, joriy etish, o\'zlashtirish va foydalanishga doir faoliyat innovatsion jarayondir.\n\nInnovatsion faoliyat – pedagogik jamoani harakatga keltiruvchi, olg\'a boshlovchi, taraqqiy ettiruvchi kuchdir. Innovatsion faoliyat – bu yangi ijtimoiy talablar bilan an\'anaviy me\'yorlar-ning mos kelmasligi, yoxud amaliyotning yangi qo\'llanilayotgan me\'yorining mavjud me\'yor bilan to\'qnashuvi natijasida vujudga keluvchi majmuali muammolarning yechimiga qaratilgan faoliyatdir.\n\nInnovatsion salohiyat deganda, alohida pedagogning va yaxlitlik-da pedagogik jamoaning yangilikni o\'zlashtirishga tayyorligi, ulardan amaliyotda foydalana olishi va kutilgan natijalarni qo\'lga kirita olishi tushuniladi. Pedagogika va pedagogik menejmentda innova-tsion salohiyat tushunchasi ikki xil tarzda talqin etiladi: keng ma\'no-da – ta\'lim muassasasining innovatsion salohiyati, tor ma\'noda – o\'qituvchining innovatsion salohiyati. Ta\'lim muassasasining innovatsin salohiyati deganda, uning o\'z-o\'zini rivojlantirishga tayyorligi, shaxsning o\'z-o\'zini rivojlantirish uchun madaniy-ta\'li-miy muhitning va shart-sharoitlarning xilma-xilligi hamda kommunikativ munosabatlarning yuqori darajasi tushuniladi. Alohida pedagog uchun esa, bu – uning shaxsidagi ijtimoiy-madaniy va ijodiy o\'ziga xosliklar yig\'indisi, pedagogik faoliyatni takomillashtirishga tayyorligi hamda buning uchun zaruriy ichki vosita va metodlarning mavjudligidir.\n\n“Innovatsiya” tushunchasi lotin tilidan olingan bo\'lib (in-ga, novus-yangi), ya\'ni tarjimasi “yangilanish”, “o\'zlashtirish”, “qandaydir yangilikni kiritish”, “yangini joriy qilish”, “yangilik kiritish”. O\'z navbatida “yangi” so\'zi ushbu tushunchaning asosiy yadrosini tashkil etadi.\n\n“Innovatsiya” tushunchasi doimo bir xil ma\'noda ta\'riflanmaydi, ko\'p hollarda u “yangilik kiritish” tushunchasi sifatida ko\'rib chiqiladi.', '5jRaSgMIPmw', 15, 25, '2026-11-06 09:32:36'),
(14, 2, 14, '7-Amaliyot: Ta\'limiy loyihalash (Project-based learning) texnologiyasi asosida dars loyihasi', 'practice', '# 7-AMALIYOT: TA\'LIMIY LOYIHALASH (PROJECT-BASED LEARNING) TEXNOLOGIYASI ASOSIDA DARS LOYIHASI\n\n### 🎯 Mashg\'ulotning asosiy maqsadi:\nNazariy bilimlarni bevosita sinf amaliyotida, simulyatsion dars bosqichlari va pedagogik keyslar orqali qo\'llash ko\'nikmalarini shakllantirish.\n\n### 📋 Amaliy ish bosqichlari:\n1. **Didaktik maqsadni belgilash:** Boshlang\'ich sinf o\'quvchilarining yosh xususiyatlariga mos vazifalar tanlash.\n2. **Interfaol metodlarni qo\'llash:** Mavzuga mos klaster, aqliy hujum, keys-stadi yoki loyiha metodini dars bosqichlariga kiritish.\n3. **Refleksiv tahlil:** Dars yakunida o\'quvchilarning o\'zlashtirish darajasini va o\'qituvchining o\'z faoliyatini xolisona baholash.\n\n### 💡 Metodik ko\'rsatma:\nUshbu amaliy mashg\'ulot M.B. Muxamadaliyeva tomonidan ishlab chiqilgan **operatsion-faoliyatli** va **refleksiv** komponentlarni rivojlantirishga qaratilgan bo\'lib, bo\'lajak o\'qituvchining darsni mustaqil loyihalay olish mahoratini oshiradi.\n', '5jRaSgMIPmw', 20, 35, '2026-11-06 09:32:36');
INSERT INTO `lessons` (`id`, `module_id`, `order`, `title`, `lesson_type`, `content`, `video_url`, `reading_time_minutes`, `xp_reward`, `created_at`) VALUES
(15, 2, 15, '8-Ma\'ruza: Bolalar jamoasida tarbiya va yagona pedagogik jarayon', 'lecture', 'Mavzu: bolalar tarbiya jamoasi va yagona pedagogik jarayon\n\n---\n\nReja:\n1.Mustaqil fikrlovchi erkin shaxsni shakllantirish ta\'lim va kadrlar tayyorlash milliy modelining asosiy maqsadi.INSERT INTO `lessons` (`id`, `module_id`, `order`, `title`, `lesson_type`, `content`, `video_url`, `reading_time_minutes`, `xp_reward`, `created_at`) VALUES
(19, 3, 19, '10-Ma\'ruza: Integratsiya — ta\'limning muhim didaktik prinsipi', 'lecture', '10-MA\'RUZA. INTEGRATSIYA – TA\'LIMNING MUHIM PRINSIPI.\n\nIntegratsiya kursi – o\'quv fanlaridan biri bo\'lib, fanlararo bilimlar (integrativ bilimlar)ni chuqurlashtirish va oshirish, ulami shakllantirisb uchun o\'rganiladi. U har xiI turlar, usullar, uslublar, fanlararo integratsiya obyektlari asosida tuzilgan. Integratsiya kurslarining sinflarga bo\'linishini turli asoslarda tahlil qilish mumkin:\n\n• maqsad va muammolar asosida;\n\n• maktab tabiiy-ilmiy tizimidagi vazifalari asosida;\n\n• qo\'shiluvchi fan tarmoqlari asosida;\n\n• integratsiya usullari va yo\'llari asosida;\n\n• o\'quv rejasidagi o\'rni asosida;\n\n• kursni o\'rganishga sarflangan vaqt asosida;\n\n• o\'quvchilar uchun qiyinlik darajasi asosida va h.k.\n\nShuni e\'tiborga olamizki, bu kurslaming mualliflari, odatda, o\'z oldilariga bir necha maqsad va muammolarni yechish masalasini qo\'yishadi, shu sababli kurslar ko\'p maqsadli, turli vazifali bo\'ladi, Ko\'p rniqdordagi dasturlar va ularni tatbiq etishga urinishlarni ko\'rib chiqib. biz bu kurslar qurilishining asosiy yo\'nalishlarini ajratamiz va ulami mohiyatiga qarab, sinflarga bo\'lishimiz murnkin.\n\nINTEGRATIV TA\'LIMNING SINFLARGA BO\'LINISHI\n\nUlami yana universa1 yoki bir necba asosiy tizim kurslarini almashtiruvchi umumiy, deb ham atash mumkin. Masalan, o\'qish, tabiat. rasm darslarini bitta umumiy fanga birlashtirish. Odatda, bunday kurslaming mualliflari tabiiy fanlar maleriallarini birlashtirib, ularni bir ma\'lum tizimga keltirishadi va o\'z kurslarini integrativ yoki kompleks (umumiy), deb alaydiLar. Ko\'rinib turibdiki, boshlang\'ich ta\'lim tizimidagi tabiiy fanlar 5 materiallarini berishda to\'g\'ri ketma-ketlikka faqat darslar tuzilishini saqlab qolibgina erishish mumkin. Ba\'zi e\'tiborli olimlar ta\'kidlaydilarki, bu an\'anaviy maktablarda ham tabiiy fanlari ketma-ket o\'rganish yo\'li bilan ham hal qilinmoqda. Bir qator olimlar boshlang\'ich ta\'limga ham darslarga ajratib o\'qitish an\'analari tarqalgan, deb hisoblashadi. Tabiiy fanlarni o\'qitishning tizim bo\'yicha davom ettirishni bekor qilish va soddalashtirish uchun ko\'pgina mualliflar gumanitar sinflar uchun umumlashtirilgan kurslar (darslar) taklif qilishadi. Bularga umumiy tushunchalar beruvchi, bolalarda tabiiy fanlarni o\'rganishga qiziqish uyg\'otish vazifasini bajaruvchi, tabiat haqida qiziqarli ko\'rinishda hikoya qiluvchi boshlang\'ich tabiiy fanlar kurslari (masalan, boshlang\'ich sinflardagi «Tabiatshunoslik») kiradi. Chegaradosh fanlar asosida tuzilgan kurslar keng integratsiyajarayoni oldingi i1miy yo\'nalishlarni bog\'lovchi yangi tabiiy fanlar va ilmiy yo\'nalishlar hosil bo\'lishiga olib keldi. Boshlang\'ich sinflarda ekologik ta\'limni kuzatib, o\'qish, tabiatshunoslik. mehnat (tabiiy materiallar bilan ishlash). rasm fanlariga ekologik mavzular kiritilgani ko\'rinadi. Bir-biriga yaqin chegaradosh fanlaming qatoriga molekulyar biologiya, biofizika, geolizika. biokimyo, astrofizika, astrokimyo kiradi. Bu fanlar asosida maktab integrativ tabiiy fanlari tuziladi. Asosiy fanlar asosida tuzilgan kurslar Zamonaviy bilimlarning har bir bo\'limini qamrab oluvchi asosiy fanlar asosida tuziladi. Ular qatoriga pedagogika, pedagogik texnologiya, pedagogik psixologiya, inson yoshi psixologiyasi. Fan rivojlanishi jarayonini o\'rganuvchi pedagogik psixologiya, fanning insonning boshqa hayot jarayonlariga bog\'liqligini o\'rganuvchi\n\n- kibernetika-boshqarish, aloqa va informatsiyani qayta ishlash\n\n- informatsiyaning tuzilishi va xususiyatlarini, uning shaxs shakllanishidagi o\'mini o\'rganuvchi informatika.\n\nInson hayotining turli jarayonlarida ilmiy yo\'nalish bo\'lgan tizimlarning aloqalarini o\'rganuvchi sinergetikaning qo\'llanilishi. Bu sinfdagi integrativ kurslaming mazmuni shu fanlar ma\'nosi va strukturasi asosida tuziladi. Umumiy Hmiy tusbuocbalar, qoDuaiyatlar, oazariyalar asosidagi kurslar Bu asosda integrativ kurslar yaralish haqidagi tikrlar yaxshi natijalar berdi. Muallillar orasida yuqori darajadagi umumiylikni bildiruvchi tushunchalar: “materiya”, “harakat”, “modda”, “maydon”, “energiya” va boshqalar ko\'p ishlatiladi. Qonunlar orasida sermahsuli tabiatni saqlash qonuni, odamlaming mehnat faoliyati tufayli rivojlanishi, tabiatga tuyg\'u bilan qarash bo\'ldi. Nazariyalar orasida integrativ kurs yaralish uchun asos bo\'lib asosiy tabiiy-ilmiy nazariyalar xizmat qiladi. Shunisi e\'tiborga loyiqki, bu asosda integrativ kurslar yaratishga urunishlar ko\'p bo\'lgan bo\'lsa ham, ular qovushmaganligi va ma\'lum kelma-ketlikka, didaktik maqsadga ega emasligi bilan ajralib turadi. Fan evolutsiyasi bilan bog\'liq muammolarni, tabiatni ilmiy nuqtayi nazardan o\'rganish uslublarini, olamning ilmiy ko\'rinishini o\'rganish asosidagi kurslar yuqoridagi barcha mashqlar integrativ mazmunga ega va tatbiq etishga katta imkoniyatlari bor, afsuski, bunday kurslar maktab faoliyatida qo\'llaniluvchi material va o\'qitish uslubining murakkabligi tufayli hali keng tarqalgani yo\'q. Kompleks obyektlar asosida Integrativ kurs yaratishga asos bo\'lgan kompleks obyektlarga yer, biosfera, odam va uning yashash muhiti misol bo\'la oladi. Bu kurslaming bir xil mavzularida bir obyekt turli fan nuqtayi nazaridan ko\'riladi. Shu xildagi integratsiya o\'tgan asming yigirmanchi-yillarida maorif tizimida qo\'llanilgan. Keyinchalik u bekor qilingan, lekin bizning davrimizda, aytish mumkinki qaytadan tug\'ildi.\n\nBizning nazarimizda, ma\'lum hajmda u tabiiy fanlar ta\'limiga yaxshi ta\'sir ko\'rsatadi. Turli muammolar asosida integrativ kurslami turli lokal (mahalliy) va global (umumjahon) muammolar asosida tatbiq etishga urinishlar ko\'p uchraydi. Bunda tabiiy ilmiy bilimlarning muammolar asosida 7 birlashtirilishi qo\'llaniladi. Bu sinfdagi integrativ kurslar (asosan, ekologiya bilan bog\'liq kurslar) maktablar ish faoliyatida keng tarqalgan. • Muammolar bo\'yicha tuzilgan integrativ kurslar rivojlanishiga global ta\'limning rivojlanishi ham turtki bo\'ldi. Bu yo\'nalishning tarafdorlari zamonaviy shaxsning rivojlanishiga bugungi kunda mamlakatlarning va millatlarning ekonomika, fan, siyosat, ma\'naviyatining uzviy bog\'liqligidan kelib chiquvchi globalik omili kuchli ta\'sir ko\'rsatadi, degan tasdiqlashni asos qilib olishgan. Faoliyat asosida tabiiy fanlar asosini o\'rganishda o\'quvchilar kitob bilan ishlash, kuzatishlar olib borish, tajribalar o\'tkazish, olingan bilimlami bir tizirnga solish-turli o\'quv-ta\'lim ish faoliyati bilan to\'qnashadi. O\'quvchilami faoliyatning bir turi bilan tanishtiruvchi bir butun kurs yaratish maqsadga muvofiqdek ko\'rinadi. U o\'qitish jarayonining har bir vaqtida foydali bo\'lishi mumkin va kichik hajmda ham tabiiy fanlami o\'qitishda, o\'quvchilaming ortiqcha kuch sarf qilishlari muammosini hal qilishda, mustaqil bilim olish ko\'nikmalarini rivojlantirishida yordam beradi. Bu sinfdagi integrativ kurslami yaratish va ularni o\'quv jarayoniga tatbiq qilish bugungi kunda muhim ahamiyat kasb etadi. Tabiiy fanlami o\'zlashtirishni tekshirishlar natijalari shuni ko\'rsatadiki, o\'zbek o\'quvchilari chet ellik tengdoshlarga nisbatan ko\'p ma\'lumot o\'zlashtirishsa ham, uni tatbiq qilishda sezilarli darajada orqada qolishadi. Ko\'pchilik bunga sabab, asosiy ko\'nikmalaming moslashtirilmaganida deb biladi. Balki, uzoq vaqt davomida an\'anaviy maktabda integrativ darslarga e\'tibor berilmaganidadir? Bu yerda bugungi kungacha yaratilgan integrativ kurslaming asosiy sintlari sanab o\'tildi. Lekin o\'quv fanlarini integratsiyasi jarayonida qator kamchiliklar ham bo\'lishi mumkin.\n\nBirinchidan. Aytib o\'tilgan tabiiy integrativ kurslami tuzish yo\'llari kO\'pincha bir-birini takrorlaydi va birga qo\'llaniladi, bu bilan yangi asoslar yaratilib, ulami tartibga keltirish, ilmiy asos yaratish qiyinlashadi.\n\nIkkinchidan. Integrativ kurslar fanlararo aloqaning o\'mini bosa olmaydi. Bizning fikrimizcha, ular bu aloqaning tashkil etuvchilaridan biri.\n\nUchinchidan. Tabiiy i1miy ta\'timning qulay tuzitishi shundayki, integrativ kurslar o\'quv rejasining o\'zgaruvchan qismiga kirib. uning regional tashkil etuvchisi hisoblanadi.\n\nTo\'rtinchidan. To\'liq o\'quv-metodik qo\'llanmalarning yo\'qligi integrativ kurslaming o\'quv jarayoniga tatbiq etilishida qiyinchiliklar tug\'diradi. Ulaming mualliflari dastur tuzib. umumiy metodik ko\'rsatmalar tuzishgandan so\'ng to\'xtab qolishadi.\n\nBeshinchidan. Integrativ kurslar uchun o\'qituvchilarni rejati va maqsadga muvofiq tayyorlash tizimi hali takomillashgani yo\'q.\n\nFANNI O\'QITISHDA INTEGRATSIYA ASOSIDAGI TA\'LIM FALSAFASI\n\nSo\'nggi o\'n-yilliklar ichida ta\'tim falsafasi shunday i1miy yo\'nalishga aylandiki, u insonning ta\'lim olish jarayonida yaxlit intellektual rivojlanishi borasidagi savolga javob taklif etmoqda. Ta\'lim olayotgan yosh insonning rivojlanish sharoitidagi qarama-qarshilikni amaLiyotdagi pedagoglar aniqlashgan. Fan o\'qitishdagi integratsiya bo\'yicha ularning taklifi tashqi birikish xarakteriga ega, aslida esa fanlami integratsiyalashni chuqur metodologiya asosida o\'tkazish zarur. Yangi rivojlanayotgan fan mazmunida turli falsafiy oqimlarda paydo bo\'lgan g\'oya va metodlar birlashuvi ehtimoli bor. Ta\'lim falsafasi tomonidan nafaqat tabiiy moslashuv, balki kontinental moslashuv ham o\'zlashtirilmoqda. Olimlardan T. Kun va V.S. Stopin bu boradagi ishlari natijasida falsafa tabiat va madaniyat haqidagi fanlarni birlashtirdi. Shunday qilib. fizika modellariga zamonaviy inson ongi murojaat etuvchi ilg\'or fanga aylandi. XX asr o\'rtalarida ilg\'or fanlar orasida kibernetika yuqori o\'rin egalladi. Kibernetikada o\'zlashtirilgan prinsiplar o\'z qo\'lIanishini anorganik olamdagi hodisalami tushuntirishda biologiya, texnikada topdi. Noklassik fizikadagi N. Boming qo\'shimchalilik prinsipi avval olimlar tomonidan umumiy tabiat qonuniyatlarini ifodalovchi falsafiy prinsip, deb aniqlangan edi. Bu esa kelgusida boshqa fanlar rivojlanishiga asos soldi. Qonuniyatlar majmuasi shakllanish vaqtiga kelib. fan ko\'p qirrali bo\'la boshlaydi, inson tasviri ko\'proq gavdalanadi. Integratsiya jarayonini kuchaytirishga, insoniyat tajribasini tartiblashtiruvchi madaniyat toifalarini izlashga zaruriyat tug\'i1adi. Zamonaviy falsafa taqdim etgan integratsiyaning poy devor tarkibiy elementlariga dunyoqarash mukammalligi kiradi. Ular ma\'noni anglash, tushunish va insonning dunyoni ko\'rish usulini belgilaydi. Yosh insonning ijtimoiylashuviga maorif tizimi yordamida ushbu madaniyat turiga kiritish unda dunyoqarash mukammallik.larini o\'zlashtirishga sharoit yaratilganda erishish mumkin. Individni madaniyatga kiritish, shaxsni shakllantirish uchun dunyo manzarasini to\'liq o\'zlashtirishni taqozo etadi. Mukammalliklar asosidagi matritsalar turli aniq faoliyat, bilim, ideal, shaklga asos bo\'ladi. Dunyoqarash mukammalliklar tizimi dunyoni umumiy ta\'riflovchi toifalarni o\'z ichiga oladi. Ular tabiat, ijtimoiy obyektlarga, jonli va jonsiz tabiatga, inson va uning jamiyatdagi hayotiga, ma\'naviyatiga, ongiga kiradi. Universal toifalar universal qo\'lIanish imkoniga ega. Bu toifalar: kenglik, vaqt, harakat, miqdor, sifat, sabab, tasodif, shaxs, inson, jamiyat, men, boshqalar, ong, go\'zallik, ishonch, adolat, erkinlik va h.k. Bo\'limlarga bo\'lingan ta\'lim mazmunidagi mukammalliklar uning barcha qonuniyatlarini qamrab olishi lozim. Mukammalliklaming integratsion ahamiyati madaniyatning barcha yo\'nalishlarida namoyon bo\'ladi. Ulamihg o\'zlashtirilishi istalgan fanni o\'rganishda o\'zini ko\'rsatadi. Ular yordamida madaniyat, ijtimoiy tajriba insondan insonga, bir avloddan ikkinchisiga o\'tadi. Madaniyat mukammalligi ushbu modelda inson ongining tuzilishi elementi shaklida aks etadi. Madaniyat mukammalligi mazmuni individ tomonidan uning ta\'lim olish jarayonida, shaxsiy shakllanishida, tarbiyasida va jamiyatdagi hayotida o\'zlashtirilishi lozim. Ular uning ichki intellektual salohiyati va tashqi olamdagi xatti-harakatining qurilish materiali bo\'lib xizmat qiladi. Ong dunyosi va amaliy dunyo bog\'liqligi falsafaning rivojlanish darajasiga qarab, unda metaforik fikrlashida aks etadi. Madaniyat mukammalligini falsafiy o\'zlashtirish bosh shaklidagi yo\'li turli ijtimoiy-madaniy yo\'lanishlarda namoyon bo\'ladi. Ta\'lim falsafasi dunyoni ma\'naviy o\'zlashtiradi. Adabiyot, madaniyat faoliyat yo\'nalishlari kabi ma\'naviy ishlab chiqarish va mukammalliklarini aniqlab berishdek murakkab jarayonlar amalga oshirildi. Farq shundaki, ta\'lim falsafasida bu hodisa professional darajada, metodologikjihozlangan tartibda ro\'y beradi. Kundalik fikrlash, ma\'naviy anglash falsafiy madaniyat mukammallikJarining birlamchi shakJida paydo qiladi. Tahliliy ishlar mobaynida universal toifalar mazmuni murakkablashadi. Bu asosda yetarli murakkab va o\'ziga xos falsafiy g\'oya komplekslari rivojlanadi. Falsafa maydonida bo\'la turib, toifalar anglash dunyosi obyektiga aylanadi. Madaniyat mukammalligi falsafiy tahlil doirasida fikriy tajribalar o\'tkazish mumkin bo\'lgan o\'ziga xos ideal obyektga aylanadi. Tabiat, jamiyat, inson o\'zining real dunyosi ma\'naviy tahlili uchun ideal obyektlar bilan ishlash zaruriyati shunga olib keladiki, bu obyekt fikrlash metodlariga bog\'liq bo\'ladi. Mukammallik anglashjarayonida moddiy ta\'sirlanishga uchraydi. Natijada paydo bo\'lgan toifa turi faqatgina ta\'siri universal toifalami aniqlashga olib kelgan haqiqatnigina aks etmay, balki fikrlashning ideal yo\'nalishini ko\'rsatadi. Hozirgi vaqtda pedagogik amaliyotda fanlararo bog\'lanish asosida ta\'lim jarayoni integratsiya yo\'llarida izlanishlar davom elmoqda. Olib borilayotgan ishning foydaliligini tan olgan holda uning xarakterini belgilab o\'tamiz. Bunday tarbiyaviy ish katta samaraga ega. Mazmun va ta\'lim maqsadi integratsiyasi bo\'yicha masala faqat ta\'lim falsafasi asosida yechish mumkin. Metodologik apparat asosidagi ta\'lim falsafasi boshida fanning ideal shakllari. universal toifalari turishi kerak. Integratsiya rusum ham, navbatdagi kompaniya ham emas. U shunday an\'analar aksiki, ular bugun inson faoliyatining barcha sohalarini ta\'riflab beradi. Bu faoliyat kengliklari o\'zgardi, davrning dolzarb muammolari tug\'ildi. Ular labiat va inson yagona tizim va bog\'liqlikda mavjudligini yodga solib, inson yashashi uchun ilmiy asoslangan foydalanishning tashkilini talab qiladilar. Zamonaviy tabiatshunoslik va texnikaning insonparvarligini, odamzod faoliyatining barcha turlarini o\'z ichiga olgan bu fanlar metodologiyasidagi o\'zgarishlar bilan bog\'lash kerak. Fanni anglash jarayonida ijtimoiy insonparvarlik, tabiiy-ilmiy, lexnik biIim metodologiyalari o\'zaro bog\'lanishda ko\'rinadi. Aynan integratsiya asosida tabiiy fanlar bioolam ko\'rsatmalaridagi, inson faoliyatini o\'rganishdagi, davming dolzarb muammolarini yechishda ko\'rinadi. Xullas, bu tafovut monosabatlar o\'zgarishida va barcha maklab talablarining umummadaniy bilimlarida namoyon bo\'ladi. Integratsiya tabiiy-ilmiy ta\'lim mazmuni insonparvarlashuvining asosiy mexanizmi bo\'lib chiqadi. Hozirgi kunda tabiiy-ilmiy ta\'lim ahamiyatini baholab xulosalash mumkinki, u tabiiy-ilmiy haqqoniylik va insonparvar ideallar birga bo\'lishiga da\'vat etadi. Integratsion yondashuv qo\'llanishi tabiatshunoslik va tevarak-atrof bilan tanishuv kursida ko\'rsatilgan. Ilg\'or g\'oya, prinsip va vazifalar bu kursning konsepsiyasi ishlanmasida bizning zamonda tabiat-inson tizimida o\'quvchilar tushunchasi asoslangan bo\'lishi kerak. Ma\'naviy ekologik tushuncha bo\'lmog\'i lozim, faqatgina tabiatga ehtiyotkorlik bilan munosabatda bo\'lish inson kelajagi xavfsizligini ta\'minlashini tushuntirmoq lozim.· Bunday yondashuvning ilg\'or g\'oyalariga birdamlik, maqsadga yo\'naltirilganlik, inson va tabiat uzviyligi, inson-tabiat tizimining samoviy belgilanganligini anglash kiradi. Prinsiplar - bu birinchidan, gumanitarlash, u tabiiy-ilmiy va gumanitar bilimlami «tabiat - inson» tizimida integrallash, ikkinchidan, tabiatdagi mavjud aloqalami o\'quvchilar anglashi orqali shaxsning shakllanishi, uchinchidan, tabiat haqidagi aniq bilimlarga tegishli o\'quvchilar fikrlash -yo\'nalishi usuli shakllanish ustuvorligi, to\'rtinchidan, kelgusi didaktik moslashuv ilmiy izlanishga mos kelgan turli sohalardan materialni tanlashdir. Vazifalarga quyidagilar kiradi: o\'quvchilarda tizimli fikrlashning orientir asosini shakllantirish tabiat birlamchiligi haqidagi qonunlar, hodisalarga oid bilimlarni shakllantirish, tabiatshunoslik qonuniyatlari, kuzatish qobiliyatlarini shakllantirish, bilimlar tizimini ishlab chiqish, aqliy mustaqillik muammolarini bilish va ulaming yechish yo\'llarini topish qobiliyatini rivojlantirish. Vazifalarga, shuningdek, tabiatni estetik qabul qilish, insonparvar ma\'naviy ideallarga ekologik fikrlash va tabiatni asrash munosabatini asos qilish kiradi. Didaktik aspektdagi bunday yondashuvning asosiy farqlari quyidagilar: chiziqli kurslar fan o\'rganishdagi mantiq tushunchalardan voz kechish; deduksiyani vaqtidan oldin ishlatish, tushunchalar shakllanishining klassik tizimidan integratsion umumlashtirishning umumiy tushunchalarni ishlatish darajasiga o\'tish; tarixiy yondashuv bilimlarini minimallashtirish tabiat obyektlarini o\'rganishda aniq dalillami o\'zlashtirishga emas, u bilan bog\'liqligini anglash. Kuzatish va xulosalar pedagogik izlanishlar shuni ko\'rsatadiki, integratsion asosda fanlami o\'rgangan o\'quvchilar predmetli o\'rgatishning chiziqli kurslarini qisqa muddatda o\'zlashtirishmoqda. Tez o\'qitish maqsad qilib olinmaganiga qaramasdan, undagi tabiat, mehnat, rasm, o\'qish sohasidagi elementlar bu fanlarni tez o\'rganishda umidli asos bo\'lib xizmat qilyapti. Pozitiv natijalar deb, dunyo haqidagi ilmiy tasavvurlaming zamonaviy darajasiga to\'g\'ri baho berish; o\'quvchi oldida olamning ko\'p o\'lchovli dunyo manzarasining dinamikada, turli bog\'lanishlarda yaratish, aylantirish; ko\'rish gorizontlarini kengaytirish, o\'zi uchun dunyoni qaytadan kashf etish, o\'quvchi bilan muloqotdagi yangi metodik shakllarni izlash; turli mutaxassislar faoliyatlari muammolarini hat etishda birlashtirish, o\'quv faoliyatida toliqishning oldini olish, yangi sifatli pedagogik natija olish, ta\'limning yangi falsafasi bo\'lishi, pedagogik jarayonining integrativ borlig\'ini aks etishga aytiladi. Integratsiyaga qarshi, fikrlar muammo tug\'ilishi xavfini yaratishi mumkin. Ayrim olimlar inlegratsiyani mexanik birikishga xavf tug\'diradi, deb hisoblashmoqda. Ta\'lim muassasalari rahbarlari ko\'pincha integratsion kursning maqsad va vazifalarini aniqlashda kerakli o\'quv dasturini tanlashda, o\'qituvchilar malakasini oshirishda qiyinchiliklarga duch kelishmoqda. Shunday qilib, integratsiya ta\'lim rivojlanishga zamin yaratgan holda har bir maktabda dolzarb muammo ham bo\'lib kelmoqda. Bu integrativ yondashuv mohiyatini tushunmaslikdan kelib chiqyapti. Ta\'lim tizim tashkilotchilari zimmasiga bu masalani to\'g\'ri yechishda katta mas\'uliyat tushayotir.\n\nTa\'lim mazmunining insoniylashtirishda asosiy mexanizm deb, integratsiyani anglash qadriyatni, ya\'ni zamonaviy maktabning rivojlanishida ilg\'or an\'analar ahamiyatini aniqlashga imkon beradi.\n\nTA\'LIM JARAYONINI INTEGRATSIYALASHNING NAZARIY ASOSLARI\n\nDidaktik olimlarning tekshiruvlarida uslubning amaliy faoliyat bilan bo\'lgani genetik tabiati ajratib ko\'rsatiladi. N.N. Skatkin, I.Y. Lemer, Y.K. AJeksyut, Y.K. Babanskiyning kuzatishlarida ta\'lim uslublariga taalluqli ikkilamchi tur belgilarining ta\'rifi beriladi. Ular uslub - ifoda, mazmun va ta\'lim usuli ekanligini isbotlab berishgan. Gegel falsafadagi uslubni mazmun harakatining shakli sifatida ko\'rsatadi. Ta\'lim jarayonida turli xil mantiqiy tizimlar orqali o\'qituvchi va u bilan birgalikda o\'quvchilar o\'z bilim, qobiliyat va ko\'nikmalarini deduksiya, induksiya, sintez, umumlashtirish, aniqlashtirish, taqqoslash shaklida ifodalashadi. Barcha mantiqiy jarayonlar uslubning mazmun bilan uzviy bog\'langan ichki tomonini tashkil qiladi. BoshJang\'ich sinflarda o\'quv jarayoni foydalanilayotgan usul, uslub va shakllarining turli tumanligi bilan ajralib turadi. Mamlakatimizda amalga oshirilayotgan yangi o\'quv rejalari va dasturlariga o\'tish davrida jamiyat va atrof-muhit o\'rtasidagi aloqalami uyg\'unlashtirish, atrof-muhitga jiddiy munosabatni o\'rnatish va shakllanish masalalari muhim ahamiyat kasb etadi. Atrof-muhitga jiddiy munosabatlar poydevori boshlang\'ich sintlarda o\'rgatiladi. Shuning uchun iqtisodiy ta\'limning natijasi maktab ta\'limning birinchi bosqichiga bog\'liq. Yangi psixologik-pedagogik tadqiqotlar kichik yoshdagi maktab o\'quvchilarining bilish faoliyatlari cheklanganligi haqida ilgarigi tushunchalarni ko\'rib chiqishga imkon beradi. Bu boshlang\'ich iqtisodiy ta\'limning barcha tarkibiy qismlarini o\'zgartirish va yangilashga asos yaratadi. Boshlang\'ich sinf o\'quvchilarining yosh xususiyatlariga javob beradigan va dars talablariga mos keladigan maqsadni aniqlash bunday yangilanishning asosiy masalasidir.\n\nXIX-XX asrlar oralig\'ida pedagogikada kichik maktab o\'quchilarining tabiiy muhit bilan tanishtirishning integratsiyalashgan kursini yaratish fikri paydo bo\'lgan. Bu fikr A.Y. Gerd, O.N. Kaygorodov, A.P. Pavlov nomlari bilan bog\'liq bo\'lib, ular boshlang\'ich maktabga atrofdagi jonli va jonsiz dunyo haqidagi bo\'linmagan kursni kirgizishni talab qilishdi. Integratsiyalashgan ta\'lim-tarbiya, fanlararo aloqalaming ayrim jihatlari mashhur pedagoglaming (Y. Komenskiy, O. Lokk, I. Gerbart, M. Pestalossi, K. Ushinskiy va boshq.), didaktiklarning (1.0. Zverev, MA Oanilov, V.N. Maksimova, S.P. Baranova, M.N. Skatkin va boshq.), psixolog olimlarning (E.N. KabanovaMeller, N.F. Talizina, Y.A. Samarina, G.1. Vergeles), metodist olimlaming (M.R. Lvov, V.G. Goreskiy, N.N. Svetlovskaya, Y.M. Kolagin, G.N. Pristupova) ishlarida ko\'rib chiqilgan. Bir qator ishlar boshlang\'ich ta\'limdagi fanlararo va fanlar ichidagi aloqalarga bag\'ishlangan. Bu muammolar o\'quv fanlarini integratsiyalashga o\'tishning yaqin rivojlanish zonasidir.\n\n(T. G. Raizayeva, G. N. Akvileva, D. I. Troytap, G. V. Baltukova, N. Y. Velenkin, N. M. Drujnina, T. S. Nazarova, I. K. Blinova, R. G. Matushova.) Boshlang\'ich maktab fanlarining integratsion aloqalari kam ishlab chiqilgan bo\'lib, qarama-qarshi ifodalangan. Bu aloqalarning mohiyati haqida olirnlar orasida qarama-qarshiliklar ko\'p.\n\nIntegratsiya atama va uslubiy nuqtayi nazardan hodisa sifatida nima ekanligini ko\'rib chiqaylik. Intergratsiya lotincha integratio - tiklash, to\'ldirish, integer - butun so\'zidan kelib chiqqan. Bu borada ikki tushunchaga egamiz:\n\n1. Tizim, organizmning alohida tabaqalashtirilgan qism va vazifalaming bog\'liqlik holatini bildiruvchi tushuncha va shu holatga olib boruvchi jarayon.\n\n2. Tabaqalashtirish jarayonlari bilan birga amalga oshirilayotgan fanlami yaqinlashtirish jarayoni. Differensiatsiya fransuzcha differentiosion, lotincha differensia - farq, har xillik, ya\'ni butunni bo\'laklarga bo\'lish, ajratish. Ta\'lim mazmunini integratsiyalash - dunyo an\'anasi (g\'oya, fikr, intilish). Integrativ yondashish turli darajadagi tizimli aloqalaming obyektiv yaxlitligini aks ettiradi (tabiat-jamiyat-inson). Integratsiya ilgari bo\'lingan qismlarni bir butunga birlashtirish bilan bog\'liq. U tizim elementlarining yaxlitlik va uyushqoqlik darajasini oshirishga olib keladi.\n\nIntegratsiyalash mobaynida bir-biriga bog\'liqlik hajmi oshadi va tartibga tushadi. shu tizim qismlaming ishlashi va o\'rganish obyektining yaxlitligi tartibga solinadi. Bu umumiy qoidalami qanday qilib maktab ta\'limida qo\'llash mumkin? Zamonaviy didaktik va metodikada ta\'kidlanishicha, o\'quvchilami o\'qitish, rivojlanishi va tarbiyasining muvaffaqiyallari ularda dunyo birligi haqida tushunchaning shakllanganligi, o\'z faoliyatlarini umumiy tabiat qonunlari asosida yo\'lga solish zaruriyatini tushunishlari, tabiatshunoslik kursida fanlararo va fanlar ichidagi aloqalami yecha olishlari bilan bog\'liq. Ta\'limdagi integratsiya o\'quv fanlari mazmunini konstruksiyalashga tizirnli yondashish orqali ko\'rib chiqiladi. Integratsiyaning turli darajalari ajratiladi: boshlang\'ich, tabiat haqidagi elementlar bilimlarni birlashtirish; oraliq - fanlar bo\'limlarini bo\'lish integratsiyasi; yakuniy - tabiatshunoslikni o\'rganish bilan bog\'liq, ta\'limning oxirgi bosqichi integratsiyasi. Shu bilan birga, tabiiy-ilmiy ta\'limini to\'liqroq va kengroq integratsiyalash imkoniyati ham inkor etilmaydi.\n\nMaktab ta\'limini integratsiyalash jarayonining psixologik asosi sifatida olim Y.A. Samarinning assotsiativ tafakkur to\'g\'risidaga flkrlari olinishi mumkin. Bu ikrlarning mazmuni shundaki, har qanday bilim bu o\'xshatish, bilimlar tizimi esa o\'xshatishlar tizimidir. Y.A. Samarin o\'xshatishlarning quyidagi turlarini ajratadi: .lokal (mahalliy, ma\'lum bir joy, narsa bilan chegaralangan); • biror tizimga tegishli bo\'lgan; • tizim ichidagi; • tizimlar orasidagi; • aqliy faoliyat darajalarini o\'xshatishlarining mos keladigan darajasiga birlashtirish xususiyatiga qarab tasniflaydi.\n\nTabiat yoki predmet haqidagi eng oddiy bilimlami hosil qiluvchi bog\'liqlikning eng soddasi ma\'um bir joy yoki tushuncha bilan chegaralangan lokal tasavvurdir. Bu bog\'liqlik boshqa bilimlardan nisbatan ajralgan, shuning uchun eng oddiy aqliy faoliyatni ta\'minlaydi. Bu kichik maktab yoshiga xos. Biron bir tizimga tegishli bo\'lgan tasavvurlar eng sodda tizimli tasavvurlardir. Ular biron bir mavzu, predmet yoki hodisani o\'rganishi asosida hosil bo\'ladi. Biron bir predmetni bilish yangi dalil va tushunchalarning tanlanishi ulami bir bilimlar bilan taqqoslanishi orqali amalga oshiriladi. Bilimlaming eng oddiy umumlashtirilishi sodir bo\'ladi, Lekin olingan bilim hamma unga yaqin bo\'lgan bilimlar bilan bog\'lansa ayni muddao bo\'lar edi. Bunda o\'quvchilaming tahlil qilish va umumlashtirish faoliyatlari vujudga keladi.\n\nTizim ichidagi tasavvurlar o\'quvchilaming butun bir fanlar tizimining bilishini ta\'minlaydi (fizikaviy, kimyoviy, biologik, bilimlar tizimi), o\'rganilayotgan fan doirasida bilimlardan keng foydalanish kuzatiladi. Tizim ichidagi tasavvurlar, vaqt, muhit, son bog\'lanishlami aks ettiradi. Predmetlararo tasavvurlar aqliy faoliyatning eng yuqori pog\'onasi hisoblanadi. Ular bilimlaming turli tizimlarini birlashtiradi, hodisa yoki jarayonning xilma-xilligini bilishiga imkoniyat beradi. Shu bilimlar asosida umumiy tushunchalar kelib chiqadi. Tizimlararo tasavvurlaming shakllanishi, ularni bilimlardan foydalanishga, ulami bir-biriga bo\'ysundirishga, bilimlar chegarasidagi bo\'shliqlikni aniqlashga imkon beradi. Bayon qilingan psixologik dalillar boshlang\'ich, to\'liqsiz o\'rta va o\'rta maktab ta\'limini integratsiyalashning asosiy xususiyatlarini aniqlash mumkin. S.P. Baranov, L.R. Bolotin, V.A. Slasteninning “Pedagogika” kitobida darslarda qo\'lIaniladigan fanlararo bog\'lanish ko\'rsatiladi, lekin integratsiyalashgan ta\'lim muammolari aks etmagan.\n\nBoshlang\'ich ta\'lim-jumallarida maktab ta\'limini integratsiyalash muammosiga katta ahamiyat beriladi. L N. Baxareva o\'zining boshlang\'ich maktab o\'quv mashg\'ulotlarini o\'lkashunoslik asosida integratsiyalash maqolasida. “Integratsiya - differensiya jarayonlari bilan birgalikda amalga oshirayotgan fanlarni yaqinlashtirish va bog\'lash jarayoni bo\'lib, yangi, butun, yaxlit bo\'limlar yaratishga yordam beruvchi, fanlararo aloqalarni amalga oshiruvchi yuqori ko\'rinishda” deb ta\'kidlaydi. O\'quv predmetlari orasida integratsiya predmetlar tizimini inkor etmaydi. Integratsiya tizimini takomillashtirish, kamchiliklarini bartaraf etish yo\'li bo\'lib, predmetlar orasidagi aloqalar va bog\'liqliklarni chuqurlashtirishga qaratilgan bunday yondashuv - differensiya va integratsiya orasidagi munosabatlami tushunishga tayanadi. Pedagogikaning maqsadi bir xil maqsad vazifalarga ega bo\'lgan turli fanlarning element va qismlarini bir bo\'limga birlashtirishga yo\'naltirilgan integratsiyani amalga oshirishda o\'qituvchilarga yordam berishdir. Ko\'p yillik kuzatishlar shuni ko\'rsatadiki, boshlang\'ich sinf o\'qituvchilari, keyinchalik esa bitiruvchilar u yoki bu fanlami o\'rganib, shu bilim, ko\'nikmalarni boshqa fanlami o\'rganishda qo\'llashga qiynalib, ularga mustaqil fikrlash, olingan bilimlarga o\'xshash yoki yangi vaziyatlarga ko\'chira bilish ko\'nikmalari yetishmayapti. Bularning hammasi boshlang\'ich sinflardagi turti fanlar bo\'yicha mashg\'ulotlarning o\'zam kelishmovchiligi tufayli sodir bo\'lmoqda. Bu holatda integratsiya bir predmet bo\'yicha bilimlarni ikkinchisiga ko\'chirish va faoliyatning almashinishi emas, balki zamonaviy fanlar integratsiyasi yo\'nalishlarini aks ettiruvchi yangi didaktik ekvivalent (mos bo\'lgan, o\'xshash, keng keladigan narsa)lami yaratish jarayonidir. Psixolog E.N. Kabanova-Millerning fikricha, “O\'qituvchiga hali uchramagan vazifa asosida bilim ko\'nikma va qobiliyatlami mustaqil ko\'chirilishi aqliy rivojlanishning muhim ko\'rsatkichidir”. U o\'zining “Boshlang\'ich sinflarda ta\'limni integratsiyalash tajribasi” ishida maktab ta\'limini integratsiyalashning muhimligiga e\'tiborini qaratgan. Ular faoliyatning turli shakllarini almashib turishi orqali o\'quvchilar charchashi va asabiylashishini oldini oladi.\n\nINTEGRATSIYANING HOZIRGI ZAMON MUAMMOLARI\n\nBoshlang\'ich maktab ta\'lim-tarbiyasini integratsiyalash muammosi nazariya uchun ham, amaliyot uchun ham muhim va dolzarbdir. Boshlang\'ich ta\'limni integratsiyalash masalasiga keyingi paytda bir qancha yondashishlar bo\'ldi: darsni ikki fan o\'qituvchisi olib borishi yoki ikki fanni bir darsga birlashtirib, uni bir o\'qituvchi tomonidan o\'tilishidan to integratsiyalangan kurslar tashkil etish, boshlang\'ich ta\'lim mazmunini tubdan o\'zgartirishgacha. Bunga maktab ham, didaktika va metodika ham tayyor emas. Hozirgi kunda asosini tabiatshunoslik bo\'yicha bilimlar tashkil etuvchi integratsiyalangan kurs yaratish muammosi dolzarb bo\'lib turibdi. Bular boshqa turdagi bilimlami jipslashtiruvchi asosiy vazifani o\'z zimmasiga oladi. Bunday yondashish anchadan beri ma\'lum va chet el maktablari tajribasida hal etilgan. Bunda so\'z faqat sinflarda emas, balki umumiy ta\'limning o\'rta va tugallovchi bo\'g\'inlarida ham bir qator fanlarning mazmunini integratsiyalash ustida bormoqda. Bu integratsiyalangan fanga tabiat va jamiyatning birligini tushunish uchun zarur bo\'lgan bir qator ijtimoiy-iqtisodiy, axloqiy-estetik g\'oya va tushunchalarni kiritish ko\'zda tutilgan. Keyingi paytda maktab ta\'limini integratsiyalash to\'g\'risida ko\'p so\'z yuritilmoqda. Olimlar va amaliyotchi o\'qituvchilar bolalarda qanday qilib dunyo to\'g\'risida yaxlit tushuncha hosil qilish va turli fanlar bo\'yicha bilimlarni yaqinlashtirish uchun bir butun dasturni tuzish to\'g\'risida bosh qotirishyapti. Bir-biriga yaqin bo\'lgan fanlarni birlashtiruvchi kurslar tashkil etish harakatlari bo\'lmoqda. Masalan, matematika va konstruksiyalash, tasviriy san\'at va badiiy mehnat. Bu kurslarning samaradorligi to\'g\'risida xorijlik pedagoglarning ko\'p-yillik ishlari natijalari bo\'yicha baholash mumkin. Zero, integratsiyalangan kurslar chet el maktablari uchun odatiy holga aylangan. Chet el tajribasi bilan tanishish shuni ko\'rsatdiki, tabiat va jamiyat haqidagi bilimlarni rivojlantirish uchun asos bo\'luvchi integratsiyalangan fanlar ko\'pgina mamlakatlaming o\'quv dasturlariga kiritilgan. Bu ekologik yo\'nalishiga ega bo\'lgan integratsiyalangan fanlar jahon hamjamiyatida o\'quvchilarda atrof-muhitga javobgarlikni shakllantirishning asosiy vositasi ekanligi to\'g\'risida xabar beradi. Hozirgi kunda integratsiyaning bir necha usullari qo\'lIaniladi. Birinchisi, bir nechta fanlami bir fanga birlashtirish. Shu masaladagi 1988-yilda chop etilgan xalqaro pedagogik tajriba yakunlariga bag\'ishlangan tadqiqot foydali manba ko\'pgina xorijiy mamlakatlar boshlang\'ich maktablarining o\'ziga xos xususiyati integratsiyalangan kurslar bo\'yicha ta\'lim bo\'lib qoldi. Kursning maqsadi bolani dunyo bilan suhbatga tortish, inson tabiat, jamiyat, fan, san\'at bilan suhbatlashishga faqat odamlar suhbatlashadigan til bilangina emas, hayvonlar, o\'simliklar tili bilan, rassomlar, musiqachilar, olimlar foydalanadigan til bilan tanishtirishdir. Kichik maktab o\'quvchisiga fikr doirasi keng bo\'lgan muloqot san\'atining boshlang\'ich savodini egallashda yordam berish muhimdir. Bu savod o\'zida odamlar bilan muloqotdan tortib (tengdoshlar, katta yoshdagilar, kichik yoshdagilar) o\'z-o\'zi bilan muloqotdan to atrof-muhitdagi hodisalar bilan muloqotni qamrab oldi. Kursning maqsadidan yana biri - o\'zi ishlayotgan olam haqida narsa va hodisalar orasidagi bog\'liqlik, o\'zaro yordam, moddiy va madaniyatning turli-tumanligi xususida keng va eng asosiysi, insonning ichki (ma\'naviy) va ijtimoiy dunyosi, olamda hukm suruvchi qonunlar (tabiiy, ilmiy, tarixiy, axloqiy) haqida tushuncha berish. Asosiy urg\'u faqat ma\'lum bilimlami egallashga emas, balki tasvirli fikrlashni rivojlantirishga beriladi. Olamning umumiy ko\'rinishi tovushlar, tasvirlar, ranglar orqali tanishtiriladi, bola esa ham dunyoni, ham o\'zini o\'rganuvchi, tekshiruvchi o\'rniga qo\'yadi. Bunda kurs ta\'limiy kichik maktab o\'quvchilarining parallel ravishda asosiy fanlarni o\'rganishlari hamda o\'rta maktab ta\'limida qulay sharoitlar yaratishga xizmat qiladi.\n\nKursning tuzilishi qanday? Kursning integrativligi uning tuzilishiga xos xususiyatlami belgilab beradi. Kurs uchun umumiy bo\'lgan bir mavzu, har chorakning asosiy mavzusida o\'z rivojini topadi. Shunday qilib, kurs asosiga qo\'yilgan g\'oyalar (fikrlar)ning gorizontal harakati amalga.oshiriladi. Xuddi shu yo\'l bilan vertikal harakat ham amalga oshiriladi (sinfdan sinfga), bunda bir mavzu bolaning o\'sishiga qarab, murakkablashib boradi. Integrativlik insonning olam bilan o\'zaro aloqalarida aks etuvchi mavzularga kiritilgan: bola idrokida noma\'lum bo\'lgan uzoq olam bilan (kosmos, yulduzlar, yer kurrasi, katta bo\'shliqlar va vaqt qadri). Yaqin olam (mikroolam, uy oldidagi hayvonlar va o\'simlik dunyosi, ona-Vatan tabiati va boshqa mamlakatlar tabiati). Insonlar olami bilan (turli mamlakatlar va madaniyatlar, sivilizatsiya markazlari, insonning inson va jamiyat bilan munosabatlari, insonning ichki dunyosi); madaniy dunyosi bilan (xalq ijodi, rassom va olimlar ijodi, ma\'naviy qadriyatlami saqlovchi odamlarning ishlari). Shu olamlar ichra sayohatning mavjudlik qonuniyatlari, tillaming o\'ziga xos xususiyatlarini ochish - kurs tizimining asosiy mantiqidir. Kurs oddiylikdan murakkablikka, bilishdan ilmga, tartibsizlikdan uyg\'unlikka, chaqqonlikdan mohirlikka va ijodga bo\'lgan harakatni taklif qiladi. Bola dunyo yaralishining «g\'ishtchalari» bilan tanishadi, olamning boshlanishga, insonning yerda paydo bo\'lishiga murojaat qiladi. So\'zlar, sonlar siri, yashil barg, qadimiy afsonalar jumboqlarini ochish yuzasidan fikrlaydi, o\'quvchi makon va zamon bo\'ylab sayohatga otlanadi. Shunday qilib, bola har kuni ochishi kerak bo\'lgan olamning go\'zalligi va turli-tumanligini his qiladi. Murakkab dunyoqarashlar ilmiy, badiiy g\'oyalar bola tushunishi uchun qulay, tasvirli mavzularda o\'z aksini topgan, ular-yil mundarijasini tuzishga imkon beradi. Bir tartibga solingan tizim shu kursning o\'ziga xos xususiyatidir. Bunday o\'yinlarga yondashish 6-10 yoshdan boshlanadi. Bu hol ularni turli o\'yin orqali murakkab bilim orttirish, badiiy, axloqiy masalalami hal qilishga yordam beradi.', 'Vcn6Y1tw1-M', 15, 25, '2026-11-06 09:32:36'),
(20, 3, 20, '10-Amaliyot: Ona tili va O\'qish savodxonligi darslarini integratsiyalash keysi', 'practice', '# 10-AMALIYOT: ONA TILI VA O\'QISH SAVODXONLIGI DARSLARINI INTEGRATSIYALASH KEYSI\n\n### 🎯 Mashg\'ulotning asosiy maqsadi:\nNazariy bilimlarni bevosita sinf amaliyotida, simulyatsion dars bosqichlari va pedagogik keyslar orqali qo\'llash ko\'nikmalarini shakllantirish.\n\n### 📋 Amaliy ish bosqichlari:\n1. **Didaktik maqsadni belgilash:** Boshlang\'ich sinf o\'quvchilarining yosh xususiyatlariga mos vazifalar tanlash.\n2. **Interfaol metodlarni qo\'llash:** Mavzuga mos klaster, aqliy hujum, keys-stadi yoki loyiha metodini dars bosqichlariga kiritish.\n3. **Refleksiv tahlil:** Dars yakunida o\'quvchilarning o\'zlashtirish darajasini va o\'qituvchining o\'z faoliyatini xolisona baholash.\n\n### 💡 Metodik ko\'rsatma:\nUshbu amaliy mashg\'ulot M.B. Muxamadaliyeva tomonidan ishlab chiqilgan **operatsion-faoliyatli** va **refleksiv** komponentlarni rivojlantirishga qaratilgan bo\'lib, bo\'lajak o\'qituvchining darsni mustaqil loyihalay olish mahoratini oshiradi.\n', 'Vcn6Y1tw1-M', 20, 35, '2026-11-06 09:32:36'),
(21, 3, 21, '11-Ma\'ruza: Boshlang\'ich maktabda integratsiyalashgan ta\'limdan foydalanish metodikasi', 'lecture', '11-MA\'RUZA. BOSHLANG\'ICH MAKTABDA INTEGRATSIYALASHGAN TA\'LIMDAN FOYDALANISH\n\nBoshlang\'ich maktabni integratsiya qilish.\n\nHozirgi kunda boshlang\'ich maktab ta\'limini integratsiya qilish haqida ko\'p gapirilayapti. Bu tushunarli - kichik maktab o\'quvchisi atrofidagi olamni bir butunligicha qabul qiladi. Uning uchun tabiatshunoslik, rus tili, musiqa va boshqa o\'quv fanlari nomi emas, balki atrofidagi olam obyektlarining tovushlar, ranglar, hajmlarning turli-tumanligi qiziqarlidir. Bolalarning tabiat va kundalik hayotdagi barcha narsalarning bog\'liqligini ko\'rishga o\'rgatish kerakligini o\'qituvchi sezadi, biladi. Shunday ekan ta\'lim integratsiyasi hozirgi zamon talabiga javob beradimi? Bu masala qanday yechilishi kerak, uning mohiyati nimada\'? Ta\'limni integratsiyalash fikri xalq ta\'limida tabaqalashtirish va individuallashtirish bilan birga muhokama qilina boshlandi. Agar kichik maktab ta\'limini tabaqalashtirish asosida kitob, darslik va boshqa adabiyotlar bilan mustaqil ishlashga tayyorgarlik darajasi hamda kichik maktab yoshida qiziqishlami faol shakllantirishni taqozo etsa, integratsiyaning asosi qilib, turli ranlami o\'rganish obyektlari bo\'lgan ba\'zi umumiy tushunchalami chuqurlashtirish, aniqlashtirish va kengaytirish mumkin. Ta\'limni integratsiyalashning asosiy maqsadi - boshlang\'ich maktabdayoq tabiat va jamiyat haqida yaxshi tasavvur asoslarini qo\'yishi va ulaming rivojlanishi qonunlariga o\'z munosabatini shakllantirishdir. Mana shuning uchun kichik maktab o\'quvchisi predmet yoki voqealik hodisalaming bir necha tomondan ko\'rish muhimdir: mantiqiy va emotsional tomondan, badiiy asarda va ilmiy ommabop maqolada, biolog, so\'z ustasi, rassom, musiqachi nuqtayi nazardan va boshqalar. Asosiy fanlami o\'zlashtirish va olamdagi bor narsalar qonuniyatlarini tushunishda predmetlar ichidagi va predmetlararo aloqalarini o\'rnatish ta\'limni integratsiyalashga yondashuvning metodik asosidir. Dunga turli darslar tushunchalariga ko\'p marta qaytish, ulami chuqurlashtirish va boyitish, shu yoshga tushunarli bo\'lgan muhim belgilami aniqlash orqali erishish mumkin. Shunday qilib, yaxshi shakllangan tuzilish va o\'tkazish tartibiga ega bo\'lgan, tarkibiga shu o\'quv predmetiga tegishli bo\'lgan tushunchalar guruhi kiritilgan har qanday dars integratsiyaga asos qilib olinishi mumkin. Lekin integratsiyalangan darsga boshqa fanlar, boshqa o\'quv predmetJari bilan bog\'liq tushunchalar tahlil qilinishining natijalari kiritiladi. Masalan, «qish», «sovuq .. , «bo\'ron\", kabi tushunchalar o\'qish, rus tili, tabialshunoslik musiqa, tasviriy san \'at darslarida ko\'rib chiqiladi. Tushunchalarning tahlil qilinishi boshqa o\'quv darslarida o\'zlashlirilgan bilimlarga murojaat qilinadigan darslar integratsiyalangan hisoblanadi. Dars ijodiy, erkin bo\'lishi bilan birga, yaxlit, mantiqan ketma-kct, o\'ziga xos o\'tish mctodikasiga ega bo\'ladi. Umumiy ta\'limning poydevorini qo\'yadigan boshlang\'ich maktabdagi ko\'p tushunchalar tabialshunoslik. rus tili, musiqa, tasviriy san\'at va boshqalar uchun umumiydir. Hozirgi kunda bir qator o\'quv prcdmetlari uchun umumiy bo\'lgan tushunchalar orasidagi aloqalarni o\'rnatish psixologik va metodik asos bo\'lgan inlegratsiyalangan darslar tizimini ishlab chiqish va sinovdan o\'tkazish lozim. Tekshirish davomida o\'quv predmetlarini integratsiyalash jarayonida faol aqliy faoliyatga yordam beruvchi omillar - integratsiyalash uchun fanlarning ma\'qul birlashishi, o\'qiluvchi va o\'quvchi harakallarining mos kelishi, bolalarning yosh imkoniyatlarini hisobga olgan holda mazmun, metod, usullarni tanlashdan iborat.\n\nINTEGRATSIYALANGAN DARSLARNING SAMARADORLlGlNI OSHIRISH OMILLARI. Avvalo, qaysi darslar inlegratsiyalash uchun mos kelishini aniqlab olish kerak. Bunday darslarning negizi - turli fanlar asosiy mavzulari mazmunining yaqinligi va mantiqiy aloqalari.\n\nIntegratsiyalangan darslar. Bu yerda taxlil jarayon kechadi:\n\na) kitob o\'qish asbobi sifatida o\'qish darslarida olgan o\'qish ko\'nikmalarini takomillashtirish;\n\nh) matn ustida ishlash;\n\nd) suhbatdoshlar doirasini tanlash\n\nBoshlang\'ich sinflarda integratsiyalangan ta\'limni amalga oshirish metodikasi Integratsiya, integratsiyalash jarayonlari zamonaviy maktabga kirib kelib, faqat uning mazmunini emas, balki kichik maktab o\'quvchilarini ekologik ta\'limining tashkiliy shakl va uslublariga ham faol kirib boryapti. O\'qituvchi bilim olish jarayonini shunday tashkil etish kerakki, unda o\'quvchilar ko\'proq mustaqil izlanishlari, o\'z harakat va faoliyatlarining oqibatlarini oldindan bilishga o\'rganishlari, bahs munozaralarda ishtirok etishlari, tabiiy va ijtimoiy muhitni yakunlashlari kerak. Shuning uchun o\'qish vaqtining yarmini o\'quvchilar tabiat va ijtimoiy muhitda o\'tkazishlari, amaliy-ijodiy va tekshirish ishlari olib borishlari kerak. Bu vazifani ta\'limning turli shakllarida bajarish mumkin: kuzatishlar, tajriba va sinovlar o\'tkazish, san\'at asarlarini qayta tiklash, modellashtirish, ijtimoiy muhitdagi o\'z harakat va faoliyatlarini natijasini ko\'ra bilish, kitob bilan ishlash. O\'qituvchi dars samaradorligini oshiruvchi, matematika, rus tili, o\'qish, tabiatshunoslik fanlarini o\'qitishning turli-tuman shakllariga ega har bir dars o\'quvchiga ilmiy bilim, tasavvur va tushunchalarning ma\'lum bir yig\'indisini berishi, hamda tarbiyalash va rivojlantirishi kerak. Dasturdagi materialni ular dars davomida o\'zlashtirishlari kerak. Bu o\'quvchilarning o\'quv mashg\'ulotlari bilan ortiqcha yuklanmasligining muhim shartidir, chunki yaxshi o\'zlashtirilgan dars uy vazifasini bajarish uchun ketadigan vaqtni ancha qisqartiradi. Bu holatda asosiy prinsip: kichik maktab o\'quvchilarining eng muhim vazifasi – o\'qish, mustahkam bilim olish, darsdagi vazifa esa o\'qituvchi boshchiligidagi mehnat. Darsga tayyorlanar ekan, o\'qituvchi birinchi navbatda uning maqsadini anglaydi va shu asosida darsning mazmuni tanlanadi, asosiy savollar belgilanadi. Bunda o\'qituvchi faqat darslik matnini gapirib berish bilan cheklanmasligi kerak. O\'quvchilarni qo\'shimcha material bilan ko\'mib tashlamagan holda, ularga kitobda yo\'q misollarni ham berib borishi kerak: turli she\'rlar, badiiy asarlardan parchalar, maqollar, topishmoqlar va boshqa materiallar o\'quvchilarda jonli qiziqish uyg\'otadi va ta\'sirlantiradi. Har bir dars mazmuni belgilanayotganda predmet ichidagi va predmetlararo aloqalar hisobga olinadi. Darsning mazmuni belgilangach o\'qituvchi qanday tasavvur va tushunchalar unda o\'z rivojini topishini, o\'quvchi qanday bilim va ko\'nikmalarga ega bo\'lishini aniqlaydi. Darsning maqsadi va mazmuniga mos ravishda o\'qituvchi ta\'lim metodlarini tanlaydi. Darsda o\'qituvchi va o\'quvchining faoliyatlari bir-biri bilan uzviy bog\'liq bo\'lganligi sababli, bu faoliyatlarning aniq bosqichlarini belgilab olish kerak. Butun dars davomida sinfning faol ishlashi uchun usul va vositalarning to\'g\'ri almashinuvini aniqlab olish kerak. Boshlang\'ich sinflarda integratsiyalashgan darslarni amaliyotda qo\'llash. 3-sinfda integratsiyalashgan dars( matematika+tabiatshunoslik) fragmenti Darsning mavzusi: Harakatga doir masala. O\'qituvchi:- keling,ko\'phadli sonlarni eslaylik. Daftaringizga quyidagi sonlarni yozing: 40204506,326925,150000000,32482.Sonlarni ortib borish tartibida o\'qing. Eng katta sonni o\'qing.Bunday katta son nimani bildirish mumkin(bolalar o\'z taxminlarini aytadilar). O\'qituvchi:- bu son yerdan- quyoshgacha bo\'lgan masofani bildiradi.Bu juda katta km lar soni,uni tasavvur qilish qiyin. Agar biz quyoshga aravada boradigan bo\'lsak,bizga 500 yil kerak bo\'lar edi. Bu necha asrga teng? Bolalar:- 5 asrga. O\'qituvchi: - odamlar avtomabilni ixtiro qildilar. Endi bu yo\'lni bosib o\'tish uchun 5 marta kam vaqt kerak bo\'ladi. Bu qancha? B: 100 yil. O\': - samolyotda esa 10 yil uchishi kerak.Bu necha oy? B:-120 oy. O\'- raketa esa, bu yo\'ni 1 yilda bosib o\'tadi.Agar yilni kun hisobida o\'lchasak, bu necha kun? B:- 366 kun Og\'zaki ish.Yer yaqinidagi orbitaga chiqish uchun bir kosmik tezlikda harakat qilish kerak.U 8km/s ga teng.Hisoblab ko\'ringchi,bu bir minutdan keyin bizning kemamiz Yerdan qanday masofada bo\'ladi? B: - 60*8=480km O\': - biz hayot sharoitlari bo\'yicha Marsga Yerdagi hayot sharoitlariga yaqinligi haqida gapirgan edik.Kemamiz Marsga yetishi uchun kema ikkinchi tezlikda harakat qilishi lozim.Ikkinchi kosmik tezlik birinchisiga qaraganda 3km/s ga ko\'p.Raketa 3 minut ichida qancha masofani bosib o\'tadi? B: - 3 min.180sek,demak masofa 1980km ga teng. O\': - biz Yerdan Marsgacha bo\'lgan masofaning qanchaligini,kema qanday tezlik bilan harakat qilishini bilamiz.Marsga yetib borish uchun qancha vaqt talab etilishini uyda mustaqil ravishda hisoblab chiqishga urinib ko\'ring. Bugungi zamonaviy darsliklarimizda ham turli xil fanlar integratsiyasini ko\'rishimiz mumkin. Bu darsliklarimiz o\'quvchilarni har tomonlama yetuk,dunyoqarashi keng inson qilib tarbiyalashga yordam beradi.\n\nFoydalanilgan adabiyotlar:\n\n1.Mavlonova R.A, “Boshlang\'ich ta\'limning integratsiyalashgan pedagogikasi”, Toshkent-2006\n\n2.T.G\'offorova. ”Boshlang\'ich ta\'limda zamonaviy pedagogik texnologiyalar” “Tafakkur nashriyoti”- 2011.\n\n3.J.Yo\'ldoshev,S.Usmonov,”Pedagogik texnologiya asoslari”, T., 2004.', 'PDLXPWO98LM', 15, 25, '2026-11-06 09:32:36'),
(22, 3, 22, '11-Amaliyot: Matematika va Tabiiy fanlar (Science) fanlararo bog\'lanishli amaliy dars ishlanmasi', 'practice', '# 11-AMALIYOT: MATEMATIKA VA TABIIY FANLAR (SCIENCE) FANLARARO BOG\'LANISHLI AMALIY DARS ISHLANMASI\n\n### 🎯 Mashg\'ulotning asosiy maqsadi:\nNazariy bilimlarni bevosita sinf amaliyotida, simulyatsion dars bosqichlari va pedagogik keyslar orqali qo\'llash ko\'nikmalarini shakllantirish.\n\n### 📋 Amaliy ish bosqichlari:\n1. **Didaktik maqsadni belgilash:** Boshlang\'ich sinf o\'quvchilarining yosh xususiyatlariga mos vazifalar tanlash.\n2. **Interfaol metodlarni qo\'llash:** Mavzuga mos klaster, aqliy hujum, keys-stadi yoki loyiha metodini dars bosqichlariga kiritish.\n3. **Refleksiv tahlil:** Dars yakunida o\'quvchilarning o\'zlashtirish darajasini va o\'qituvchining o\'z faoliyatini xolisona baholash.\n\n### 💡 Metodik ko\'rsatma:\nUshbu amaliy mashg\'ulot M.B. Muxamadaliyeva tomonidan ishlab chiqilgan **operatsion-faoliyatli** va **refleksiv** komponentlarni rivojlantirishga qaratilgan bo\'lib, bo\'lajak o\'qituvchining darsni mustaqil loyihalay olish mahoratini oshiradi.\n', 'PDLXPWO98LM', 20, 35, '2026-11-06 09:32:36');
INSERT INTO `lessons` (`id`, `module_id`, `order`, `title`, `lesson_type`, `content`, `video_url`, `reading_time_minutes`, `xp_reward`, `created_at`) VALUES
(23, 3, 23, '12-Ma\'ruza: Boshlang\'ich sinf darslarini integratsiyalash texnologiyasi', 'lecture', '12-MA\'RUZA. BOSHLANG\'ICH SINF DARSLARINI INTEGRATSIYALASH\n\nUmumta\'lim maktablarida barcha fanlarning o\'qitilishi bugungi kun o\'smirlarining ijobiy munosabatlarini shakllantirishda yordam beradi. O\'smir yoshdagi o\'quvchilaming shaxsi va ularning kamoloti muammosi taraqqiy etayotgan va o\'z taraqqiyotida yuksak cho\'qqiga intilayotgan jamiyat uchun dolzarb masaladir. Har bir o\'quv fanining o\'rganilishi, ta\'lim samarasi yuksak bo\'lishi, bolalar erkin fikrlashni o\'rganishi .... naqadar dolzarb ekanligi hech kimda shubha uyg\'otmaydi. Erkin fikrlay oladigan kishigina jamiyatda o\'z mavqeyini to\'la idrok qila oladi. Bilimdonlikning muhim qismi bo\'lgan insoniy demokratik munosabatlar tizimidagi teranlik shaxs taqdiri va salohiyatini belgilovchi muhim-omildir. Pedagogika va ijtimoiy psixologiya har bir o\'smir shaxsning hayotning barcha jabhalarida o\'zini erkin sezish va fikrlarini to\'la-to\'kis bayon etishiga o\'rgatuvchi usul sifatida xizmat qiladi. Bugungi kunda o\'smirlaming shaxslararo va ular o\'rtasidagi o\'zaro munosabatlari ma\'lum bir darajada ularni shaxsidagi psixologik holatlami o\'zgartirish va ijobiy munosabatlarni shakllantirishda yordam beradi. Maktab ta\'limining san\'at yo\'nalishi mazmuni bolalaming ta\'lim-tarbiya olishiga, odamiylik sifatlari qunt bilan singdirib borilsa, ular yetuk va barkamol, sog\'lom, mustaqil fikrlovchi shaxs bo\'lib yetishadi. Har bir yosh davrning psixologik xususiyatlarini hisobga olgan holda tarbiyaviy ta\'sir o\'tkazish bolada o\'z vaqtida o\'zini anglashni vujudga keltiradi. Bolada o\'zini anglash tuyg\'usi qancha erta uyg\'onsa, shaxsiy nuqtayi nazar, o\'z huquqini his etish, o\'zining aqliy va jismoniy imkoniyatlarini baholash shunchalik tez paydo bo\'ladi. Hozirgi vaqtda hamma fanlar, shu jumladan, politexnik sikl har tomonlama talqin qilinar ekan, shu fanlami chuqur o\'rganish va uni ijtimoiy hayotni yaxshilashda foydalanish - bugungi kunning dolzarb va kechiktirib bo\'lmaydigan masalalaridan biridir. O\'zbekistondagi shu sohadagi qarashlar, psixologik olimlarning olib borayotgan va rejalashtirilgan ilmiy-amaliy yo\'nalishdagi barcha tadqiqotlarning qimmatli ahamiyati juda kattadir. Shu bilan birga barcha yosh avlod ta\'lim-tarbiyasining buguni va ertangi kun talablari uchun zarurdir. Sharq mutafakkirlarida ilg\'or g\'oyalar - yosh avlodni aqliy va jismoniy jihatdan yetuk, ma\'rifatli, bilim va hunarlarni egallagan, odob-axloq qoidalarini o\'ziga mujassamlagan go\'zal didli hamda zavqli qilib yetishtirishdir. Bu avloddan avlodga og\'zaki ijod va yozma adabiyotlar vositasida ommalashadi. Yosh avlodni hayotga tayyorlashda ko\'p asrlar davomida qo\'llanilgan usul-vositalari, tadbir va shakllar, o\'ziga xos urf-odat va an\'analar, tarbiya haqidagi g\'oyalar va hayotiy tajriba xalq pedagogikasida mujassamlangandir. Ma\'lumki. har bir xalq boshqa xalqlar bilan bog\'liq holda yaratilgan. Shu sababli ham ulaming ijtimoiy-siyosiy va madaniy hayoti, urf-odatlari, an\'analarida o\'xshashlik mavjud. Bu o\'xshashlik ulaming mehnat va nafosat aqliy va axloqiy tarbiya usullarida yorqin ko\'rinadi. Ular har xil ish turlarida kasb egalari bo\'la olishadi. Bular quyidagi kasblardir: mexanizator, ta\'mirlovchi payvandchi, chorvador, dehqon. O\'quvchilami hozirgi zamon kasb-hunarga o\'rgatish, rnehnatkash inson psixologiyasini rivojlantiradi. Umumta\'lim maktabining vazifasi mana shulardan iborat. Ijtimoiy hayotimizdagi inqilobiy o\'zgarishlar, mustaqillik, huquqiy davlat tizimiga intilish - insonparvar psixologiya qonuniyatlari va ilrniy materiallami o\'rganish monitoringidan turmushda foydalanishga quyidagicha baho beradi:\n\n• talabalami individuallik qiyofasida shakllantirish;\n\n• ta\'lim-tarbiyani, odamiylik sifatlarini qunt bilan singdira borish;\n\n• tarbiyaviy jarayonning natijasi;\n\n• keng bilim saviyasiga ega bo\'lish, turli bilimlardan xabardor bo\'lishi;\n\n• yosh pedagogik-psixologiya, ijtimoiy psixologiya va pedagogika, yosh fiziologiyasi hamda maktab gigiyenasidan chuqur bilimlarga ega bo\'lishi;\n\n• o\'zi dars beradigan fan bo\'yicha mustahkam bilimga ega bo\'lib, o\'z kasbi, sohasida jahon fanida erishilgan yutuq va kamchiliklardan xabardor bo\'lishi;\n\n• ta\'lim va tarbiya metodikasini egallashi;\n\n• o\'z ishiga ijodiy yondashishi;\n\n• pedagogik texnikani (mantiq, nutq, ta\'limining ifodali vositalari) va pedagogik taktikaga ega bo\'lish;\n\no\'qituvchi o\'z bilimi va pedagogik mahoratini doimiy ravishda oshirib borishi barobarida har bir o\'qituvchi psixologik jihatdan ana shu talablar monitoringiga eng yuqori darajada mos keladigan bo\'lishiga intilishi lozim. Zamonaviy o\'qituvchi o\'quvchilar o\'rtasida o\'zaro munosabatlarni yo\'lga qo\'ya olish, bolalar jamoasida ijtimoiy-psixologik mexanizmlardan foydalanishni bilishi zarur. Jamiyat tomonidan qo\'yilgan talablar bilan bir qatorda o\'qituvchi o\'z faoliyatida tevarak atrofidagi kishilar, maktab ma\'muriyati, hamkasblari, o\'quvchilar va ularning ota-onalari undan nimalarni kutishni ham esdan chiqarmasligi lozim.\n\nO\'qituvchilaming pedagogik mahorati va innovatsion tayyorgarligi O\'quvchilarni tarbiyalash dasturini ishlab chiqish va uni amalga oshirish qobiliyati yetarli darajada bo\'lishi lozim. Psixologik xususiyatlarning turlari haqida hozirga qadar yosh psixologiyasi sohalari - chaqaloqlik, ilk bolalik, maktabgacha davr, kichik maktab, o\'spirinlik, yoshlik, yetuklik, keksalik davri bo\'yicha bebaho ilmiy-amaliy ma\'lumotlar to\'plangan. Endi asosiy vazifa ana shu ma\'lumotlarni ijtimoiy hayotning barcha jabhalarida qo\'llashdan iborat. Odamga chaqaloqligidan keksalik davrigacha uning ichki imkoniyati, mayli, iqtidori, aql-zakovati, qiziqish, irodasi, his-tuyg\'usi, diqqati va bilim jarayonlarining xususiyatiga ko\'ra, individual munosabatda bo\'lishi, bunga pedagogik-psixologik ta\'limning talablariga integratsion moslashuv xususiyatlaridan kelib chiqqan holda ish olib borish maqsadga muvofiqdir.\n\nBoshlang\'ich sinflarda integratsiyalashgan darslarni tashkil etish texnologiyasi o\'qitish va o\'rganishga istiqbolli yondashuvni taklif etadi, bu o\'quvchilarni XXI asr inson kapitalini shakllantirishga ko\'mak berib va ularning umumiy akademik va shaxsiy rivojlanishiga hissa qo\'shadi. Boshlang\'ich sinflarda integratsiyalashgan sinflarni tashkil etish texnologiyasi bo\'yicha tadqiqotlar bir necha sabablarga ko\'ra juda dolzarb va muhim ahamiyat kasb etadi. Shu o\'rinda boshlang\'ich sinflarda integratsiyalashgan darslarni tashkil etish bo\'yicha quyidagi tadqiqotlarni ko\'rib o\'tamiz: Onlayn ta\'lim platformalari: Google Classroom, Microsoft Teams va Zoom kabi onlayn ta\'lim platformalari COVID-19 pandemiyasi davrida masofaviy ta\'limni qo\'llab-quvvatlash uchun keng qo\'llanilgan. EdWeek tadqiqot markazi tomonidan o\'tkazilgan so\'rovga ko\'ra, AQShdagi o\'qituvchilarining 74 foizi pandemiya davrida onlayn ta\'lim platformalaridan foydalangan.\n\nInterfaol doskalar: Interfaol doskalar boshlang\'ich sinflarda o\'quvchilar faolligini va o\'quv natijalarini yaxshilashga yordam beradi. Olib borilgan 17 ta tadqiqotning metod-tahlili shuni ko\'rsatdiki, interfaol doskalardan foydalanish boshlang\'ich maktablarda o\'quvchilarning muvaffaqiyatiga o\'rtacha darajada ijobiy ta\'sir ko\'rsatdi. Ta\'limga oid raqamli platformalar: Ta\'limga oid ilovalar va dasturiy ta\'minotlar boshlang\'ich sinflarda tobora ommalashib bormoqda, chunki ular interfaol va moslashtirilgan o\'rganish imkoniyatlarini taqdim etadi. Common Sense Media tomonidan olib borilgan tadqiqot shuni ko\'rsatdiki, AQSHdagi K-12 o\'qituvchilarining 58 foizi sinfda ta\'lim dasturlaridan foydalanishadi.\n\nMultimedia resurslari: Videolar, tasvirlar va audio kabi multimedia resurslaridan foydalanish boshlang\'ich sinflarda o\'quv natijalarini yaxshilashi ko\'rsatilgan. 43 ta tadqiqotning metod-tahlili shuni ko\'rsatdiki, multimedia resurslaridan foydalanish boshlang\'ich maktablarda o\'quvchilarning muvaffaqiyatiga kichik, ammo sezilarli darajada ijobiy ta\'sir ko\'rsatdi. Ta\'limni boshqarish tizimlari: Moodle va Canvas kabi ta\'limni boshqarish tizimlari aralash ta\'limni qo\'llab-quvvatlash uchun boshlang\'ich sinflarda keng qo\'llanilgan. Raqamli ta\'lim markazi tomonidan o\'tkazilgan so\'rov shuni ko\'rsatdiki, AQShdagi K-12 o\'qituvchilarining 68 foizi sinfda ta\'limni boshqarish tizimlaridan foydalanadi96 . Onlayn hamkorlik vositalari: Google Docs, Padlet va Flipgrid kabi onlayn hamkorlik vositalari boshlang\'ich sinflarda tobora ommalashib bormoqda, chunki ular hamkorlikda o\'rganish imkoniyatini beradi. EdTech Digest tomonidan olib borilgan tadqiqot shuni ko\'rsatdiki, AQShdagi K-12 o\'qituvchilarining 73% sinfda onlayn hamkorlik vositalaridan foydalanishadi. Boshlang\'ich sinf darslarini integratsiyalash ta\'lim-tarbiya jarayonini samarali tashkil etishdagi o\'qituvchi oldida quyidagi vazifalar mavjud: - Ta‟lim maqsadini belgilab olish - Ta‟lim vazifasini aniqlashtirish – Ta\'lim mazmuni va maqsadiga mos keluvchi metodologiyani tanlab olish zarur – Ta\'lim jarayonida ta\'lim oluvchilarning yoshiga, intellektual salohiyatiga monand topshiriqlarni berish - Dars loyihasini ishlab chiqish Boshlang\'ich sinflarda integratsiyalashgan darslarni tashkil etishda xorij tajribasi. Yuqori sifatli ta\'lim tizimi bilan mashhur Finlyandiya texnologiyani o\'quvchilarga yo\'naltirilgan ta\'limni qo\'llab-quvvatlash vositasi sifatida qabul qildi. Finlyandiya Milliy Ta\'lim Agentligi hamkorlik, ijodkorlik va tanqidiy fikrlashni rivojlantirishda texnologiya muhimligini ta\'kidlaydi. Finlyandiya maktablari ko\'pincha o\'quvchilarni fanlararo va loyihaga asoslangan ta\'lim faoliyatiga jalb qilish uchun Seppo va Minecraft: Education Edition kabi raqamli platformalardan foydalanadilar. Singapur 1997-yildan beri ta\'limda Axborot-kommunikatsiya texnologiyalari (AKT) bo\'yicha bir qator bosh rejalarni amalga oshirib kelmoqda. Joriy “Master reja” 4 dasturi o\'quvchilarning raqamli savodxonlik ko\'nikmalarini rivojlantirish hamda innovatsiyalar va hamkorlik madaniyatini rivojlantirishga qaratilgan. Singapore Student Learning Space texnologiyasi o\'qituvchilarga integratsiyalashgan darslar yaratish va o\'quvchilarga interfaol kontent orqali mavzularni o\'rganish imkonini beradi. Avstraliya o\'quv dasturi o\'quvchilarga erta yoshdan boshlab hisoblash fikrlash va raqamli ko\'nikmalarni o\'rgatishga qaratilgan “Raqamli texnologiyalar” fanini o\'z ichiga oladi. Maktablar ko\'pincha fanlar bo\'yicha integratsiyalashgan o\'rganishni qo\'llab-quvvatlash uchun Matletika (Mathletics) va O\'qish tuxumlari (Reading Eggs)kabi interfaol doskalar va raqamli resurslardan foydalanadilar. Digital Technologies Hub kabi kasbiy rivojlanish dasturlari texnologiyani darslariga integratsiya qilishga intilayotgan o\'qituvchilar uchun resurslar va yordam taklif qiladi. Xorijiy mamlakatlar tajribasi boshlang\'ich ta‟limda integratsiyalashgan darslarni tashkil etishni kuchaytirish uchun texnologiya imkoniyatlarini ko\'proq qo\'llashini guvohi bo\'ldik. Albatta, integratsiyalashgan darslarni olib borishda raqamli texnologiyalarning o\'rni va ahamiyati muhim, biroq pedagogining kasbiy, didaktik malaka va mahoratini ham yoddan chiqarmaslik lozimdir. Integratsiyalashgan ta\'limning didaktik xususiyatlarini quyidagilar tashkil etadi:\n\nIntegratsiyalashgan darslarning birinchi xususiyati o\'quvchi shaxsiga yo\'naltirilganligidandir. An\'anaviy ta\'limdan farqli o\'laroq, integratsiyalashgan ta\'lim ta\'lim oluvchini har jihatdan tarbiyalashga, uning ijodiy qobiliyatlarini shakllantirishga ko\'mak beradi. Integratsiyalashgan darslarda o\'quv jarayonidagi barcha o\'quv komponentlari, o\'quv tizimining barcha qismlarini, tizimlararo o\'zaro aloqadorlikni qamrab oladi. Boshlang\'ich ta\'limda integratsiyalashgan darslarni tashkil etish texnologiyasi hozirgi zamonda tobora dolzarb va ahamiyatli bo\'lib bormoqda. Integratsiyalashgan darslar bolalarni turli mavzular orqali ularning tanqidiy fikrlash, muammolarni hal qilish va tahlil qilish qobiliyatlarini rivojlantirishga yordam beradi. Mavzularning o\'zaro bog\'liqligini tushunish orqali ular murakkab tushunchalarni yaxshiroq tushunishlari mumkin bo\'ladi. Integratsiyalashgan darslar hamkorlik, muloqot, ijodkorlik va moslashuvchanlik kabi muhim ko\'nikmalarni rivojlantirishni rag\'batlantiradi. Ushbu ko\'nikmalar ta\'lim oluvchilarning bugungi doimiy o\'zgaruvchan dunyoda muvaffaqiyatga erishishlari uchun juda muhimdir. Umuman olganda, boshlang\'ich ta\'limda integratsiyalashgan darslarni tashkil etish o\'quvchilarni tez sur\'atda, bir-biriga bog\'langan dunyoda muvaffaqiyatga tayyorlash uchun juda muhimdir.\n\nXulosa qilib aytganda, boshlang\'ich sinflarda integratsiyalashgan sinflarni tashkil etish texnologiyasi bo\'yicha olib borilayotgan izlanishlar o\'quvchilarning bilim olish natijalarini oshirish, o\'qitish amaliyotini takomillashtirish va o\'quvchilarni kelajakka tayyorlashda muhim ahamiyatga ega.', '5jRaSgMIPmw', 15, 25, '2026-11-06 09:32:36'),
(24, 3, 24, '12-Amaliyot: \'Mavzuli kun\' (Thematic day) formatida integratsiyalashgan mashg\'ulot modellashtirish', 'practice', '# 12-AMALIYOT: \'MAVZULI KUN\' (THEMATIC DAY) FORMATIDA INTEGRATSIYALASHGAN MASHG\'ULOT MODELLASHTIRISH\n\n### 🎯 Mashg\'ulotning asosiy maqsadi:\nNazariy bilimlarni bevosita sinf amaliyotida, simulyatsion dars bosqichlari va pedagogik keyslar orqali qo\'llash ko\'nikmalarini shakllantirish.\n\n### 📋 Amaliy ish bosqichlari:\n1. **Didaktik maqsadni belgilash:** Boshlang\'ich sinf o\'quvchilarining yosh xususiyatlariga mos vazifalar tanlash.\n2. **Interfaol metodlarni qo\'llash:** Mavzuga mos klaster, aqliy hujum, keys-stadi yoki loyiha metodini dars bosqichlariga kiritish.\n3. **Refleksiv tahlil:** Dars yakunida o\'quvchilarning o\'zlashtirish darajasini va o\'qituvchining o\'z faoliyatini xolisona baholash.\n\n### 💡 Metodik ko\'rsatma:\nUshbu amaliy mashg\'ulot M.B. Muxamadaliyeva tomonidan ishlab chiqilgan **operatsion-faoliyatli** va **refleksiv** komponentlarni rivojlantirishga qaratilgan bo\'lib, bo\'lajak o\'qituvchining darsni mustaqil loyihalay olish mahoratini oshiradi.\n', '5jRaSgMIPmw', 20, 35, '2026-11-06 09:32:36'),
(25, 4, 25, '13-Ma\'ruza: Maktab va oila integratsiyasi hamda hamkorlik pedagogikasi', 'lecture', '13-MA\'RUZA. MAKTAB VA OILA INTEGRATSIYASI\n\nOilaviy integratsiya tushunchasi\n\nOilaviy integratsiya darajasi tushuniladi – oila a\'zolari o\'rtasidagi munosabatlarda mavjud bo\'lgan sog\'liq, uyg\'unlik va muvozanatshu jumladan, insonni va oilaning yadrosidagi rolini qadrlash.\n\nUni saqlab qolish uchun oila yadrosi a\'zolarining har birining mustahkam, tizimli va izchil munosabatlari va bog\'lanishiga imkon beradigan harakatlar, harakatlar va harakatlar talab etiladi, shunday qilibki, oila uyushgan va funktsional tarzda ishlaydi va uning har bir a\'zosi uchun farovonlik yaratish. Maqsad, uning tarkibiy qismlari o\'rtasida uyg\'unlik va ishonch va ittifoq munosabatlarini yaratishga alohida qiziqish bilan, umuman oilani rivojlantirishga imkon beradigan sog\'lom oilaviy muhitga erishishdir.\n\nUmuman olganda, oilaviy integratsiya haqida gapirganda, biz sa\'y-harakatlarni nazarda tutamiz mustahkam va hurmatli ittifoqni va aloqani saqlab qolish kattalar o\'z farzandlarining hayotida ishtirok etishi mumkin bo\'lgan oila doirasida, bu barcha oila a\'zolariga sifatli aloqani saqlashga va ma\'lumot sifatida harakat qilishga imkon beradi.\n\nYaxshi oilaviy integratsiya ijobiy ishlarni qadrlash va sifatli ta\'limni kafolatlash va qo\'shma tadbirlarni o\'tkazish uchun etarli vaqt va kuch sarflash hamda oila a\'zolari o\'rtasida yaxshi munosabatlarni qo\'llab-quvvatlash hamda oilani hayotga jalb qilish orqali ta\'minlaydi. uning a\'zolari. Buning uchun kerak oilaviy guruh a\'zolari sifatli vaqtni baham ko\'rishadi, shuningdek, aloqa borligi va qo\'rquv, shubha, his-tuyg\'ular, quvonch va qadriyatlar ifoda etilganligi.\n\nMuhim bo\'lishi mumkin bo\'lgan yana bir jihat - bu nafaqat oilaning o\'zini qanday tutishi, balki uning jamiyat va atrof-muhit, shu jumladan ish, do\'stlik yoki hordiq faoliyati bilan bog\'liqligi.\n\nXuddi shunday, munosabatlar nafaqat oilaning eng yosh a\'zolari bilan, balki uning qolgan a\'zolari bilan, shu jumladan er-xotin munosabatlari bilan (agar mavjud bo\'lsa) yaxshi bo\'lishi kerak. Yaxshi munosabatlar nafaqat o\'zaro bog\'liqlikni rivojlantirish uchun, balki oilaning qolgan qismiga (ayniqsa, bolalarga) ta\'sir qiladi. Bu yomon er-xotin o\'zlari xohlamasa ham birga bo\'lishlari kerak degani emas, lekin bu ularning o\'zaro ta\'siri etarlicha hurmatli bo\'lishini anglatadi, shunda atrof-muhitning qolgan qismi va ayniqsa bolalar zarar ko\'rmasligi yoki o\'zlarini aybdor his qilishlari kerak. ularning yomon munosabatlaridan.\n\nAloqa ham yaxshi bo\'ladi va izchil chegaralarni izlash va qo\'llash osonlashadi va bular voyaga etmaganlar tomonidan ham osonroq tushuniladi. Bundan tashqari, u tajovuzkorlikka yoki tengsiz kuch munosabatlarini izlashga moyil bo\'lgan holda, ijtimoiy bo\'lmagan qadriyatlarni taqdim etishni qiyinlashtirishi mumkin. Xuddi shu tarzda, haqiqatdan qochish yo\'llarini izlash (masalan, giyohvand moddalar kabi) va yuzaga keladigan muammolarni hal qilish uchun faolroq izlash rag\'batlantiriladi.\n\nBundan tashqari, yaxshi oilaviy integratsiyaning yo\'qligi kontsentratsiya muammolarini, unumdorlikning pasayishini, bezovtalik va qayg\'uga moyillikni, stressli vaziyatlarga duchor bo\'lish qobiliyatini yoki ijtimoiylashuvni pasayishini ma\'qullaydi.\n\nEhtimol sizni qiziqtirishi mumkin: \"Oilaviy xilma-xillik: yolg\'iz va homoparental oilalar\"\n\nOilaviy integratsiyaga nima xalaqit berishi mumkin?\n\nAytganimizdek, oilaviy integratsiyani saqlashga erishish juda muhimdir oila a\'zolari o\'rtasida ijobiy muhit va iqlimni shakllantirish va bu normal rivojlanadi. Ammo haqiqat shundaki, bunday integratsiyaga zarar etkazadigan ko\'plab omillar mavjud.\n\nUlardan biri va, ehtimol, eng keng tarqalgan narsa, bu oila va ishni yarashtirishdagi qiyinchilik, ayniqsa, agar ish vaqti yoki ish turi voyaga etmaganlarning ko\'p vaqtini yolg\'iz o\'tkazishini yoki ota-onalardan biri ular bilan deyarli vaqt o\'tkazmasligini anglatsa. Shu ma\'noda o\'yinlar va turli xil tadbirlar orqali birgalikda o\'tkazish va aralashish uchun lahzalarni topish maqsadga muvofiqdir.\n\nEr-xotin munosabatlaridagi tengsizlikning mavjudligi, oilaviy muhitning har qanday a\'zolarining ehtiyojlarini kam baholashi yoki jinoyatchilik, giyohvandlik yoki oiladagi zo\'ravonlik kabi muammolarning mavjudligi ham oilaning parchalanishi muammolari, voyaga etmaganning rivojlanishi uchun salbiy modelni yaratish.\n\nUzluksiz ishsizlik, ijtimoiy chetga chiqish va / yoki o\'ta qashshoqlik holatlari ham ushbu integratsiyani saqlashda qiyinchiliklar tug\'dirishi mumkin. Mumkin bo\'lgan yana bir mushkullik - bu oila a\'zolarining ehtiyojlarini er-xotin va bolalar darajasida idrok etishmasligi. Masalan, buni ko\'rish mumkin edi maxsus ta\'lim ehtiyojlari bo\'lgan ba\'zi bolalarda, intellektual nuqsonlari, autizm, miya yarim falaji yoki aqliy kasalliklari bo\'lgan voyaga etmaganlarga nisbatan bo\'lishi mumkin.\n\nAgar birlashma va me\'yoriy aloqani saqlashda qiyinchiliklar mavjudligi aniqlansa, yuzaga kelishi mumkin bo\'lgan muammolarga echim topish uchun oilaviy terapiya, vositachilik yoki oilaviy maslahat turlariga murojaat qilish foydali bo\'lishi mumkin. Bunday holda, oila a\'zolaridan, masalan, bobosi yoki boquvchisidan foydalanish mumkin, ammo bu ma\'noda ma\'muriyat va biznes sektori tomonidan haqiqiy kelishuvga yo\'l qo\'yishi uchun ijtimoiy siyosatni ishlab chiqish zarur\n\nTarbiya nazariyasi-pedagogika fanining bir qismi bo\'lib, tarbiyaviy jarayonning mazmuni, usuli va tashkil etish masalalarini o\'rganadi. Tarbiya nazariyasi markaziy Osiyo faylasuflarining va xalq pedagoglarining tarbiya borasida boy tajribalariga tayanadi. U o\'z qoidalarini asoslashuchun falsafa, sotsiologiya, etika,estetika, fiziologiya, psixologiya, fanlaridan foydalanadi.Tarbiya nazariyasi pedagogikaning tashqi bilimlari: pedagogikaning umumiy asoslari, ta\'lim nazariyasi, maktabshunoslik bilan uzviy bog\'langandir. Tarbiya jarayonida kishining turliqobiliyatlari rivojlanadi, g\'oyaviy. axloqiy, irodaviy estetik xislatlari shakllanadi, tabiatga, jamiyatga ilmiy qarashlar tizimi tarkib topadi, jismoniy rivojlanadi. Bola o\'sgan sari bu faoliyatlartakomillashadi,mustahkamlashadi.Oilada tarbiya turli qoidalar asosida olib boriladi.Tarbiya qoidalari pedagogik ta\'lim vatarbiya jarayonini yaxshiroq tashkil e\'tish maqsadida foydalanaladigan boshlang\'ich holat, rahbarlik asosidir. Ta\'lim qoidalari o\'qituvchi, tarbiyachilarga yo\'l-yo\'riq ko\'rsatuvchi qoidalar hisoblanadi, yangi kishini shakllantirish vazifalari bilan belgilanadi. Tarbiya qoidalari sharq va markaziy Osiyo faylasuf donishmandlarining fikrlari va milliy pedagogikada erishgan yutuqlarga asoslanadi. Tarbiyaning mazmuni, tashkil e\'tishi, usullari va ularga qo\'yiladigan talablar shu qoidalarda o\'z ifodasini topadi.\n\nOilada tarbiyaning olib boriladigan tarbiya qoidalariga quyidagilarni kiritish mumkin:\n\n-tarbiyaning ma\'lum maqsadga qaratilganligi;\n\n-tarbiyaning insonparvarligi va demokratligi;\n\n-tarbiyaning hayot va mehnat bilan bog\'liqligi;\n\n-tarbiyada milliy madaniy va umuminsoniy qadriyatlarning ustuvorligi;\n\n-tarbiyalanuvchining yoshini va shaxsiy xususiyatlarini hisobga olish;\n\nDemak, tarbiya usuli tarbiyachi va tarbiyalanuvchilarning hamkorligidagi faoliyat va o\'zaro ta\'sir ko\'rsatish usullaridir.Bu jarayonda esa oilaning o\'rni, ayniqsa, katta. Оila –an\'anaviy tarbiyaning asоsiy instituti bo\'lib hisоblanadi. Bоla yoshlik davrida оilada оlgan ta\'lim –tarbiyasini butun umri davоmida saqlab qоladi. Bоla hayotini asоsiy qismini оilada o\'tkazadi, o\'zining ta\'sir kuchiga ko\'ra hеch qanday tarbiya vоsitasi оila bilan bеllasha оlmaydi. Оilada bоla shaхsini asоslari tarkib tоpdiriladi maktabga bоrganda esa bоla shaхs sifatida shakllangan bo\'ladi. Оila bоlalarga insоniyva salbiy ta\'sir etish оmili bo\'lishi mumkin. Bоla shaхsiga ijоbiy ta\'sir etish shundan ibоratki, оilada bоlaga eng yaqin insоnlardan -оta, оna, buvi, buva, aka, оpalardan tashqari hеch kim ulardеk bоlani yaхshi ko\'rib, u haqida qayg\'urmaydi. Shu bilan birga,bоla shaхsini shakllantirishga, ularga tarbiya bеrishda оila salbiy ta\'sir ham ko\'rsatishi mumkin. Оila –bu o\'ziga хоs jamоadir u tarbiyada asоsiy o\'ringa egadir.Оilani o\'ziga хоs tarbiyaviy ahamiyatini hisоbga оlgan hоlda, оilani bоlaga ijоbiy ta\'sirini оshirib, salbiy ta\'sirini kamaytirish zarur. Buning uchun esa tarbiyaviy ahamiyatga ega bo\'lgan, ichki оilaviy ijtimоiy-psiхоlоgik оmillarni aniq bеlgilash lоzim.Bоlani tarbiyalashda asоsiysi оta-оna bilan bоla o\'rtasida qalban yaqinlikka va axlоqiy bоg\'likka erishishdir. Оta-оnalar hеch qachоn tarbiya jarayonini o\'z hоliga tashlab qo\'ymasligi kеrak, ayniqsa katta bo\'la bоshlagan bоlani o\'z hоliga tashlab qo\'ymasligimiz kеrak. Bоla оilada birinchi hayotiy tajribani o\'rganadi, kuzatadi va o\'zini turli xil vaziyatlarda qanday tutish kеrakligini o\'rganadi. Biz bоlani nimaga o\'rgatsak uni aniq, hayotiy misоllarbilan mustahkamlash kеrak,bоla kattalarniaytgan gaplari amalda ham bir xil bo\'lishini ko\'rishi kеrak. (masalan: agar bоla har kuni оta-оnasi tоmоnidan yolg\'оn gapirish mumkin emasligini eshitsa-yu, lеkin оta-оna o\'zi sеzmagan hоlda shunga qоidaga riоya qilmasalar, bоla tarbiyasiga darz kеtadi). Har bir оta-оna farzandlarida o\'zlarni davоmchilarini ko\'radi. Farzandlarini o\'zlari xоhlagan insоn bo\'lishlarinixоhlaydilar. Оta-оnalar o\'rtasidagi mоjarоli vaziyatlar, ayniqsa, munosabatlarni darz ketkazish uchun sabab bo\'lishi mumkin. Оta-оnalar o\'rtasidagi mоjarоli vaziyatlar –bu оta-оnalar tоmоnidan bоla tarbiyasiga turlicha yondashuvdir. Mоjarоli vaziyatlarni hal etish uchun quyidagilarga riоya qilish kеrak. Maktabda va oilada bolalarning o\'zini tutishiga alohida e\'tibor berish, ayniqsa muhim. Maktabni оila bilan bоg\'lоvchi vоsita-bu o\'qituvrchilardir. Maktab,оila va jamоatchilik hamkоrligini yo\'lga qo\'yishda sinf rahbarining tarbiyaviy faоliyati nihоyatda muhimdir. O\'qituvchilarni tarbiyalashda sinf rahbari оmmaviy, guruh, yakka tartibdagi ishlarni tashkil qiladi. Maktabning оila bilan оlib bоradigan оmmaviy ish shakllariga: pеdagоgik ma\'ruza, оta-оnalar majlisi, оchiq eshiklar kuni, maslahat bеrish,savоl –javоb kеchalari, birоn bir mavzuga bag\'ishlangan yig\'ilishlari kiradi. Pеdagоgik bilim оta-оnalar uchun nihоyatda zarurdir. Pеdagоgik bilim maktabda, mahallada va kundalik aхbоrоt vоsitalari оrqali bеrib bоriladi. Pеdagоgik ma\'ruza pеdagоgik bilim bеrishning an\'anaviy shakllaridan biridir. Оta-оnalar uchun ma\'ruza aniqmatеrial, ijоbiy namunalar, adabiy manbalar ko\'rgazmali qo\'llanmalardan fоydalanib o\'tkazish maqsadga muvоfiqdir. Sinf rahbari оta-оnalar bilan ishlashining asоsiy shakllaridan biri har o\'quv chоragida kamida bir marta оta-оnalar majlisi o\'tkazishidir. Sinf rahbari o\'qituvchilarni aqliy faоliyatining o\'ziga хоs хususiyatlari, o\'quv mеhnatidagi bo\'sh tоmоnlar, o\'quvchilarning turli fanlarga munоsabatlari, ularning mеhnatsеvarligi, tirishqоqligi to\'g\'risidagi o\'qituvchilar fikri bilan tanishtiradi. Maktabning оila bilan оlib bоradigan guruh tarzdagi ish shakliga оta-оnalar qo\'mitasi faоliyati, guruh tarzidagi majlis –suhbatlar kiradi. Umummaktab va sinf оta-оnalar qo\'mitalarining faоliyati umumta\'lim maktablari оta-оnalar qo\'mitasi Nizоmida bеlgilangan. Bu qo\'mitalar оta-оnalar yig\'ilishida saylanadi. U bоlalarga maktab va оila tarbiyaviy ta\'sirining yaхlitligini ta\'minlaydi. Qo\'mitaning ishini Rais bоshqaradi. Maktab оta-оnalar qo\'mitasi sinf оta-оnalar qo\'mitalari faоllarni o\'qishlari ularning tajriba almashishlarini tashkil qiladi. Sinf rahbari оta-оnalar qo\'mitasi bilan birgalikda оilada bоlalarning tarbiyalashning shakl va usullari bu ishda ilg\'оr tajribalarni o\'rganadi. Maktabning оta-оnalar, jamоatchiligi bilan alоqa qilishida O\'qituvchi va tarbiyachilarga yaqindan yordam bеruvchi bumaktab оta-оnalar qo\'mitasidir. Mazkur qo\'mita qabul qilgan umumiy qоidalar asоsida оta-оnalar jamоatchiligini maktab hayotiga, sinfdan vamaktabdan tashqari tarbiyaviy ishlarga jalb qilinadi. Maktabning оila bilan оlib bоradigan yakka tartibdagi ish shakllariga: pеdagоgik suhbatlar, оta-оnalarni maktabga taklif qilish, оilaga tashrifkiradi. Sinf rahbari оta-оnalarning uylariga bоrib maishiy sharоit bilan tanishadi. O\'quvchini tarbiyalash yuzasidan оta-оnalarga maslahatlar bеradi. Maktab ahоlining,birinchi navbatda, оta-оnalarning pеdagоgik uquvini amalga оshiradi, har bir оilada o\'zarо hurmat, bir-biriga yordam, insоniy munоsabatlar muhiti yaratilishini qo\'llab-quvvatlaydi, ko\'p bоlali va kam ta\'minlangan оilalarning bоlalariga mоddiy yordam ko\'rsatish yo\'lida fuqarоmеhr-shafqat dasturini amalga оshirishda o\'zining tarbiyaviy imkоniyatlarini оchib bеradi. Оila esa, o\'z navbatida o\'quv-tarbiya jarayonini qayta qurishda maktabga yaqindan yordam bеrib, o\'quvchilarning ta\'lim-tarbiyaning barcha jabhalarini egallashlari uchun maktab jamоasigayaqindan ko\'maklashadi. Shuning uchun ham оila, maktab va mahalla hamkоrligi masalasi hоzirgi davrning asоsiy talabidir. Оilada bоla tarbiyasini yo\'lga qo\'yishda mahallaning rоli kattadir. Qadimdan o\'zbеk хalqi mahalla-jamоatchilik bilan hamjihatchilikda yashab, оilaviy urf-оdat va an\'analarniular ishtirоkida, ular bilan bamaslahat o\'tkazganlar. Mahalla kishilarni birlashtiradigan, ijtimоiy-siyosiy, madaniy-ma\'rifiy va tarbiyaviy ahamiyatgaega bo\'lgan jamоa vazifasini bajarib kеlgan. «Bir bоlaga yеtti mahalla оta-оna dеgan naqldan kеlib chiqib kеlajak avlоdni tarbiyalash va unga ta\'lim bеrish jarayonini amalga оshirish bоrasida kichik Vatan bo\'lmish mahallaning оldida quyidagi vazifalar turadi:\n\n-mahala o\'z hududidagi yordamga muhtоj оilalarni aniqlaydi va ularni qo\'llab –quvvatlab, farzand tarbiyasida ishtirоk etadi;\n\n-ma\'nan nоsоg\'lоm оilalarni mahala yig\'inlarida muhоkama qilish va ularga nisbatan chоra ko\'rish;\n\n-mahalla hududidagi o\'quv tarbiya muassasalaridagi ijtimоiy va iqtisоdiy yordam ko\'rsatilishini qo\'llab-quvvatlash;-оta-оnalar оrqali bоlalardagi mеhnatsеvarlik vatanparvarlik, tashabbuskоrlik kabi хislatlarni singdirishni rag\'batlantirish;-mahala hududida o\'quv tarbiya muassasalaribilan birgalikda bayram,ko\'rik tanlоv, anjuman, spоrt m\n\nusabоqalarini tashkil etish.-ta\'lim yo\'nalishida iqtidоrli bo\'lgan o\'qituvchi bоlalarni maktab tavsiyasiga ko\'ra ijtimоiy va iqtisоdiy qo\'llab-quvvatlash;\n\n-ilg\'оr pеdagоgik хоdimlar tarbiyachilargamahalla imkоniyatidan kеlib chiqqan hоlda yordam bеrish;\n\n-farzandlariga ta\'lim –tarbiya bеrishda ijоbiy natijalarga erishgan namunali оilalar hayoti tajribasini оmmalashtirish;\n\n-har bir yosh fuqarоda O\'zbеkistоnga,uning tabiatiga, tariхiga qiziqish, mahalla оbоdоnchiligi, ahilligi uchun javоbgarlik ruhini tarbiyalash.\n\nTarbiya jarayoni ishtirоkchilari sa\'y –harakatlarini birlashtirish maqsadida 1993-yilda ishlab chiqilgan «Оila, mahalla, maktab hamkоrligi kоnsеptsiyasi yoshlarni ma\'naviy barkamоl, vatanparvar etib tarbiyalashda kеng jamоatchilik faоliyatini muvоfiqlashtirish bоrasida ma\'lum dasturul amal bo\'ldi. Yosh avlоdni ma\'naviy aхlоqiy tarbiyalashda хalqimizning bоy milliy, madaniy, tariхiy, an\'analariga, urf-оdatlariga, hamda umumbashariy qadriyatlarga asoslangan. Samarali zamоnaviy pеdagоgik tехnоlоgiyaning ishlab chiqib amaliyotga tadbiq etilishi, shaхsni tarbiyalash va uni har tоmоnlama kamоl tоptirishining ustuvоrligini ta\'minlash, umumiy va milliy pеdagоg madaniyatni оshirish, fuqarоlar оrasida miliy mafkuraviy tarbiya ishlarini takоmillashtirish, «Оila, mahala, maktab hamkоrligi» kоnsеptsiyasini asоsiy maqsadidir. «Оila, mahalla, maktab hamkоrligi quyidagi tamоyillarga asosan olib boriladi.\n\nTamоyillar:\n\n-Ta\'lim va tarbiya sоhasida hamkоrlik jarayoni ishtirоkchilari harakatlarining ish birligi;\n\n-Tarbiyalanuvchiga hurmat va talabning uyg\'unligi;\n\n-Hamkоrlik jarayoni sub\'еktlarining tеng хuquqliligi va yuksak mas\'uliyati;\n\n-Hamkоrlikning milliy asоslanganligi;\n\n-Faоliyat jarayonida millat va davlat manfaatlari ustuvоrligi.\n\nBundan tashqari, oilada munosabatning quyidagi 3 turi bor.\n\n1..Avtoritar (loqaydlik) munosabat (xamileon-buqalamun) bo\'lmaslik kerak so\'zi avtaritet so\'zlariga ma\'nodosh obro saqlamoq degan ma\'noni bildiradi. O\'zining tarkibiga majbur e\'tish, qo\'rqitish, do\'q-po\'pisa, buyruq berish, ta\'qiqlash, o\'rta darajada jazolash\n\n2.Demokratik-munosabatlarda mehribon bo\'lish. Oilada hamma a\'zolarga nisbatan mehribon, jonkuyar bo\'lish. “Siz o\'z shogirdingizga shunday muomalada va munosabatda bo\'lingkim, kelajakda undan buyuk inson chiqishiga ishonch ko\'zi bilan qarang. (N.A.Dobralyubov). Nutqda raxmat, barakalla, minnatdorman, ofarin, yaxshi uylabsiz, ma\'qul gap, tasanno va boshqa so\'zlari ishlatilsa, o\'quvchi bilan o\'qituvchilar o\'rtasidagi mehr-muhabbatni oshiradi, iplarni bog\'laydi.\n\n3.Liberalmunosabat-sovuqqonlik, oiladagi munosabatlarga panja orqasidan qarash. A.Qahhor “Sinchalak” asarida qoziqning uchi ham pasti ham bo\'lma, sababi uchi bo\'lsang yerga kirasan,orqasi bo\'lsang to\'qmoqeysan, yaxshisi o\'rtasi bo\'l ekan. Xulosa qilib aytadigan bo\'lsak, tarbiya-bu uzoq muddatli, murakkab jarayon bo\'lib, undagi munosabatlar kompleks vaoila, mahalla va maktab hamkorligini ta\'minlashni o\'z oldiga maqsad qilgan holda olib borilsa, jamiyat yanada rivojlanadi.\n\nFOYDALANILGAN ADABIYOTLAR:\n\n1.Munavvarov A.KPedagogika,Toshkent,”O\'qituvchi”, 1996, 119-136', '0gAb9YZAIec', 15, 25, '2026-11-06 09:32:36'),
(26, 4, 26, '13-Amaliyot: Ota-onalar bilan interfaol muloqot va hamkorlikdagi loyiha rejasini ishlab chiqish', 'practice', '# 13-AMALIYOT: OTA-ONALAR BILAN INTERFAOL MULOQOT VA HAMKORLIKDAGI LOYIHA REJASINI ISHLAB CHIQISH\n\n### 🎯 Mashg\'ulotning asosiy maqsadi:\nNazariy bilimlarni bevosita sinf amaliyotida, simulyatsion dars bosqichlari va pedagogik keyslar orqali qo\'llash ko\'nikmalarini shakllantirish.\n\n### 📋 Amaliy ish bosqichlari:\n1. **Didaktik maqsadni belgilash:** Boshlang\'ich sinf o\'quvchilarining yosh xususiyatlariga mos vazifalar tanlash.\n2. **Interfaol metodlarni qo\'llash:** Mavzuga mos klaster, aqliy hujum, keys-stadi yoki loyiha metodini dars bosqichlariga kiritish.\n3. **Refleksiv tahlil:** Dars yakunida o\'quvchilarning o\'zlashtirish darajasini va o\'qituvchining o\'z faoliyatini xolisona baholash.\n\n### 💡 Metodik ko\'rsatma:\nUshbu amaliy mashg\'ulot M.B. Muxamadaliyeva tomonidan ishlab chiqilgan **operatsion-faoliyatli** va **refleksiv** komponentlarni rivojlantirishga qaratilgan bo\'lib, bo\'lajak o\'qituvchining darsni mustaqil loyihalay olish mahoratini oshiradi.\n', '0gAb9YZAIec', 20, 35, '2026-11-06 09:32:36'),
(27, 4, 27, '14-Ma\'ruza: Innovatsion ta\'lim muhitida o\'qituvchining kreativligi va pedagogik mahorati', 'lecture', '14- MAVZU: Innavatsion ta\'lim muhitida o\'qituvchining kreativligi\n\nReja:\n\n1. Innovasion faoliyatning mazmuni va mohiyati.\n\n2. O\'qituvchining innovasion faoliyatining o\'ziga xos kreativ xususiyatlari .\n\nInnovatsiya (inglizcha innovation) - yangilik kiritish, yangilikdir.\n\nA.I. Prigojin innovasiya deganda muayyan ijtimoiy birlikka - tashkilot, aholi, jamiyat, guruhga yangi, nisbatan turg\'un unsurlarni kiritib boruvchi maqsadga muvofiq o\'zgarishlarni tushunadi. Bu innovator faoliyatidir.\n\nTadqiqotchilar (A.I. Prigojin, B.V. Sazonov, V.S. Tolstoy, A.G.Kruglikov, A.S.Axiezer, N.P.Stepanov va boshqalar) innovasion jarayonlar tarkibiy qismlarini o\'rganishning ikki yondashuvini ajratadilar: yangilikning individual mikrosathi va alohida-alohida kiritilgan yangiliklarni o\'zaro ta\'siri mikrosathi.\n\nPedagogikaga oid adabiyotlarda innovasion jarayoni kechishining 4 ta asosiy qonuniyati farqlanadi:\n\npedagogik innovasiya muhitining ayovsiz bemaromlik qonuni;\n\nnihoyat amalga oshish qonuni;\n\nqoliplashtirish (stereotiplashtirish) qonuni;\n\npedagogik innovasiyaning davriy takrorlanishi va qaytishi qonuni;\n\nPedagogik innovatsiyada R.N.Yusufbekova innovatsion jarayon tuzilmasining uch blokini farqlaydi:\n\nBirinchi blok - pedagogikadagi yangini ajratish bloki. Bunga pedagogikadagi yangi, pedagogik yangilikning tasnifi, yangini yaratish shart-sharoiti, yangilikning me\'yorlari, yangining uni o\'zlashtirish va foydalanishga tayyorligi, an\'ana va novatorlik, pedagogikadagi yangini yaratish bosqichlari kiradi.\n\nIkkinchi blok - yangini idrok qilish, o\'zlashtirish va baholash bloki: pedagogik hamjamiyatlar, yangini baholash va uni o\'zlashtirish jarayonlarining rang-barangligi, pedagogikadagi konservatorlik va novatorlik, innovatsiya muhiti, pedagogik jamiyatlarning yangini idrok etish va baholashga tayyorligi.\n\nUchinchi blok - yangidan foydalanish va uni joriy etish bloki, ya\'ni yangini tadbiq etish, foydalanish va keng joriy etish qonuniyatlari va turlaridir. M.M.Potashnikning innovatsiya jarayonlari talqinlari kishi e\'tiborini o\'ziga tortadi. U innovatsiya jarayonining quyidagi tuzilmasini beradi:\n\nfaoliyat tuzilmasi - motiv - maqsad - vazifa - mazmun - shakl - metodlar - metodika komponentlari yig\'indisi;\n\nsub\'ektiv tuzilma-innovatsion faoliyat sub\'ektlarining xalqaro, mintaqaviy, tuman, shahar va boshqa sathlari;\n\nsathiy tuzilma-innovatsion faoliyat sub\'ektlarining xalqaro, mintaqaviy, tuman, shahar va boshqa sathlari;\n\nmazmun tuzilmasi - o\'quv-tarbiyaviy ishlar, boshqaruv (va b.)da yangilikning paydo bo\'lishi, ishlab chiqilishi va o\'zlashtirilishi;\n\nbosqichlilikka asoslangan hayot davriylik tuzilmasi – yangilikning paydo bo\'lishi - ildam o\'sish - etuklik – o\'zlashtirish - diffuziya (singib ketish, tarqalish) – boyish (to\'yinish) – qoloqlik - inqiroz – irradiatsiya (aldanish) – zamonaviylashtirish;\n\nboshqaruv tuzilmasi - boshqaruv harakatlarining 4 ta turining o\'zaro aloqasi: rejalashtirish - tashkil etish - rahbarlik qilish - nazorat qilish;\n\ntashkiliy tuzilma - diagnostik, oldindan ko\'ra bilish, sof tashkiliy, amaliy, umumlashtiruvchi, tadbiq etuvchi.\n\nO\'qituvchining innovasion faoliyatining o\'ziga xos xususiyatlari\n\nO\'qituvchining innovasion faoliyatini samarali amalga oshirish bir qator shart-sharoitlarga bog\'liq. Unga o\'qituvchining tayinli muloqoti aks fikrlarga nisbatan beg\'araz munosabat, turli holatlarda rasional vaziyatning tan olinishini uqtirishga tayyorligi kiradi. Buning natijasida o\'qituvchi o\'z bilim va ilmiy faoliyatini ta\'minlaydigan keng qamrovli mavzu (motiv) ga ega bo\'ladi.\n\nO\'qituvchi faoliyatida o\'z-o\'zini faollashtirish, o\'z ijodkorligi, o\'z-o\'zini bilishi va yaratuvchiligi mavzu (motiv)lar muhim ahamiyat kasb etadi. Bu esa o\'qituvchi shaxsining kreativligini shakllantirish imkoniyatini beradi.\n\nYangilik kiritishning muhim sharti muloqotning yangi vaziyatini tug\'dirishdir.\n\nMuloqotning yangi vaziyati - bu o\'qituvchining o\'z mustaqillik mavqeini, dunyoga, pedagogik fan, o\'ziga bo\'lgan yangi munosabatni yarata olish qobiliyatidir. O\'qituvchi o\'z nuqtai nazarlariga o\'ralashib qolmaydi, u pedagogik tajribalarning boy shakllari orqali ochilib, mukammallashib boradi. Bunday vaziyatlarda o\'qituvchining fikrlash usullari, aqliy madaniyati o\'zgarib boradi, hissiy tuyg\'ulari rivojlanadi.\n\nGuruh sharoitida ishlashda va tanqidiy fikrlashga o\'rgatishda turli interfaol usullardan foydalanish yaxshi samara beradi. Shunday usullardan ayrimlari bilan tanishib chiqamiz.\n\nAqliy hujum (Breynshtorming)\n\nAqliy hujum- g\'oyalarni generatsiya qilish usuli. Qatnashchilar birlashgan holda qiyin muammoni yechishga harakat qiladilar: uni yechish uchun shaxsiy g\'oyalarini ilgari suradilar (generasiya kiladi). U ishtirokchilarni o\'z tasavvurlari va ijodlaridan foydalanishga rag\'batlantiradi. «Aqliy hujum»ning vazifasi kichik guruhlar yordamida yangi- yangi g\'oyalarni yaratishdir. Bu usul muammoni hal qilayotgan kishilarning ko\'proq aql bovar qilmaydigan va hatto fantastik g\'oyalarni yaratishga undaydi. G\'oyalar qancha ko\'p bo\'lsa, ularning hech bo\'lmaganda bittasi ayni muddao bo\'lishi mumkin.\n\n«Aqliy hujum»ning qoidalari:\n\nFikr va g\'oyalar hech qanday cheklanmagan holda iloji boricha qattiqroq aytilishi lozim;\n\nBildirilgan fikr va g\'oyalar takliflar berish to\'xtatilmaguncha muhokama qilinmaydi, baholanmaydi;\n\nBildirilgan har qanday g\'oya va fikrlar hisobga olinadi;\n\nQancha ko\'p g\'oya va fikrlar bildirilsa shuncha yaxshi;\n\nBildirilgan g\'oya va fikrlarni to\'ldirish va yanada kengaytirish mumkin;\n\nBarcha aytilgan takliflar yozib boriladi;\n\nTakliflarni bildirish uchun vaqt aniq belgilanadi.\n\nBu usul barcha funksiyalarni bajaradi: lekin uning asosiy vazifasi- muammoni mustaqil tushunish va echishga ta\'lim oluvchilarning motivatsiyasini uyg\'otishdan iboratdir.\n\nAqliy hujum usulining texnologik xaritasi.\n\nPinbord usuli ( inglizchadan: pin - mustahkamlash, board - doska)\n\nBu o\'qitish usulining mohiyati shundan iboratki, unda munozara yoki o\'quv suhbati amaliy usul bilan bog\'lanib ketadi. Uning afzallik funksiyalari- rivojlantiruvchi va tarbiyalovchi vazifadir: o\'quvchilarda muloqat yuritish va munozara olib borish madaniyati shakllanadi, o\'z fikrini faqat og\'zaki emas, balki yozma ravishda bayon etish mahorati, mantiqiy va tizimli fikr yuritish ko\'nikmasi rivojlanadi.\n\nMunozara (Muhokama) uslubi\n\nKo\'p hollarda seminar mashg\'ulotlari orada o\'qituvchi monologlari bilan bo\'linadigan talabalar monologlari shaklida o\'tadi, qolgan o\'quvchilar esa shu paytda zerikib o\'tiradilar. Shuning uchun darsda Munozara usulini qo\'llash barcha o\'quvchilarning faolligini oshirib, zerikishlarga yo\'l qo\'ymaydi.', '2G2ODT_fFM0', 15, 25, '2026-11-06 09:32:36'),
(28, 4, 28, '14-Amaliyot: Pedagogik vaziyatlar (keys-stadi)ni tahlil qilish va refleksiv o\'z-o\'zini baholash', 'practice', '# 14-AMALIYOT: PEDAGOGIK VAZIYATLAR (KEYS-STADI)NI TAHLIL QILISH VA REFLEKSIV O\'Z-O\'ZINI BAHOLASH\n\n### 🎯 Mashg\'ulotning asosiy maqsadi:\nNazariy bilimlarni bevosita sinf amaliyotida, simulyatsion dars bosqichlari va pedagogik keyslar orqali qo\'llash ko\'nikmalarini shakllantirish.\n\n### 📋 Amaliy ish bosqichlari:\n1. **Didaktik maqsadni belgilash:** Boshlang\'ich sinf o\'quvchilarining yosh xususiyatlariga mos vazifalar tanlash.\n2. **Interfaol metodlarni qo\'llash:** Mavzuga mos klaster, aqliy hujum, keys-stadi yoki loyiha metodini dars bosqichlariga kiritish.\n3. **Refleksiv tahlil:** Dars yakunida o\'quvchilarning o\'zlashtirish darajasini va o\'qituvchining o\'z faoliyatini xolisona baholash.\n\n### 💡 Metodik ko\'rsatma:\nUshbu amaliy mashg\'ulot M.B. Muxamadaliyeva tomonidan ishlab chiqilgan **operatsion-faoliyatli** va **refleksiv** komponentlarni rivojlantirishga qaratilgan bo\'lib, bo\'lajak o\'qituvchining darsni mustaqil loyihalay olish mahoratini oshiradi.\n', '2G2ODT_fFM0', 20, 35, '2026-11-06 09:32:36');
INSERT INTO `lessons` (`id`, `module_id`, `order`, `title`, `lesson_type`, `content`, `video_url`, `reading_time_minutes`, `xp_reward`, `created_at`) VALUES
(29, 4, 29, '15-Ma\'ruza: Markaziy Osiyo va MDH davlatlarida integratsiyalashgan ta\'lim tajribalari', 'lecture', '15-MA\'RUZA. MARKAZIY OSIYO VA MDX DAVLATLARIDA INTEGRATSIYALASHGAN TA\'LIM\n\nN.M.Nazarova bu atamani qayd etadi integratsiya noaniq va o\'zgaruvchan talqinlarga ega. Ajralmas qism integratsiya jamiyatda rivojlanishida nuqsonlari bo\'lgan bolalar integratsiya ta\'lim muassasalariga, ular birgalikda imkoniyatga ega bo\'ladilar o\'rganish odatda rivojlanayotgan tengdoshlari bilan. Mahalliy maxsus pedagogikada bo\'g\'in jarayonlarini belgilaydigan bir qator atamalar qo\'llaniladi o\'rganish rivojlanishida nuqsoni bor va normal rivojlanayotgan bolalar. Eng ko\'p ishlatiladigan atama integratsiyalashgan ta\'lim.\n\nM.I.Nikitina, tahlil qilmoqda integratsiyalashgan ta\'lim, Rossiya Federatsiyasi qonun loyihasiga asoslanib, o\'z ta\'rifini beradi \"Maxsus ta\'lim to\'g\'risida\": \"Ostida integratsiyalashgan ta\'lim tushuniladi\"qo\'shma shaxslarni o\'qitish jismoniy va (yoki) ruhiy nogironlar va bunday nogiron bo\'lmagan shaxslar, maxsus vositalar, usullar yordamida va mutaxassis o\'qituvchilar ishtirokida. Shunga o\'xshash ta\'rif bilan integratsiyalashgan ta\'lim beriladi.\n\nStepanov: «G\'ayritabiiy bolalar uchun integratsiyalashgan ta\'lim - o\'rganish va aqliy va jismoniy rivojlanishida nuqsonlari bo\'lgan bolalarni umumiy ta\'lim tizimi muassasalarida normal rivojlanayotgan bolalar bilan birga tarbiyalash. Muddat integratsiyalashgan ta\'lim maxsus sohadagi etakchi olimlarning asarlarida ishlatilgan ta\'lim: L.S.Volkova, N.N.Malofeeva, N.M.Nazarova, M.I.Nikitina, L.P.Ufimtseva, N.D.Shmatko va boshqalar Bu atama bilan bir qatorda bu atama ham ishlatiladi. integratsiyalashgan ta\'lim va tarbiya, integratsiyalashgan ta\'lim... Biroq, mualliflar o\'z mazmuniga o\'xshash ma\'no qo\'ygan. Inklyuziv ta\'lim (fr. inclusif-shu jumladan, lat. kiritish-men xulosa qilaman, men o\'z ichiga olaman) - barcha bolalarning har xil ehtiyojlariga moslashish nuqtai nazaridan hamma uchun ta\'lim mavjudligini nazarda tutadigan umumiy ta\'limning rivojlanish jarayoni, bu alohida ehtiyojli bolalar uchun ta\'lim olish imkoniyatini beradi. Inklyuziv ta\'lim bolalarga yo\'naltirilgan metodologiyani ishlab chiqishga intiladi, u barcha bolalar har xil ehtiyojlarga ega shaxslar ekanligini tan oladi. o\'rganish... Inklyuziv ta\'lim ta\'limga yondashuvni ishlab chiqishga intiladi va o\'rganish turli ehtiyojlarni qondirish uchun yanada moslashuvchan bo\'ladi o\'rganish... Agar o\'qitish va ta\'lim Inklyuziv ta\'lim kiritadigan o\'zgarishlar natijasida samaraliroq bo\'ladi, shunda hamma bolalar foyda ko\'radi (faqat alohida ehtiyojli bolalar emas). Siz rivojlanishni ko\'rishingiz mumkin chet elda integratsiya jarayonlari... Amerika Qo\'shma Shtatlarida 1975-yilda hamma uchun g\'ayritabiiy ta\'lim to\'g\'risidagi qonun (P.L. 94-142, “Qonun integratsiya”, jamiyat demokratik qatlamlarining irqchilikka, irqiy segregatsiyaga qarshi uzoq-yillar davom etgan kurashining tabiiy natijasi bo\'ldi, bu o\'nlab-yillar davomida mamlakatda ijtimoiy balo bo\'lgan. Bu yo\'nalishdagi demokratik tendentsiyalarning yanada rivojlanishi, tabiiyki, irqchilik g\'oyalarini uzatishga olib keldi integratsiya nogironlar va rivojlanish muammolari to\'g\'risida integratsiya maxsus ta\'lim bilan bog\'liq jarayonlar ichida o\'qitish \"Umumiy oqim\" (asosiy so\'z).\n\n1961-yildan 1980-yilgacha Daniya va boshqa Skandinaviya mamlakatlarida o\'qituvchilar, ota-onalar, butun aholi tomonidan tushunish va o\'zlashtirish bo\'yicha ulkan ijtimoiy-pedagogik ishlar olib borildi. integratsiya... Bu hokimiyat tomonidan tartibga solinmagan ko\'plab alohida tashabbuslar harakati edi. Bu erda, AQShda bo\'lgani kabi, integratsiya asta -sekin o\'sib bordi \"Pastdan\" sotsial -demokratik harakat tashabbusi va qo\'llab-quvvatlanishi, mamlakatning ijobiy ijtimoiy va iqtisodiy rivojlanishi. Va faqat mamlakat bu hodisani amalda va ma\'naviy jihatdan o\'zlashtirganida integratsiya (taxminan 20-yil davom etdi, u qonuniylashtirildi haqiqat: 1980-yil yanvar oyida nogironlar bilan munosabatlarni normallashtirish tamoyilini kiritishni nazarda tutuvchi \"Ta\'lim islohoti to\'g\'risida\" qonun qabul qilindi. Italiyaning o\'ziga xos tarixi bor integratsiya... U erda bu jarayon boshlandi 60-70-yillar oxirida ijtimoiy harakat ichaklarida \"Demokratik psixiatriya\", unga ruhoniy F.Basaglia boshchilik qilgan. Bu harakatning maqsadi psixiatriya shifoxonalarida progressiv o\'zgarishlarga erishish, ijtimoiy izolyatsiyani bekor qilish va ruhiy kasalliklari bo\'lgan, ijtimoiy jihatdan zararsiz odamlarni izolyatsiya qilish, aslida psixiatriya shifoxonalari asirlari edi. Bu harakat rahbarlari ruhiy kasalliklar va ruhiy kasalliklarning paydo bo\'lishida birinchi navbatda jamiyat va maktab aybdor, deb hisoblar edilar, shuning uchun ular odamga bunday zararli ta\'sir ko\'rsatmasligi uchun o\'zgarishi kerak edi. 1962-yilda boshlangan integratsiya maktab ta\'limini isloh qilish. 20-asrning oxiriga kelib dunyoning ko\'plab mamlakatlarida (AQSh, Buyuk Britaniya, Shvetsiya, Germaniya, Italiya, Skandinaviya mamlakatlari) bolalarni maxsus muassasalarga yuborish (tuzatish) boshqa barcha imkoniyatlar allaqachon ishlatilgan va kerakli natijani bermaganida, ta\'lim muassasalari o\'ta o\'lchovli ko\'rinadi. Bu mamlakatlarning ta\'lim amaliyotida bu tamoyil amalga oshiriladi birlashtirilgan yondashuv - rivojlanish muammolari bo\'lgan bolalarga imkoniyat berish o\'rganish oddiy bolalar bilan ommaviy maktabda. Shu bilan birga, ular uchun maxsus yordam va qo\'llab -quvvatlash uchun qo\'shimcha shart -sharoitlar yaratiladi ta\'lim.\n\nKareliya Respublikasida ikkita model mavjud integratsiya: UUning umumiy turiga ega bo\'lgan tuzatish sinflari va guruhlari - bu sinflar o\'qitiladi rivojlanish muammolari bo\'lgan bolalar. 2008-yil oxiriga kelib Rossiya Federatsiyasida bunday sinflarda o\'qitildi 160 mingdan ortiq nogiron bolalar, shundan 28 mingga yaqini aqli zaif bolalar va 122 mingdan ziyod aqli zaif bolalardir. Yaqin o\'tkan-yillarda chet elda (AQSh, Kanada, Buyuk Britaniya va boshqa davlatlar) tushunchani almashtirish uchun «integratsiya» rag\'batlantiruvchi choralarni ijtimoiy siyosatga kiritish tushunchasi keladi \"Inklyuziv ta\'lim\" (Ispaniya, Salamanka, 1994). L.S.Vigotskiy bu g\'oyani birinchilardan bo\'lib asosladi integratsiyalashgan ta\'lim... Keyinchalik uning g\'oyasi G\'arbiy Evropa va AQSh maktablari amaliyotida amalga oshdi va faqat so\'nggi-yillarda u tobora ko\'proq o\'zlashtirila boshladi. Rossiyadan. Integratsiya jarayonlar boshlandi Rossiya faqat 90-yillarda... XX asr jahon axborot-ta\'lim makoniga kirishi tufayli. Bugungi kunda mamlakatimizda maxsus ta\'lim nogironlarni o\'qitish va hayotiy faoliyat sohasida umume\'tirof etilgan xalqaro standartlarga hali javob bermaydi. Mamlakatimiz uchun vazifa integratsiyalashgan ta\'lim davlat darajasida qaror qabul qilishni talab qiladi. Amalga oshirish imkoniyati haqida integratsiya jarayonlari e\'lon qilindi, lekin ta\'lim tizimi na iqtisodiy qo\'llab - quvvatlashga, na kerakli tayyorlikka ega (kadrlar, ma\'naviy va axloqiy, mazmunli va tashkiliy) ularni amalga oshirish uchun ommaviy ta\'lim. Bundan tashqari, zo\'ravonlik bilan ekish integratsiya maxsus yopilish (tuzatish) ta\'lim muassasalari bu jarayonni tezlashtirish va pulni tejash g\'oyani obro\'sizlantiradi integratsiya, jamiyat tomonidan uning axloqiy asoslarini o\'zlashtirish jarayonini murakkablashtiradi. Hozirda umumiy umumiy ta\'lim maktablarida Rossiyadan rivojlanish muammolari bo\'lgan bolalar ko\'p. Bu majburiy integratsiya(soxta integratsiya)... Uning sabablari bor: maxsus etishmasligi (tuzatish) ta\'lim muassasalari; bolaning va uning oilasining yashash joyidan uzoqligi; ota -onalarning xohlamasligi o\'rgatmoq bola maxsus muassasada; bir vaqtning o\'zida ommaviy maktabda tegishli infratuzilmani yaratmasdan ta\'lim organlarining ixtiyoriy qarori. Printsiplar Rossiya integratsiyalashgan ta\'lim tushunchasi: Integratsiya erta tuzatish orqali - birinchi va eng muhim tamoyil.\n\nBiz erta o\'rnatilgan dasturlar haqida gapirayapmiz (hayotning birinchi oylaridan boshlab) buzilgan funktsiyalarni tibbiypsixologik-pedagogik tuzatish, bu muammoli bolani psixofizik rivojlanish darajasiga olib chiqish imkonini beradi, bu unga umumiy ta\'lim muhitiga imkon qadar tezroq qo\'shilish imkoniyatini beradi. Umumiy ta\'lim bilan parallel ravishda ishlaydigan majburiy tuzatish bo\'limining mavjudligi. Integratsiya Ommaviy ta\'lim muassasalarida rivojlanishida nuqsoni bo\'lgan bolalar maxsus tuzatish yordami va psixologik yordam ko\'rsatadilar, ularning vazifalari bolaning rivojlanishi va uning muvaffaqiyatini nazorat qilishdir. o\'rganish, sog\'lom tengdoshlar muhitiga moslashish muammolarini hal qilishga ko\'maklashish. Aqli zaif bolalarga tabaqalashtirilgan yondashuv zarurati. Ta\'kidlash joizki, ba\'zi hollarda (masalan, emotsional irodali soha, xulq -atvor, bolaning noqulay ijtimoiy sharoitlari buzilgan taqdirda) afzalroqdir. o\'rganish va bolalarni maxsus tarbiyalash (tuzatish) ta\'lim muassasasi. Modellar integratsiya: birlashtirilgan integratsiya - integratsiya bunda psixofizik va nutqiy rivojlanish darajasiga ega, yosh normasiga mos keladigan yoki 1-2 yoshli bolalar ommaviy guruhlarda tarbiyalanadilar (sinflar, maxsus guruh o\'qituvchi-defektologidan doimiy tuzatuvchi yordam oladi) (sinf); qisman integratsiya - integratsiya bunda ta\'lim standartini hali o\'z tengdoshlari bilan teng darajada o\'zlashtira olmaydigan bolalar, kunning faqat bir qismini to\'kishadi. (masalan, uning ikkinchi yarmiga) ommaviy guruhlarga bo\'linadi (sinflar) 1-2 kishi; vaqtinchalik integratsiya - integratsiya, unda maxsus guruhning barcha o\'quvchilari (sinf) psixofizik va nutqning rivojlanish darajasidan qat\'i nazar, ular boshqa bolalar bilan har oyda kamida 2 marotaba birlashib, har xil tarbiyaviy tadbirlarni amalga oshiradilar; to\'liq integratsiya psixofizik va nutqning rivojlanish darajasi bo\'yicha yosh normasiga mos keladigan va sog\'lom tengdoshlari bilan birgalikdagi mashg\'ulotlarga psixologik tayyor bolalar uchun samarali bo\'lishi mumkin. o\'rganish... 1-2 kishilik bunday bolalar oddiy bolalar bog\'chalari guruhlariga yoki maktab sinflariga kiritiladi, shu bilan birga ular tuzatish yordamini mahalliy darajada olishlari shart. o\'rganish(masalan, bolalar bog\'chasining nutq markazida yoki maxsus bolalar bog\'chasida yoki maktabda yoki turli markazlarda qisqa muddatli qolish guruhida nutqida nuqsoni bo\'lgan bolalar. Bu modellarning barchasini amalga oshirish jarayonga majburiy rahbarlikni nazarda tutadi. integratsiya ta\'limni tashkil qilishda ommaviy o\'qituvchilarga yordam beradigan o\'qituvchi-defektolog tomonidan o\'rganish sog\'lom tengdoshlar jamoasida rivojlanishida nuqsoni bor bola Integratsiya Maxsus ta\'lim ehtiyojlari va nogironligi bo\'lgan shaxslar jamiyatida unga jamiyat hayotining barcha turlari va shakllarida (shu jumladan ta\'limda) teng huquqli va jamiyatning boshqa a\'zolari bilan ishtirok etish huquqlari va real imkoniyatlarini berish jarayoni va natijasi tushuniladi. rivojlanishdagi burilishlar va imkoniyatlarning cheklanishi uchun unga kompensatsiya beradigan sharoitda (Nazarova N.M., 2000).\n\nIntegratsiya \"normalizatsiya\" (Nirje, 1976) kontseptsiyasiga asoslangan bo\'lib, u nogironlarning hayoti va hayoti ular yashayotgan jamiyatning sharoitlari va turmush tarziga iloji boricha yaqin bo\'lishi kerak degan fikrga asoslangan. \"Normallashtirish\" tamoyillari bir qator xalqaro -huquqiy hujjatlarda mustahkamlangan: \"Bola huquqlari deklaratsiyasi\", \"aqli zaif\" shaxslar huquqlari deklaratsiyasi va \"nogironlar huquqlari deklaratsiyasi\". Bolalarga kelsak, bu quyidagilarni anglatadi. Maxsus ta\'lim ehtiyojlari bo\'lgan bolaning umumiy ehtiyojlari ham bor, ularning asosiysi muhabbat va rag\'batlantiruvchi muhitga bo\'lgan ehtiyojdir. Bola iloji boricha odatdagidek hayot kechirishi kerak. Bola uchun eng yaxshi joy - bu uning uyi va alohida ta\'limga muhtoj bolalarni o\'z oilasida tarbiyalashga rag\'batlantirish mahalliy hokimiyat zimmasida. Hamma bolalar o\'rganishi mumkin, demak, ularning rivojlanish buzilishlari qanchalik og\'ir bo\'lmasin, ularga ta\'lim olish imkoniyatini berish kerak. Shuni esda tutish kerakki, bunday odamlar uchun ta\'lim dasturlari nafaqat g\'amxo\'rlik va davolanishni o\'z ichiga olishi kerak ta\'lim va rivojlanish. Ushbu model rivojlanishining buzilishi sabablari va oqibatlarini klinik tadqiqotlar va ayrim kasalliklarning oldini olish va davolashning mumkin bo\'lgan usullari, natijada inson imkoniyatlarining cheklanishi bo\'yicha ilmiy tadqiqotlarning rivojlanishiga turtki bo\'ldi. Zamonaviy sharoitda bu model etarli emas, chunki bu alohida ehtiyojli odamning imkoniyatlarini cheklashdir. Odamdan tashqari model(rivojlanishida nuqsoni bo\'lgan odam o\'z darajasida hayvonga yaqinlashib kelayotgan pastroq jonzot sifatida qaraladi) nogironlarga nisbatan g\'ayriinsoniy muomaladan foydalanish uchun asos bo\'ldi. \"Jamiyatga tahdid\" modeli(rivojlanishida nuqsoni bo\'lgan shaxslarning ayrim toifalari jamiyat uchun xavf tug\'diradi) bu odamlar \"zarar yuborishi\", \"baxtsizlik keltirishi\", moddiy va ma\'naviy zarar etkazishi mumkin degan fikrga tayanadilar. Jamiyat o\'zini bu potentsial \"tahdid\" dan himoya qilib, ko\'pincha jamiyatdan uzoqda bo\'lgan, ba\'zida qattiq qamoqda saqlash rejimiga ega bo\'lgan maktab -internatlar, yopiq parvarish muassasalarini tashkil etdi. Bunday holda, mashg\'ulotlar yo\'q yoki etarli emas edi. Asosiy vazifa mkiyingan \"Achinish obyekti\"(nogiron odamga o\'sib ulg\'aymagan, bolaligida abadiy qoladigan kichkina bola sifatida qaraladi) faqat nogironni jamiyatdan ajratib, qulay yashash muhitini yaratish orqali atrofidagi \"yomon\" dunyodan himoya qilish, ta\'lim va taraqqiyotga yordam bermaslik.\n\nMarkaziy Osiyo davlatlari uzoq vaqt davomida Sobiq Ittifoq ta\'siri ostida bo\'lib keldi. 1922-yilda tuzilgan SSSR 1991-yilning 8-dekabrida amalda tugatildi. O\'tgan shuncha vaqt davomida Markaziy Osiyoning besh respublikasi har tomonlama Moskva ta\'siri ostida bo\'lib kelgan. Shunday ekan siyosiy qaramlik bilan birgalikda ta\'lim tizmi ham markazdan belgilab berilgan rejaga muvofiq amalga oshirilib kelingan.\n\n1991-yilda mintaqaning besh davlati birin-ketin mustaqillikka erisha boshladi. Siyosiy jihatdan mustaqil bo\'lgan bu davlatlar oldida juda ko\'p muammolar ko\'ndalang bo\'lib turar edi. Davlat rahbarlari birinchilardan bo\'lib boshqa sohalar kabi ta\'lim sohasining ham zamon ruhiga mos, milliy mentalitetdan kelib chiqqan holda qaytadan isloh qilishga o\'z e\'tiborlarini qaratdi. Lekin shuni ham ta\'kidlab o\'tishimiz lozimki, ta\'lim sohasini isloh qilish mintaqaning barcha davlatlarida birdek ketmagan. Chunki bu davlatlardagi siyosiy vaziyat ham bunga o\'z ta\'sirini ko\'rsatgan.\n\nEndi e\'tiborimizni mustaqillikka endigina erishgan Markaziy Osiyo davlatlarida ta\'lim tizmining holatiga qarataylik. So\'z yuritilayotgan vaqtda mintaqa davlatlari ta\'lim tizimi Sobiq Ittifoqning tegishli muassasalari tamonidan ishlab chiqilgan tizim asosida olib borilar edi. Bolaga ta\'lim berish dastlab bog\'chadan boshlanib, bu muassasada maktabgacha yoshdagi bolalar tarbiya olishgan. Keyingi bosqich maktab bo\'lib, bu bosqichda bolalar 11-yil yoki 8-yillik ta\'lim olishgan. Nima uchun aynan bolalarga 11 yoki 8-yil ta\'lim berilgan degan savol tug\'ilishi tabiiy holat. Ayrim bolalar 8-yil ta\'lim olgandan keyin kasb-hunarga yo\'naltirilgan, qolgan bolalar bo\'lsa maktabda ta\'lim olishni davom ettirgan. Lekin har doim ham oquvchilar 8-yillik ta\'limdan keyin o\'z xohishlariga ko\'ra kasb-hunarga yo\'naltirilavermagan. Maktabdan keyingi ta\'lim inistitutlarda olib borilgan. Bunda talabalarga 5-yillik (ayrim institutlarda ta\'lim olish muddati farqlanishi mumkin) ta\'lim berilgan. Bu vaqt davomida talaba o\'z mutaxassisligi bo\'yicha kerakli bilimlarni olib, keyingi faoliyatni xalq xo\'jaligining turli tarmoqlarida olib borishi mumkin bo\'lgan. Talabalarning ma\'lim bir qisimi ta\'lim olishni davom ettirib oliygohlarda o\'z mehnat faoliyatini ham olib borish imkoniyatiga ham ega bo\'lgan.\n\nYuqorida Markaziy Osiyo Respublikalarining SSSR ta\'siri ostida bo\'lgan vaqtlardagi ta\'lim tzimining umumiy holatini ko\'rib chiqdik. Tashqi ko\'rinishidan bu tizim juda mukammal ishlanganga o\'xshaydi. Haqiqatdan ham shunday bo\'lgan. Lekin har doim ham Ittifoq respublikalarida belgilab qo\'yilgan tartiblarga amal qilinmagan. Ta\'lim tizimida ham zamondan ortda qolish holatlari XX asr 70-yillari oxirlariga kelganda yaqqol namoyon bo\'la boshlagan. Ta\'lim muassasalarining moddiy texnik bazalari ham talab darajasida bo\'lmagan. Bundan tashqari yana ko\'plab kamchiliklarini sanab o\'tishimiz mumkin.\n\nSobiq Ittifoq parchalangandn keyin mintaqa respublikalari oldida ikkita yo\'l bor edi. Bu yo\'llardan biri ta\'lim SSSR tizimini saqlab qolish, yo bo\'lmasa zamon ruhiga mos yangi tizimni qabul qilish edi. Siyosiy vaziyatni to\'g\'ri tushungan mintaqaning bir qancha davlatlari ta\'lim tizimida islohot qilishni asta-sekin amalga oshirishni maqul ko\'rgan bo\'lsa, Tojikistondagi siyosiy beqarorlik bu tizimni isloh qilishni ortga surishga sabab bo\'ldi.\n\nXX asrning 80-yillaridan boshlab Markaziy Osiyo davlatlari ta\'lim tizimi bo\'yicha rivojlangan davlatlar ta\'lim tizimidan ortda qola boshlandi. Bu davrda rivojlangan davlatlarda ta\'lim tizimi zamon ruhiga mos ravishda o\'zgarishlar amalga oshirilmoqda edi. Misol sifatida Yevropa va AQSH ta\'lim muassasalarida zamonaviy ilg\'or texnologiyalarni joriy qilinayotgan bir vaqtda Markaziy Osiyo davlatlari ta\'limida bu texnologiyalar faqat nazariy jihatdan o\'rgatilar edi. Bu holat nafaqat Mrakaziy Osiyo davlatlarida, Ittifoqning boshqa davlatlarida ham shu ko\'rinishda edi. Mustaqillikka erishgandan keyin ham bu respublikalar zamonaviy texnologiyalarni ta\'limga birdaniga joriy qila olmas edi. Sababi davlatlarning iqtisodiy holati havas qilar darajada bo\'lmagan.\n\nEndi asosiy e\'tiborimizni Markaziy Osiyoning mustaqillikka erishgan ilk-yillaridagi ta\'lim muassasalarining holatiga e\'tiborimizni qaratamiz. Dastlab mintaqaning shimoliy qismida joylashgan Qozog\'istondagi ta\'lim muassasalarining holati bilan tanishib chiqamiz. 1991-yilda Qozog\'iston mustaqilikka erishgan davrida mamlakatda ta\'lim muassalarining umumiy soni 17 783 tani tashkil qilgan. Bu sondan ko\'rinib turibdiki ta\'lim muassasalari respublika aholisi soniga nisbatan bo\'lganda yaxshi ko\'rsatkichni tashkil qilgan. 17 783 tadan 8 881 tasi maktabgacha ta\'lim muassasasi, 8 841 tasi maktab va 61 tasi bo\'lsa oliy ta\'lim muassasasi bo\'lgan.\n\nQozog\'istonda 1991-yilda mavjud 8 881 ta maktabgacha ta\'lim muassasasida 1 067 814 nafar bolalar tarbiyalangan. Bu davrda davlatda bog\'cha yoshidagi bolalarning umumiy soni 2 300 000 nafardan ko\'p bo\'lgan. Shundan kelib chiqib, Qozog\'istonda maktabgacha ta\'lim muassasalarida shu yoshdagi bolalarning 43 % tarbiyalangan. Bu sonlar bilan birgalikda muassasalarning holatiga ham e\'tibor qaratsak. Mavjud 8881 ta maktabgacha ta\'lim muassasasining 40 % dan ortiqrog\'i talab darajasida bo\'lmagan. Bu bog\'chalarning moddiy-texnik bazasi qoniqarsiz holatda bo\'lgan. Yana 20 % bo\'lsa belgilangan me\'yorga bazo\'r javob bera olgan. Talab darajasidagi maktabgacha ta\'lim muassasalari davlatning katta shaharlari markazlarida, shimoliy hududlarda joylashgan. Bu ta\'lim muassasalarining ko\'pchiligida rusiy zabon aholining farzandlari tarbiya olishgan.\n\nSo\'z yuritilayotgan davrda Qozog\'iston maktablarining umumiy soni 8841 tani tashkil qilgan bo\'lsada, ularning yarimidan ortig\'i belgilangan talabga javob bermagan. Maktablarning ko\'pchilik qismi avariya holatida bo\'lgan. Bunday maktablar asosan ovul va qishloqlarda joylashgan. Maktablarning ko\'pchiligining moddiy-texnik bazasi talabga javob bermagan. Bunda ham markazda joylashgan maktablarning holati talab darajasida bo\'lgan. Rus tilida ta\'lim beriladigan maktablar, qozoq va boshqa tillarda ta\'lim beriladigan maktablardan holati ancha yaxshi bo\'lgan.\n\nQozog\'istonda 1991-yilda 61 ta oliy ta\'lim muassasasi faoliyat yuritgan bo\'lsa, ularning ham holati turlicha bo\'lgan. Oliy ta\'lim tizimida ham ta\'lim berilishi rivojlangan davlatlar bilan taqqoslaganda past ko\'rsatkich qayd qilgan. Ko\'plab muassasalarning holati talab darajasida bo\'lmagan. Oliy ta\'limda ham rus tili boshqa tillarga qaraganda ancha ustunlik qilgan.\n\nMustaqillikka endigina erishgan Qozog\'iston oldida yuqorida sanab o\'tgan kamchiliklarni bartaraf qilish vazifasi turar edi. Qozog\'iston hukumati bu sohani isloh qilishni mustaqilikning ilk-yillaridan boshladi.\n\nQozog\'istonga qo\'shni bo\'lgan Qirg\'iziston ham 1991-yil 31-avgustda mustaqil bo\'ldi. Mustaqillika erishgan vaqtda mamlakatda 3369 ta ta\'lim muassasasi faoliyat yuritgan. Bu muassasalarning ko\'pchiligning avariya holatida bo\'lgan.Mavjud 3369 ta ta\'lim muassasasidan 1600 tasi makatabgacha ta\'lim muassasasi, 1759 tasi maktab va 10 tasi oliy va o\'rta ta\'lim muassasasi bo\'lgan.\n\nMustaqillikka erishgan Qirg\'izistonda makatabgacha ta\'lim muasasasalarini holati havasi qilar darajada bo\'lmagan. Mavjud 1600 ta maktabgacha ta\'lim muassasasining yarimidan ko\'prog\'i talab darajasida bo\'lmagan. Ko\'plarining binolari avariya holatida bo\'lib, istish va kanalizatsiya tizimi bilan ta\'minlanmagan. Bu holatdagi maktabgacha ta\'lim muassasalarining ko\'pchiligi respublikaning qishloq hududlarida joylashgan. Davlatning katta shahar markazlarida joylashgan muassasalarining holati anchagina yaxshi bo\'lgan. Misol sifatida Bishkek shahrida joylashgan 220 dan ziyod makatabgacha ta\'lim muasasasidan atigi 32 tasining holati qoniqarsiz bo\'lgan. Lekin shahar markazlarida joylashgan maktabgacha ta\'lim muassasalarida rus tilida tarbiya berish holatlari ko\'p uchragan.\n\nRespublikada mavjud 1 759 ta makatabning 40 % talab darajasida bo\'lgan. Qolgan 60 % bo\'lsa belgilangan standart talablariga mos kelmagan. Talab darajasida bo\'lmagan maktablarning kattagina qismi asosan qishloq va shahar chekkasi hududlariga to\'g\'ri kelgan.\n\nMamlakatdagi oliy ta\'lim muassasalari soni 10 tani tashkil qilgan bo\'lsa-da, ularning atigi 3 tasining holati qoniqarli darajada bo\'lgan. Qolgan 7 tasining moddiy-texnik bazasi anchagina kambag\'al bo\'lgan. Ayrim muassasalarning binolari talab darajasida bo\'lmagan.\n\nTojikistonda ta\'lim muassasalarining holati 1991-yilda mintaqaning boshqa respubliklaridagidan deyarli katta farq qilmagan. Mamlakatdagi mavjud 4401 ta ta\'lim muassasasidan 944 tasi maktabgacha ta\'lim muassasasi, 3443 tasi maktab va 14 tasi oliy ta\'lim muasasasi bo\'lgan.\n\nMamlakatdagi mavjud 944 ta bog\'chada jami 141 500 nafar bola tarbiyalangan. Bu o\'sha vaqtdagi davlatdagi jami bog\'cha yoshidagi bolalarning 30 % ni tashkil qilgan. Bu raqamlardan ko\'rinib turibdiki, Tojikistonda Sobiq Ittifoq davrida ham maktab yoshigacha bo\'lgan bolalarning katta qismi uy sharoitioda tarbiyalangan. Mavjud bog\'chalarning ham katta qismining moddiy-texnik bazasi talab darajasida bo\'lmagan.\n\nTojikistonda 1991-yilda mavjud 3 443 ta maktabda jami 1 325 400 nafar bola ta\'lim olgan. Tojikistonda ham boshqa respubliklarda bo\'lgani kabi maktablarning kattagina qismi talabga javob bermagan. Bu holat ayniqsa respublikaning to\'g\'li qishloq hududlariga to\'g\'ri keladi. Davlatning katta shaharlaridagi maktablarining ko\'pchiligida ta\'lim rus tilida olib borilgan.\n\nMamlakatdagi 14 ta oliy ta\'lim muassasalarining ko\'pchiligining holati yaxshi darajada bo\'lmagan. Dushanbe shahrida joylashgan 1947-yilda tashkil etilgan Tojikiston davlat milliy universitetini moddiy-texnik bazasini Ittifoqning markaziy shaharlarida joylashgan universitetlar bilan taqqoslaganimizda ancha katta tafovutga duch kelishimiz mumkin.\n\nTurkmaniston Markaziy Osiyoning janubi-g\'arbida joylashgan bo\'lib, kattagina qismini cho\'llar tashkil qiladi. Turkmaniston ham mustaqillikning dastlabki davridan ta\'lim tizimini isloh qilish harakatlarini boshlagan. Ushbu davrda Turkmanistonda jami 2726 ta ta\'lim muasasasi faoliyat yuritgan. Shundan 920 tasi maktabgacha ta\'lim muassasasi, 1880 tasi maktab, 6 ta oliy ta\'lim muassasasidan iborat bo\'lgan.\n\nTurkmanistonda ham maktabgacha ta\'lim muassasalarining ko\'pchilik qismining holati talab darajasida bo\'lmagan. 920 ta makatabgacha ta\'lim muassasasining atigi 35 % har tamonlama belgilangan tartibga javob bergan. Qolgan qismi bo\'lsa talab darajasida bo\'lmagan.\n\nDavlatda 1991-yilda mavjud 1800 ta maktabning 55 % talab darajasida bo\'lgan. 1991-yilda maktablarda tahsil olayotgan o\'quvchilarning umumiy soni 890 ming nafarni tashkil qilgan. 55 ming nafar o\'qituvchi maktablarda faoliyat yuritgan. Turkmanistondagi mavjud 1800 ta maktabning 180 tasi rus tilida o\'qitishga mo\'ljallangan bo\'lsa, 90 nafari o\'zbek tilida dars berilgan. Bundan tashqari turkman tilida dars beriladigan maktablarda ham rus tilining o\'tishga katta e\'tibor qaratilgan.\n\nTurkmanistonda 1991-yilda mavjud bo\'lgan 6 ta oliy ta\'lim muassasasining holati ham mintaqaning boshqa davlatlaridagi inistitutlardan farqlanmagan. Bu oliy ta\'lim muasasalarida o\'qitladigan fanlar, ularning moddiy bazasi talab darajasidan past bo\'lgan.\n\nMarkaziy Osiyoning o\'rtasida joylashgan O\'zbekistonda ham 1991-yilda ta\'lim muassalarining umumiy holati qolgan to\'rt respublikanikidan keskin farq qilmagan. O\'zbekistondagi ta\'lim muassasalarining ham moddiy-texnik bazasi Ittifoqning markaziy hududlari bilan taqqoslaganimizda katta farqni ko\'rishimiz mumkin.\n\nBarcha respublikalarda ta\'lim muassasalarining kattagina qismining moddiy-texnik holati talab darajasida bo\'lmagan. Shu bilan birgalikda ta\'lim muassasalarida ishlayotgan pedagog xodimlarning ham ko\'pchiligining bilim saviyasi yetarli darajada emasdi.\n\nMintaqa davlatlari maktablarida o\'qitiladigan darsliklarida ham keskin farq bo\'lgan. Mahalliy tildagi darsliklarga qaraganda rus tilida yozligan darsliklar anchagina sifatli bo\'lgan. Oliy ta\'lim muassasalarida o\'qitiladigan fanlar bo\'yicha adabiyotlarning kattagina qismi rus tilida bo\'lgan. Bu esa rus tilini bilmagan ko\'plab yoshlarga bir qator muammolarni keltirib chiqargan. Chunki Markaziy Osiyo davlatlarida aholining barcha qatlami ham rus tilini yaxshi bilmagan. Rus tilini asosan shahar va uning atrofida yashovchi aholi yaxshi bilgan. Qishloqlardan shaharga kelayotgan yoshlarning kattagina qismi rus tilini unchalik ham yaxshi bilmagan.\n\nXullas, 1991-yilda mustaqilikka erishgan mintaqaning besh respublikasi oldida yuqorida sanab o\'tgan muammolar turar edi. Hukumat tepasiga kelgan rahbarlar ta\'lim tizimini isloh qilmay turib katta maqsadlarga erishib bo\'lmasligini yaxshi tushungan. Shuning uchun ham ular mustaqillikning ilk kunlaridan bu sohada islohot qilish uchun harakatlarni boshlab yubordi.\n\nFoydalanilgan adabiyotlar\n\n1. Andrianov A. Rossiyaning JST // MARKAZIDA QO\'ShIMChA muammolari va istiqbollari. 2004. № 2. -c. 98.\n\n2. ASTAPOV K. MDH mamlakatlarining yagona iqtisodiyotini shakllantirish // Jahon iqtisodiyoti va xalqaro munosabatlar. 2005. № 1. -C. 289.\n\n3. Axmedov AXS JSTga va mehnat bozoriga kirish. - Moskva, 2004. - 67.\n\n4. Ayatskov D. Integratsiya uchun alternativalar mavjud emas // Iqtisodiy Iqtisodiyot Iqtisodiy qo\'mitasi. Axborot byulleteni. - M. - 2004-yil yanvar. 23.\n\n5. Belomov R. Rossiyaning iqtisodiyoti yaqin kelajakda. // Ecentist 2007, 7-bet, p. 89.', 'LTXMBF7yBy0', 15, 25, '2026-11-06 09:32:37'),
(30, 4, 30, '15-Amaliyot: Xalqaro tajribalarni qiyosiy o\'rganish va shaxsiy kasbiy rivojlanish traektoriyasini tuzish', 'practice', '# 15-AMALIYOT: XALQARO TAJRIBALARNI QIYOSIY O\'RGANISH VA SHAXSIY KASBIY RIVOJLANISH TRAEKTORIYASINI TUZISH\n\n### 🎯 Mashg\'ulotning asosiy maqsadi:\nNazariy bilimlarni bevosita sinf amaliyotida, simulyatsion dars bosqichlari va pedagogik keyslar orqali qo\'llash ko\'nikmalarini shakllantirish.\n\n### 📋 Amaliy ish bosqichlari:\n1. **Didaktik maqsadni belgilash:** Boshlang\'ich sinf o\'quvchilarining yosh xususiyatlariga mos vazifalar tanlash.\n2. **Interfaol metodlarni qo\'llash:** Mavzuga mos klaster, aqliy hujum, keys-stadi yoki loyiha metodini dars bosqichlariga kiritish.\n3. **Refleksiv tahlil:** Dars yakunida o\'quvchilarning o\'zlashtirish darajasini va o\'qituvchining o\'z faoliyatini xolisona baholash.\n\n### 💡 Metodik ko\'rsatma:\nUshbu amaliy mashg\'ulot M.B. Muxamadaliyeva tomonidan ishlab chiqilgan **operatsion-faoliyatli** va **refleksiv** komponentlarni rivojlantirishga qaratilgan bo\'lib, bo\'lajak o\'qituvchining darsni mustaqil loyihalay olish mahoratini oshiradi.\n', 'LTXMBF7yBy0', 20, 35, '2026-11-06 09:32:37');
INSERT INTO `modules` (`id`, `order`, `title`, `description`, `pedagogical_component`, `xp_reward`, `created_at`) VALUES
(1, 1, '1-Modul: Boshlang\'ich ta\'lim pedagogikasi asoslari va metodologiyasi', 'Boshlang\'ich ta\'lim pedagogikasining maqsadi, vazifalari, ilmiy-tadqiqot metodlari, zamonaviy tendensiyalari va innovatsion yondashuvlar.', 'kognitiv', 250, '2026-11-06 09:32:34'),
(2, 2, '2-Modul: Didaktika, loyihalash texnologiyasi va zamonaviy metodlar', 'Masofaviy ta\'lim tizimi, interfaol metodlar (Aqliy hujum, Klaster), loyihalash texnologiyasi va bolalar jamoasida tarbiyaviy jarayon.', 'operatsion-faoliyatli', 250, '2026-11-06 09:32:34'),
(3, 3, '3-Modul: Fanlararo integratsiya va o\'quvchilar motivatsiyasi', 'Integratsiya tamoyili, boshlang\'ich sinf darslarini o\'zaro bog\'lash metodikasi, mavzuli kunlar va o\'quvchilar bilish motivatsiyasi.', 'motivatsion', 250, '2026-11-06 09:32:34'),
(4, 4, '4-Modul: Pedagogik mahorat, maktab-oila integratsiyasi va refleksiv tahlil', 'Oila va maktab hamkorligi, o\'qituvchining kreativligi, xalqaro ta\'limiy tajribalar hamda kasbiy faoliyat refleksiyasi.', 'refleksiv', 250, '2026-11-06 09:32:34');
