(143, 2, 15, 'lesson', 3, 'Metodlarni optimal tanlashga qanday talablar qo\'yiladi? (metodning optimalligini nima belgilaydi?)', '[\"Dars maqsadi, predmetning va mavzuning xususiyati, vaqt, sharoit, o\'quv bazasi, o\'qituvchi mahorati, o\'quvchilarning yoshi va tayyorlik darajasi\", \"Sinf o\'quvchilarining imkoniyati, o\'qituvchining shaxsiy imkoniyati va mahorati, maktab sharoiti\", \"Faoliyatning xususiyati, bolaning anatom-fiziologik xususiyati, ruhiyati, ilmiy fikr mantig\'i\", \"O\'quvchi o\'zlashtirishga ta\'sir etadigan ichki va tashqi sabablar, maktabning o\'quv bazasi\"]', 0, 'To\'g\'ri javob: «Dars maqsadi, predmetning va mavzuning xususiyati, vaqt, sharoit, o\'quv bazasi, o\'qituvchi mahorati, o\'quvchilarning yoshi va tayyorlik darajasi». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(144, 2, 15, 'lesson', 4, 'Dars tiplari qaysilar?', '[\"Yangi bilim berish darsi, umumlashtirish-tizimlashtirish darsi, takroriy-qaytarish darsi, nazorat darslari, aralash dars\", \"Turli mashg\'ulotlar qatnashadigan dars, sinov-mavzuli dars, kino dars, ma\'ruza darsi\", \"Konferentsiya-darsi, matbuot konferentsiyasi darslari, uchrashuv\", \"Aralash dars, kitob bilan ishlash, umumlashtirish\"]', 0, 'To\'g\'ri javob: «Yangi bilim berish darsi, umumlashtirish-tizimlashtirish darsi, takroriy-qaytarish darsi, nazorat darslari, aralash dars». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(145, 2, 15, 'lesson', 5, 'Innovatsion yondoshuv nima?', '[\"Muammoni yechish uchun yangicha yondashuv yoki yangi texnologik jarayonni qo\'llash\", \"Turli maqsadlar shajarasini ishlab chiqish va vazifalarni amalga oshirish\", \"Tartibga solish va nazorat qilish\", \"Zamon ehtiyojiy talablaridan kelib chiqib boshqarishni yo\'lga qo\'yish\"]', 0, 'To\'g\'ri javob: «Muammoni yechish uchun yangicha yondashuv yoki yangi texnologik jarayonni qo\'llash». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(146, 2, 15, 'lesson', 6, 'O\'qitish usuli (metodlari) deganda nima tushuniladi?', '[\"O\'qituvchi va o\'quvchilarning o\'qish vazifalarini bajarishga qaratilgan nazariy va amaliy bilish faoliyatini uyushtirish usuli va amalga oshirish yo\'li\", \"Bilimlarni bayon qilish, mashqlantirish, amaliy ishlar olib borish\", \"Ta\'lim vazifasini hal qilishga qaratilgan o\'qituvchi va o\'quvchilarning birgalikdagi faoliyatini belgilash yo\'li va vositasi\", \"O\'qitishni amalga oshirish va bolalar bilish faoliyatiga rahbarlik qilish\"]', 0, 'To\'g\'ri javob: «O\'qituvchi va o\'quvchilarning o\'qish vazifalarini bajarishga qaratilgan nazariy va amaliy bilish faoliyatini uyushtirish usuli va amalga oshirish yo\'li». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(147, 2, 15, 'lesson', 7, 'O\'qitish jarayonida nazoratning rivojlantiruvchi funksiyasini toping', '[\"O\'z-o\'zini nazorat qilish va baholash\", \"Xotirani mustahkamlash\", \"O\'quvchilarda barqaror diqqatni vujudga keltirish\", \"Baholash\"]', 0, 'To\'g\'ri javob: «O\'z-o\'zini nazorat qilish va baholash». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(148, 2, 15, 'lesson', 8, 'Masofadan o\'qitish qanday amalga oshiriladi?', '[\"Kommunikatsion texnologiyalar orqali\", \"O\'quv adabiyotlari orqali\", \"Kompyuter texnikasi orqali\", \"T\'yutorlar yordamida\"]', 0, 'To\'g\'ri javob: «Kommunikatsion texnologiyalar orqali». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(149, 2, 15, 'lesson', 9, 'Innovatsiya nima?', '[\"Innovatsiya – yangilik kiritish\", \"Innovatsiya – yangicha ta\'lim\", \"Innovatsiya - dasturlashtirilgan ta\'lim\", \"Innovatsiya - muammoli ta\'lim\"]', 0, 'To\'g\'ri javob: «Innovatsiya – yangilik kiritish». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(150, 2, 15, 'lesson', 10, 'Kompetensiya nima?', '[\"Kompetensiya-bilim, ko\'nikma, malaka, qobiliyat, qarashlar, shaxsning malakasi yoki ish yuritish qobiliyatlarining namoyon bo\'lishini belgilab beradigan shaxsiy sifatlar va qadriyatlar yig\'indisi\", \"Kompetensiya-xulq-atvor, bilim, malaka, munosabat, motiv\", \"Kompetensiya- o\'z-o\'zini namoyon qilish, boshqa odamlar bilan ijtimoiy muloqotda bo\'lish, o\'z ustida tinimsiz ishlash\", \"Kompetensiya- vaziyatni baholash va muammolarni yechish ko\'nikmasiga ega bo\'lish, tashkilotchilik, ijodiy yondashuv, boshqaruv ko\'nikmasiga ega bo\'lish\"]', 0, 'To\'g\'ri javob: «Kompetensiya-bilim, ko\'nikma, malaka, qobiliyat, qarashlar, shaxsning malakasi yoki ish yuritish qobiliyatlarining namoyon bo\'lishini belgilab beradigan shaxsiy sifatlar va qadriyatlar yig\'indisi». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(151, 2, 16, 'lesson', 1, 'Kompetensiya nima?', '[\"Kompetensiya-bilim, ko\'nikma, malaka, qobiliyat, qarashlar, shaxsning malakasi yoki ish yuritish qobiliyatlarining namoyon bo\'lishini belgilab beradigan shaxsiy sifatlar va qadriyatlar yig\'indisi\", \"Kompetensiya-xulq-atvor, bilim, malaka, munosabat, motiv\", \"Kompetensiya- o\'z-o\'zini namoyon qilish, boshqa odamlar bilan ijtimoiy muloqotda bo\'lish, o\'z ustida tinimsiz ishlash\", \"Kompetensiya- vaziyatni baholash va muammolarni yechish ko\'nikmasiga ega bo\'lish, tashkilotchilik, ijodiy yondashuv, boshqaruv ko\'nikmasiga ega bo\'lish\"]', 0, 'To\'g\'ri javob: «Kompetensiya-bilim, ko\'nikma, malaka, qobiliyat, qarashlar, shaxsning malakasi yoki ish yuritish qobiliyatlarining namoyon bo\'lishini belgilab beradigan shaxsiy sifatlar va qadriyatlar yig\'indisi». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(152, 2, 16, 'lesson', 2, 'Didaktik kompetensiya nimalardan iborat?', '[\"O\'quv jarayoni va o\'qish jarayonini boshqarish o\'quvchilar bilimini anglash va ularni rivojlantirish\", \"Ta\'limni uzluksiz ta\'minlash, bilimini anglash va ularni rivojlantirish\", \"Ta\'lim-tarbiya birligi va rejalashtirish, bilimini anglash va ularni rivojlantirish\", \"O\'quvchilarga yordam ko\'rsatish, bilimini anglash va ularni rivojlantirish\"]', 0, 'To\'g\'ri javob: «O\'quv jarayoni va o\'qish jarayonini boshqarish o\'quvchilar bilimini anglash va ularni rivojlantirish». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(153, 2, 16, 'lesson', 3, 'Kasbiy kompetensiya modeli o\'z ichiga nimalarni oladi?', '[\"Kasbiy qadriyat va ustanovka, kasbiy bilim va tushuncha, kasbiy ko\'nikma va malaka\", \"Kommunikatsiya nutqiy, ijtimoiy –madaniy, tilni chuqur bilish, kasbiy ko\'nikma va malaka\", \"Ijodiy faoliyatda o\'zi o\'zlashtirgan bilim, ko\'nikma, malakalarni, analiz va sintez qilish\", \"Pedagogik faoliyatini muvofiqlashtirish shaxsiy yutuqlarni boshqarishi, o\'zini anglash va kasbiy o\'sish\"]', 0, 'To\'g\'ri javob: «Kasbiy qadriyat va ustanovka, kasbiy bilim va tushuncha, kasbiy ko\'nikma va malaka». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
