(273, 4, 28, 'lesson', 3, '… - Tizimlashtirilgan yangi o\'quv jarayoni prognoztikasi va ma\'lumotlar majmui.', '[\"Innovatsion pedagogik g\'oya\", \"Innovatsion ta\'lim\", \"Innovatsion texnologiya\", \"Innovatsion o\'qitish\"]', 0, 'To\'g\'ri javob: «Innovatsion pedagogik g\'oya». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(274, 4, 28, 'lesson', 4, '… - Ta\'lim sohasiga kiritilgan va kiritilayotgan yangiliklar hamda yangilangan ta\'lim jarayoni', '[\"Innovatsion ta\'lim\", \"Innovatsion pedagogik g\'oya\", \"Innovatsion texnologiya\", \"Innovatsion o\'qitish\"]', 0, 'To\'g\'ri javob: «Innovatsion ta\'lim». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(275, 4, 28, 'lesson', 5, 'Qaysi ta\'lim tizimida o\'quvchi berilgan dasturni qanchalik tez o\'zlashtirsa, shunchalik tez o\'qishini tugatadi va o\'qitishni tugatganligi to\'g\'risida sertifikat oldi.', '[\"Masofaviy ta\'lim tizimi\", \"Kunduzgi ta\'lim tizimi\", \"Kechki ta\'lim tizimi\", \"Sirtqi ta\'lim tizimi\"]', 0, 'To\'g\'ri javob: «Masofaviy ta\'lim tizimi». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(276, 4, 28, 'lesson', 6, 'Qayerda butun-yil davomida faoliyat yuritadi. Ayni paytda, o\'quvchilar har 45 kundan keyin 2 hafta ta\'tilga chiqishadi. Shu tariqa o\'quvchilar butun-yil davomida an\'anaviy maktablardagidek soatlar hajmida sinfda bo\'lishadi?', '[\"AQSh\", \"Germaniya\", \"Finlandiya\", \"Yaponiya\"]', 0, 'To\'g\'ri javob: «AQSh». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(277, 4, 28, 'lesson', 7, '… Bu – sarflanayotgan mablag\' va kuchdan eng yuqori va sifatli natija olishdan iborat.', '[\"Innovatsiyaning maqsadi\", \"Innovatsion muhit\", \"Novator\", \"Yangilikni uzatish\"]', 0, 'To\'g\'ri javob: «Innovatsiyaning maqsadi». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(278, 4, 28, 'lesson', 8, '… – Bu pedagogik jamoada, umuman, ta\'lim muassasasida shunday ijodiy, samimiy, do\'stona sharoit tug\'diradiki, unda o\'qituvchi o\'zini erkin his qiladi, jamoada ichki intilish, moddiy, ma\'naviy qiziqish yuqori darajada bo\'ladi.', '[\"Innovatsion muhit\", \"Innovatsiyaning maqsadi\", \"Novator\", \"Yangilikni uzatish\"]', 0, 'To\'g\'ri javob: «Innovatsion muhit». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(279, 4, 28, 'lesson', 9, '… - Bu yangilikni qabul qilish va amalga oshirishga tayyor shaxs.', '[\"Novator\", \"Innovatsion muhit\", \"Innovatsiyaning maqsadi\", \"Yangilikni uzatish\"]', 0, 'To\'g\'ri javob: «Novator». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(280, 4, 28, 'lesson', 10, 'O\'qituvchi hamda o\'quvchilar faoliyatini o\'z ichiga oladigan jarayon bu ….', '[\"O\'qitish jarayoni\", \"Ta\'lim va Tarbiya jarayoni\", \"Hamkorlik jarayoni\", \"Mustaqil ishlar jarayoni\"]', 0, 'To\'g\'ri javob: «O\'qitish jarayoni». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(281, 4, 29, 'lesson', 1, 'Masofaviy ta\'limning tarkibiy qismlariga qaysilar kiradi?', '[\"O\'qituvchi, o\'quvchi va kommunikatsiya.\", \"O\'qituvchi va o\'quvchi\", \"Ta\'lim va tarbiya\", \"Moddiy va ma\'naviy\"]', 0, 'To\'g\'ri javob: «O\'qituvchi, o\'quvchi va kommunikatsiya.». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(282, 4, 29, 'lesson', 2, 'Qanday ta\'lim tizimi insonparvarlik prinsipiga asoslanadi. Ya\'ni hech kim kambag\'allik, geografik muammolar ijtimoiy himoyalanganlik va boshqa sabablar tufayli bilim olish huquqidan mahrum bo\'lmasligi lozim.', '[\"Masofaviy ta\'lim tizimi\", \"Offline ta\'lim tizimi\", \"Kechki ta\'lim tizimi\", \"Sirtqi ta\'lim tizimi\"]', 0, 'To\'g\'ri javob: «Masofaviy ta\'lim tizimi». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(283, 4, 29, 'lesson', 3, '… – Pedagogik taraqqiyotni ta\'minlashga qaratilgan yangi tashkiliy faollik vositalari, usullari va metodlari.', '[\"Innovatsion texnologiya\", \"Innovatsion pedagogik g\'oya\", \"Innovatsion ta\'lim\", \"Innovatsion o\'qitish\"]', 0, 'To\'g\'ri javob: «Innovatsion texnologiya». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(284, 4, 29, 'lesson', 4, '… – Qabul qilingan va qismlarga ajratilgan yangi pedagogik g\'oyalar hamda fikrlar.', '[\"Innovatsion muhit\", \"Innovatsion vaziyat\", \"Innovatsion pedagogik loyiha\", \"Innovatsion pedagogik reja\"]', 0, 'To\'g\'ri javob: «Innovatsion muhit». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(285, 4, 29, 'lesson', 5, 'O\'qituvchi-konsultant kim?', '[\"Tyutor\", \"O\'qituvchi\", \"Tarbiyachi\", \"Metodist\"]', 0, 'To\'g\'ri javob: «Tyutor». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(286, 4, 29, 'lesson', 6, 'Masofaviy ta\'lim texnologiyasi quyidagi imkoniyatlarga ega: 1. masofaviy ta\'lim o\'qish va o\'qitish jarayoniga ijobiy yondashuvni ta\'minlaydi. 2. pedagogik jarayonning maqsadi sifatida ta\'lim oluvchiga aniq yo\'nalish beradi, 3. metodologik va nazariy bilimlarni kutilgan darajada egallash imkoniyatlarini yaratadi, 4. bilimlarni chuqur va erkin o\'zlashtirishga yordam beradi. 5. jamoaviy tarzda bilimlar o\'zlashtiriladi. 6. bilish faoliyatini mustaqil tashkil etish sharoitlarini beradi, 7. ta\'limning turli axborotlarini topish va o\'zlashtirish imkoniyatlarini beradi.', '[\"1,2,3,6,7\", \"1,2,3,4,5,6,7\", \"3,4,5,6,7\", \"1,2,3,4,6,7\"]', 0, 'To\'g\'ri javob: «1,2,3,6,7». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(287, 4, 29, 'lesson', 7, 'Elektron – modulli o\'qitish texnologiyasi ….', '[\"Kompyuter kabi texnik o\'quv jihozlardan foydalangan holda ta\'lim berish majmuidir.\", \"Darsliklar, o\'quv adabiyotlari va qo\'llanmalari muhim o\'rin tutadi.\", \"Ta\'lim resurslaridan oqilona foydalaniladi.\", \"Bo\'lajak boshlang\'ich sinf o\'qituvchilariga tegishli kompetensiya beriladi.\"]', 0, 'To\'g\'ri javob: «Kompyuter kabi texnik o\'quv jihozlardan foydalangan holda ta\'lim berish majmuidir.». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(288, 4, 29, 'lesson', 8, 'Hozirgacha mavjud didaktik tizimda ta\'lim jarayoni 7 ta elementni o\'z ichiga olar edi: Ular qaysilar?', '[\"Ta\'lim maqsadi, ta\'lim mazmuni, o\'qituvchilar, o\'quvchilar, ta\'limning shakli, vositasi va metodlari.\", \"Ta\'lim maqsadi, tarbiya, o\'qituvchilar, o\'quvchilar, ta\'limning shakli, vositasi va metodlari.\", \"Ta\'lim maqsadi, ta\'lim mazmuni, o\'qituvchilar, elementlari, ta\'limning shakli, vositasi va metodlari.\", \"Ta\'lim maqsadi, ta\'lim mazmuni, o\'qituvchilar, o\'quvchilar, ta\'limning shakli, usul va uslublari.\"]', 0, 'To\'g\'ri javob: «Ta\'lim maqsadi, ta\'lim mazmuni, o\'qituvchilar, o\'quvchilar, ta\'limning shakli, vositasi va metodlari.». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(289, 4, 29, 'lesson', 9, '… Bu - motiv - maqsad - vazifa - mazmun - shakl - metodlar - metodika komponentlari yig\'indisi.', '[\"Faoliyat tuzilmasi\", \"Sub\'ektiv tuzilma\", \"Sathiy tuzilma\", \"Mazmun tuzilmasi\"]', 0, 'To\'g\'ri javob: «Faoliyat tuzilmasi». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(290, 4, 29, 'lesson', 10, '… Bu - innovatsion faoliyat sub\'ektlarining xalqaro, mintaqaviy, tuman, shahar va boshqa sathlar.', '[\"Sub\'ektiv tuzilma\", \"Faoliyat tuzilmasi\", \"Sathiy tuzilma\", \"Mazmun tuzilmasi\"]', 0, 'To\'g\'ri javob: «Sub\'ektiv tuzilma». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(291, 4, 30, 'lesson', 1, 'Breynshtorming - g\'oyalarni generatsiya qilish usuli. Ikkinchi nomini toping', '[\"“Aqliy hujum”\", \"“Blits-so\'rov”\", \"“Bumerang”\", \"“Ortiqchasini top”\"]', 0, 'To\'g\'ri javob: «“Aqliy hujum”». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(292, 4, 30, 'lesson', 2, 'Bu o\'qitish usulining mohiyati shundan iboratki, unda munozara yoki o\'quv suhbati amaliy usul bilan bog\'lanib ketadi. Uning afzallik funksiyalari- rivojlantiruvchi va tarbiyalovchi vazifadir: o\'quvchilarda muloqat yuritish va munozara olib borish madaniyati shakllanadi, o\'z fikrini faqat og\'zaki emas, balki yozma ravishda bayon etish mahorati, mantiqiy va tizimli fikr yuritish ko\'nikmasi rivojlanadi. Qaysi uslub haqida gap boryapti?', '[\"Pinbord usuli\", \"“Aqliy hujum”\", \"“Blits-so\'rov”\", \"“Bumerang”\"]', 0, 'To\'g\'ri javob: «Pinbord usuli». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(293, 4, 30, 'lesson', 3, 'Sinkveyn- fransuz tilida qanday ma\'noni bildiradi?', '[\"5 qator\", \"5 ustun\", \"5 zanjir\", \"5 mulohaza\"]', 0, 'To\'g\'ri javob: «5 qator». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(294, 4, 30, 'lesson', 4, '…. Bu - yechilishi zarur bo\'lgan muammoni qamrab olgan haqiqiy vaziyat ifodasi, tinglovchilar tomonidan muhokama qilinishi mumkin bo\'lgan va odatda qaror qabul qiluvchi menejer nuqtai nazaridan bayon etilgan vaziyat, auditoriyada mavjud imkoniyatlar va tavakkalni hisobga olgan vaziyat bo\'yicha qaror qabul qilish muhitini tashkil qilish, kelgusida aniq tadqiqotlar o\'tkazish uchun manba.', '[\"KEYS\", \"Loyihalash\", \"Ishbilarmonlik o\'yini\", \"T- chizmasi\"]', 0, 'To\'g\'ri javob: «KEYS». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(295, 4, 30, 'lesson', 5, 'Tashkiliy qism, yangi mavzuni bayon qilish, o\'rganilgan materialni mustahkamlash va uy vazifasini berish kabi punktlar qaysi dars turiga tegishli?', '[\"Yangi bilimlarni bayon qilish\", \"O\'quvchilarning bilim, ko\'nikma va malakalarini nazorat qilish\", \"Aralash dars\", \"Laboratoriya darslari\"]', 0, 'To\'g\'ri javob: «Yangi bilimlarni bayon qilish». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(296, 4, 30, 'lesson', 6, 'Kim maktabni «Jamiyatni harakatlantiruvchi kuch» deb hisoblagan.', '[\"F.Mitteran\", \"AQSHning sobiq Prezidenti R.Reygan\", \"Buyuk Britaniya Bosh vaziri M.Tetcher\", \"Fransiya Prezidenti F. Mitteran\"]', 0, 'To\'g\'ri javob: «F.Mitteran». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(297, 4, 30, 'lesson', 7, 'Qayerda to\'liqsiz o\'rta maktablarida asosiy predmetlar bilan bir qatorda tanlab olinadigan kimyo, fizika, chet tillari kiritilgan o\'quv dasturlari ham amalga oshirilmoqda? Bu o\'quv dasturi tobora to\'liqsiz o\'rta maktab doirasidan chiqib, o\'rta maktablar va gimnaziyalarni ham qamrab olmoqda.', '[\"Germaniya\", \"Yaponiya\", \"AQSh\", \"Fransiya\"]', 0, 'To\'g\'ri javob: «Germaniya». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(298, 4, 30, 'lesson', 8, 'Qaysi pedagoglar ta\'lim jarayonida sinf o\'quvchilarini uch tabaqaga ajratib o\'qitishni afzal ko\'radilar. 1.Gomogenlar — matematika va gumanitar yo\'nalishda ish olib borsa bo\'ladigan o\'quvchilar. 2.Yarim gomogen — tabiiy turkumdagi fanlarni o\'zlashtira olishga moyil o\'quvchilar. 3.Gegeron — barcha predmetlarni har xil saviyada o\'zlashtiradigan o\'quvchilar.', '[\"Fransiya\", \"Germaniya\", \"Yaponiya\", \"AQSh\"]', 0, 'To\'g\'ri javob: «Fransiya». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(299, 4, 30, 'lesson', 9, 'Qaysi maktablarda sinfda o\'quvchilar sonini qisqartirilib, bunday o\'quvchilarning har biriga individual paketlar (topshiriqlar) tarqatiladi. Topshiriqlarni o\'quvchi mustaqil bajaradi, lozim bo\'lganda u o\'qituvchidan konsultatsiya oladi.', '[\"Germaniya\", \"Fransiya\", \"Yaponiya\", \"AQSh\"]', 0, 'To\'g\'ri javob: «Germaniya». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(300, 4, 30, 'lesson', 10, 'Ta\'limining shakllanishi 1867 —1868-yillarda boshlangan. U o\'z oldiga ikki vazifani: birinchi — boyish, ikkinchi - G\'arb texnologiyasini u ishlab chiqarishiga kiritish masalasini qo\'yadi. 1872-yili «Ta\'lim haqidagi qonun» qabul qilindi. Bunda uning ta\'limi G\'arb ta\'limi bilan uyg\'unlashtirildi. 1908-yilda unda boshlang\'ich ta\'lim majburiy 6-yillikka aylantirildi. 1893-yili kasb yo\'nalishidagi dastlabki kollej paydo bo\'ldi. 1946-yili qabul qilingan Konstitutsiya fuqarolarning ta\'lim sohasidagi huquq va burchlarini belgilab berdi. Unda barcha bolalar bepul umumiy ta\'lim olishlari belgilab qo\'yilgan. Qaysi ta\'lim tizimi haqida fikr yuritilgan?', '[\"Yaponiya\", \"Fransiya\", \"Germaniya\", \"AQSh\"]', 0, 'To\'g\'ri javob: «Yaponiya». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 0, 5),
(301, 1, NULL, 'module', 1, 'O\'zbekiston respublikasining “ta\'lim to\'g\'risida”gi qonuniga muvofiq kimlar pedagogik faoliyat bilan shug\'ullanish huquqiga egalar?', '[\"Tegishli ma\'lumoti, kasbiy tayyorgarligi bor va yuksak axloqiy fazilatlarga ega bo\'lgan shaxslar\", \"Kasbiy bilim, ko\'nikma va malaka, shuningdek, ta\'lim muassasalarida ishlash tajribasiga ega shaxslar\", \"Oliy pedagogik ma\'lumot hamda 5 yillik pedagogik stajga ega shaxslar\", \"Faoliyat jarayonida ta\'lim oluvchilarning yosh va psixologik xususiyatlarini inobatga olgan holda ular bilan muloqot qilish malakasini o\'zlashtirgan shaxslar\"]', 0, 'To\'g\'ri javob: «Tegishli ma\'lumoti, kasbiy tayyorgarligi bor va yuksak axloqiy fazilatlarga ega bo\'lgan shaxslar». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(302, 1, NULL, 'module', 2, 'Ta\'lim muassasasi nima?', '[\"Qonun hujjatlariga muvofiq ishlab chiqilgan ustav asosida faoliyat ko\'rsatadigan yuridik shaxs\", \"Pulli ta\'lim xizmatlarini ko\'rsatish orqali moliyaviy imkoniyatlarini kengaytirish huquqiga ega yuridik shaxs\", \"Rivojlangan xorijiy mamlakatlarning ta\'lim muassasalari bilan hamkorlikni yo\'lga qo\'yish huquqiga ega yuridik shaxs\", \"Ta\'lim sohasidagi islohotlarni tashkil etishga mas\'ul yuridik shaxs\"]', 0, 'To\'g\'ri javob: «Qonun hujjatlariga muvofiq ishlab chiqilgan ustav asosida faoliyat ko\'rsatadigan yuridik shaxs». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(303, 1, NULL, 'module', 3, 'Mashg\'ulotlarga qo\'yiladigan maqsadlar?', '[\"Ta\'limiy, tarbiyaviy, rivojlantiruvchi\", \"Tarbiyaviy, didaktik, ijtimoiy-g\'oyaviy\", \"Tarbiyaviy, didaktik, muloqot\", \"Ijtimoiy-g\'oyaviy, aksiologik, didaktik\"]', 0, 'To\'g\'ri javob: «Ta\'limiy, tarbiyaviy, rivojlantiruvchi». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(304, 1, NULL, 'module', 4, '“Ta\'lim to\'g\'risidagi qonun” qachon qabul qilingan?', '[\"1997 yil, 29 avgust\", \"1997 yil, 29 iyul\", \"1992 yil, 12 avgust\", \"1993 yil, 11 avgust\"]', 0, 'To\'g\'ri javob: «1997 yil, 29 avgust». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(305, 1, NULL, 'module', 5, 'Kadrlar tayyorlash milliy modelining tarkibiy qismlari qaysi variantda berilgan?', '[\"Shaxs, uzluksiz ta\'lim, davlat va jamiyat, fan, ishlab chiqarish\", \"Ta\'lim xizmatlarini ko\'rsatuvchilar, ishlab chiqarish\", \"Ta\'lim xizmatlarining iste\'molchilari, ishlab chiqarish\", \"Ta\'lim jarayonining ishtirokchilari, ishlab chiqarish\"]', 0, 'To\'g\'ri javob: «Shaxs, uzluksiz ta\'lim, davlat va jamiyat, fan, ishlab chiqarish». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(306, 1, NULL, 'module', 6, 'Davlat ta\'lim standartlari nima?', '[\"Umumiy o\'rta, o\'rta maxsus, kasb-hunar va oliy ta\'lim mazmuniga hamda sifatiga qo\'yiladigan talablarni belgilaydigan me\'yoriy hujjat\", \"O\'quv yuklamlari hajmini aniqlashga xizmat qiladigan, shakl va metodlari to\'g\'risida mezonlar yig\'indisi\", \"Ta\'lim jarayonining samarali tashkil etish yo\'llari, shakl va metodlari to\'g\'risida ma\'lumotlardan iborat yo\'riqnoma\", \"O\'quv jadvalining tarkibiy elementlarini aks ettiruvchi manba, shakl va metodlari to\'g\'risida\"]', 0, 'To\'g\'ri javob: «Umumiy o\'rta, o\'rta maxsus, kasb-hunar va oliy ta\'lim mazmuniga hamda sifatiga qo\'yiladigan talablarni belgilaydigan me\'yoriy hujjat». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(307, 1, NULL, 'module', 7, 'DTS qanday ta\'lim turlari uchun joriy etiladi?', '[\"Umumiy o\'rta ta\'lim, oliy ta\'lim\", \"Umumiy o\'rta, maktabdan tashqari ta\'lim, oliy ta\'lim\", \"Maktabgacha, umumiy o\'rta, o\'rta maxsus, kasb-xunar\", \"Bolalar bog\'chasi, umumiy o\'rta ta\'lim, o\'rta maxsus\"]', 0, 'To\'g\'ri javob: «Umumiy o\'rta ta\'lim, oliy ta\'lim». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(308, 1, NULL, 'module', 8, '“Pedagogika” tushunchasi qanday ma\'noni anglatadi?', '[\"“Bola yetaklayman”\", \"“Shaxsni tarbiyalayman”\", \"“Shaxsni rivojlantiraman”\", \"“Bolani voyaga etkazaman”\"]', 0, 'To\'g\'ri javob: «“Bola yetaklayman”». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(309, 1, NULL, 'module', 9, '“Pedagogika bola tarbiyasining fani demakdir”. Ta\'rif kim tomonidan berilgan?', '[\"Abdulla avloniy\", \"H.H.Niyoziy\", \"Abduqodir shakuriy\", \"Ishoqxon ibrat\"]', 0, 'To\'g\'ri javob: «Abdulla avloniy». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(310, 1, NULL, 'module', 10, 'Pedagogika fani konsepsiyasida nimalar aks etadi?', '[\"Fanning rivojlanish istiqbollari\", \"Fanning umumiy mazmuni\", \"Fan erishgan yutuqlar\", \"Fanning yangi yo\'nalishlari\"]', 0, 'To\'g\'ri javob: «Fanning rivojlanish istiqbollari». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(311, 1, NULL, 'module', 11, 'Pedagogika fanining muhim tarkibiy qismlari qaysi javobda to\'g\'ri ko\'rsatilgan?', '[\"Didaktika (ta\'lim nazariyasi), tarbiya nazariyasi\", \"Ta\'lim menejmenti, didaktika (ta\'lim nazariyasi)\", \"Didaktika (ta\'lim nazariyasi), maktabshunoslik\", \"Tarbiya nazariyasi, ta\'lim menejmenti\"]', 0, 'To\'g\'ri javob: «Didaktika (ta\'lim nazariyasi), tarbiya nazariyasi». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(312, 1, NULL, 'module', 12, 'Pedagogika fanlari tizimi qanday fanlardan tarkib topgan?', '[\"“Maktabgacha ta\'lim pedagogikasi”, “boshlang\'ich ta\'lim pedagogikasi”, “pedagogika nazariyasi”, “pedagogika tarixi”, “pedagogik mahorat va pedagogik texnologiya”, “ijtimoiy pedagogika”, “kasbiy pedagogika”, “maxsus pedagogika”, “ta\'lim menejmenti”, “qiyosiy pedagogika” va b\", \"“Ijtimoiy pedagogika”, “kasbiy pedagogika”, “maxsus pedagogika”\", \"“Pedagogika nazariyasi”, “pedagogika tarixi”, “pedagogik mahorat”, “maxsus pedagogika”, “ta\'lim menejmenti”, “qiyosiy pedagogika”\", \"“Pedagogika nazariyasi”, “pedagogika tarixi”, “pedagogik texnologiya”\"]', 0, 'To\'g\'ri javob: «“Maktabgacha ta\'lim pedagogikasi”, “boshlang\'ich ta\'lim pedagogikasi”, “pedagogika nazariyasi”, “pedagogika tarixi”, “pedagogik mahorat va pedagogik texnologiya”, “ijtimoiy pedagogika”, “kasbiy pedagogika”, “maxsus pedagogika”, “ta\'lim menejmenti”, “qiyosiy pedagogika” va b». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(313, 1, NULL, 'module', 13, 'Pedagogikaning qaysi sohasi shaxsi va faoliyatida nuqsonlar ko\'zga tashlanadigan bolalarni o\'qitish va tarbiyalash bilan shug\'ullanadi?', '[\"Maxsus pedagogika\", \"Kasbiy pedagogika\", \"Ijtimoiy pedagogika\", \"Qiyosiy pedagogika\"]', 0, 'To\'g\'ri javob: «Maxsus pedagogika». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(314, 1, NULL, 'module', 14, 'Pedagogikaning asosiy kategoriyalari hisoblanadi?', '[\"Tarbiya, o\'qitish, bilim olish (ma\'lumot), rivojlanish\", \"Tarbiya, ta\'lim, ma\'lumot, shakllantirish\", \"Ta\'lim, ma\'lumot, shaxs, muloqot\", \"Ma\'lumot, shaxs, ta\'lim, rivojlantirish\"]', 0, 'To\'g\'ri javob: «Tarbiya, o\'qitish, bilim olish (ma\'lumot), rivojlanish». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6);
INSERT INTO `tests` (`id`, `module_id`, `lesson_id`, `quiz_type`, `order_in_quiz`, `question`, `options`, `correct_option`, `explanation`, `is_module_final`, `is_course_final`, `xp_reward`) VALUES
(315, 1, NULL, 'module', 15, 'Ta\'limning mazmuni qanday manbalarda aks ettiriladi?', '[\"Ta\'limning mazmuni: o\'quv rejalarida, dasturlarida va darsliklarda aks ettiriladi\", \"O\'quv rejasida va darsliklarda aks ettiriladi\", \"Ta\'limning mazmuni o\'quv materiallarda aks ettiriladi\", \"Ta\'limning mazmuni darsliklarda aks ettiriladi\"]', 0, 'To\'g\'ri javob: «Ta\'limning mazmuni: o\'quv rejalarida, dasturlarida va darsliklarda aks ettiriladi». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(316, 1, NULL, 'module', 16, 'Pedagogik tajriba tashkil etilish sharoitiga ko\'ra qanday guruhlarga ajratiladi?', '[\"Tabiiy tajriba, laboratoriya tajribasi, tajriba ishi\", \"Evristik tajriba, ijodiy tajriba, innovatsion tajriba\", \"Individual tajriba, guruh tajribasi, jamoaviy tajriba\", \"Laboratoriya tajribasi, amaliy tajriba, individual tajriba\"]', 0, 'To\'g\'ri javob: «Tabiiy tajriba, laboratoriya tajribasi, tajriba ishi». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(317, 1, NULL, 'module', 17, 'Insonning biologik mohiyatini o\'zida aks ettiruvchi tushunchani aniqlang:', '[\"Individ\", \"Sub\'ekt\", \"Shaxs\", \"Inson\"]', 0, 'To\'g\'ri javob: «Individ». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(318, 1, NULL, 'module', 18, 'Individ kim?', '[\"Xatti-harakatlarni shartli reflekslar asosida tashkil etuvchi biologik mavjudot\", \"Xatti-harakatlarni ongli boshqarish imkoniyatiga ega bo\'lmagan biologik mavjudot\", \"Xatti-harakatlarni shartsiz reflekslar asosida tashkil etuvchi biologik mavjudot\", \"Xatti-harakatlarni ongli ravishda tashkil etuvchi biologik mavjudot\"]', 0, 'To\'g\'ri javob: «Xatti-harakatlarni shartli reflekslar asosida tashkil etuvchi biologik mavjudot». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(319, 1, NULL, 'module', 19, 'Shaxs kim?', '[\"Psixologik jihatdan taraqqiy etgan, shaxsiy xususiyatlari va xatti-harakatlari bilan boshqalardan ajralib turuvchi, muayyan xulq-atvor va dunyoqarashga ega bo\'lgan ijtimoiy mavjudot\", \"Xatti-harakatlari bilan boshqalardan ajralib turuvchi, muayyan xulq-atvor va dunyoqarashga ega bo\'lgan ijtimoiy mavjudot\", \"Shaxsiy xususiyatlari va xatti-harakatlari bilan boshqalardan ajralib turuvchi ijtimoiy mavjudot\", \"Psixologik jihatdan taraqqiy etgan hamda ma\'lum darajada ma\'naviy-axloqiy sifatlarga ega ijtimoiy mavjudot\"]', 0, 'To\'g\'ri javob: «Psixologik jihatdan taraqqiy etgan, shaxsiy xususiyatlari va xatti-harakatlari bilan boshqalardan ajralib turuvchi, muayyan xulq-atvor va dunyoqarashga ega bo\'lgan ijtimoiy mavjudot». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(320, 1, NULL, 'module', 20, 'Shaxsga xos bo\'lgan barcha tug\'ma xususiyatlarning boyib borishi, yangi sifatlarning hosil qilinishi, shuningdek, organizmning anatomik tuzilishi, fiziologik va psixologik funksiyalarning takomillashishi, faoliyat hamda xatti-harakatning miqdor va sifat jihatdan o\'zgarib borish jarayoni deganda nima tushuniladi?', '[\"Shaxsning rivojlanishi\", \"Shaxsning o\'sishi\", \"Shaxsning shakllanishi\", \"Shaxsning takomillashuvi\"]', 0, 'To\'g\'ri javob: «Shaxsning rivojlanishi». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(321, 1, NULL, 'module', 21, 'Shaxs rivojlanishiga qanday omillar ta\'sir ko\'rsatadi?', '[\"Irsiyat, muhit, tarbiya\", \"Tabiiy muhit, ijtimoiy munosabatlar\", \"Muhit, tarbiya, bilim\", \"Irsiyat, tabiiy muhit, ijtimoiy munosabatlar\"]', 0, 'To\'g\'ri javob: «Irsiyat, muhit, tarbiya». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(322, 1, NULL, 'module', 22, '“Inson kamolatida uch narsa – irsiyat, muhit, tarbiya muhim rol o\'ynaydi” degan fikrni ilk bor ilgari surgan sharq mutafakkiri kim?', '[\"Abu rayhon beruniy\", \"Abu nasr forobiy\", \"Abu ali ibn sino\", \"Yusuf xos hojib\"]', 0, 'To\'g\'ri javob: «Abu rayhon beruniy». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(323, 1, NULL, 'module', 23, 'Shaxsning rivojlanishi qanday holatlar bilan belgilanadi?', '[\"Shaxsning fiziologik, ruhiy, intellektual o\'sishini ta\'minlovchi faoliyat hamda xatti-harakatlarning miqdor va sifat jihatdan o\'zgarishlar bilan\", \"Shaxsning fiziologik, ruhiy kamolotga erishishida kechadigan miqdor o\'zgarish bilan\", \"Shaxsning fiziologik, ruhiy kamol topishida kechadigan sifat o\'zgarishlar bilan\", \"Shaxs kamolotida muhim o\'rin tutuvchi faoliyat ko\'nikmalarining miqdor va sifat jihatdan takomillashib borishi bilan\"]', 0, 'To\'g\'ri javob: «Shaxsning fiziologik, ruhiy, intellektual o\'sishini ta\'minlovchi faoliyat hamda xatti-harakatlarning miqdor va sifat jihatdan o\'zgarishlar bilan». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(324, 1, NULL, 'module', 24, 'Shaxsga xos individual xususiyatlarni ko\'rsating', '[\"Shaxsning yo\'nalganligi, qiziqishlari, xarakteri, uni boshqalardan ajratib turadigan aqliy kamoloti, faoliyatining o\'ziga xosligini belgilovchi barqaror, muhim xususiyatlar\", \"Shaxsning yo\'nalganligi, qiziqishlari, xarakteri, uni boshqalardan ajratib turadigan aqliy kamolotini yorituvchi barqaror, muhim xususiyatlar\", \"Shaxsning yo\'nalganligi, qiziqishlari, xarakterini tavsiflovchi barqaror, muhim xususiyatlar\", \"Shaxsning qiziqishlari, xarakteri, aqliy kamoloti, faoliyatining o\'ziga xosligini ifodalovchi barqaror, muhim xususiyatlar\"]', 0, 'To\'g\'ri javob: «Shaxsning yo\'nalganligi, qiziqishlari, xarakteri, uni boshqalardan ajratib turadigan aqliy kamoloti, faoliyatining o\'ziga xosligini belgilovchi barqaror, muhim xususiyatlar». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(325, 1, NULL, 'module', 25, '“Qobiliyatni tarbiya qilmaslik zulmdir va qobiliyatsizga tarbiya hayf”. Mazkur fikrning muallifi kim?', '[\"Alisher navoiy\", \"Unsurul Maoliy Kaykovus\", \"Ahmad Yugnakiy\", \"Saidahmad Siddiqiy\"]', 0, 'To\'g\'ri javob: «Alisher navoiy». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(326, 2, NULL, 'module', 1, 'Faoliyat nima?', '[\"Ijtimoiy hayotni maqsadga muvofiq tashkil etish yo\'lida shaxs tomonidan amalga oshirilayotgan kundalik va kasbiy xatti-harakatlarning muayyan shakli\", \"Shaxs tomonidan ijtimoiy hayotning mazmunli kechishini ta\'minlash yo\'lida olib borilayotgan xatti-harakatlarning muayyan shakli\", \"Ijtimoiy hayotni maqsadga muvofiq, izchil, tizimli, uzluksiz tashkil etilishini ta\'minlashga haratilgan xatti-harakatlarning muayyan shakli\", \"Shaxsning ijtimoiy muhitga moslashishi yo\'lidagi xatti-harakatlarining muayyan shakli\"]', 0, 'To\'g\'ri javob: «Ijtimoiy hayotni maqsadga muvofiq tashkil etish yo\'lida shaxs tomonidan amalga oshirilayotgan kundalik va kasbiy xatti-harakatlarning muayyan shakli». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(327, 2, NULL, 'module', 2, 'Shaxsni shakllantirishga yo\'naltirilgan faoliyat samaradorligiga qanday erishiladi?', '[\"Faoliyatni pedagogik jihatdan to\'g\'ri uyushtirish asosida\", \"Faoliyatni ilmiy jihtdan to\'g\'ri tashkil etish orqali\", \"Faoliyatni izchil va doimiy nazorat qilish asosida\", \"Faoliyatda shaxsga maxsus ko\'rsatmalar berish orqali\"]', 0, 'To\'g\'ri javob: «Faoliyatni pedagogik jihatdan to\'g\'ri uyushtirish asosida». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(328, 2, NULL, 'module', 3, 'O\'quvchilar tomonidan tashkil etiladigan faoliyatning asosiy turlarini ko\'rsating:', '[\"O\'yin, o\'qish, mehnat\", \"Mehnat, sport, muloqot\", \"O\'qish, mehnat, sport\", \"O\'yin, o\'qish, o\'z-o\'ziga xizmat\"]', 0, 'To\'g\'ri javob: «O\'yin, o\'qish, mehnat». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(329, 2, NULL, 'module', 4, 'Ko\'nikma nima?', '[\"Shaxsning muayyan faoliyatni tashkil eta olish qobiliyati\", \"Ongli xatti-harakatning avtomatlashtirilgan shakli, faoliyatning tarkibiy qismi\", \"Faoliyat negizida amalga oshiriladigan xatti-harakatlar\", \"Bilimning yetarlilik darajasi\"]', 0, 'To\'g\'ri javob: «Shaxsning muayyan faoliyatni tashkil eta olish qobiliyati». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(330, 2, NULL, 'module', 5, 'Malaka bu:', '[\"Ongli xatti-harakat, faoliyatni bajarishning avtomatlashgan shakli\", \"Mehnat qilish jarayonida hosil bo\'lgan ko\'nikmalar natijasi\", \"Bililarning amalda bir necha bor qo\'llanilishi\", \"Inson tomonidan uzoq yillar davomida o\'zlashtirilgan bilimlar majmui\"]', 0, 'To\'g\'ri javob: «Ongli xatti-harakat, faoliyatni bajarishning avtomatlashgan shakli». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(331, 2, NULL, 'module', 6, 'Ko\'nikma va malakalarni shakllantirishda asosiy bo\'lgan metod – bu...', '[\"Amaliy mashq\", \"Namoyish\", \"Suhbat\", \"Pedagogik kuzatish\"]', 0, 'To\'g\'ri javob: «Amaliy mashq». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(332, 2, NULL, 'module', 7, 'Pedagogikada qabul qilingan yosh davrlarini ko\'rsating:', '[\"Go\'daklik davri, maktabgacha ta\'lim muassasasigacha bo\'lgan davr, maktabgacha ta\'lim davri, boshlang\'ich ta\'lim davri, o\'smirlik, o\'spirinlik\", \"Go\'daklik davri, bolalik davri, maktabgacha ta\'lim davri, kichik maktab yoshi davri, o\'rta maktab yoshi davri, katta maktab yoshi davri\", \"Go\'daklik davri, maktabgacha ta\'lim davri, kichik maktab yoshi davri, o\'rta maktab yoshi davri, katta maktab yoshi davri\", \"Go\'daklik davri, bolalik davri, maktabgacha ta\'lim davri, boshlang\'ich ta\'lim davri, o\'smirlik, o\'spirinlik\"]', 0, 'To\'g\'ri javob: «Go\'daklik davri, maktabgacha ta\'lim muassasasigacha bo\'lgan davr, maktabgacha ta\'lim davri, boshlang\'ich ta\'lim davri, o\'smirlik, o\'spirinlik». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(333, 2, NULL, 'module', 8, 'Ilk bolalik qaysi yosh davrlarini o\'z ichiga oladi?', '[\"1 yoshdan 3 yoshgacha bo\'lgan davr\", \"1 yoshdan 2 yoshgacha bo\'lgan davr\", \"2 yoshdan 3 yoshgacha bo\'lgan davr\", \"3 yoshdan 4 yoshgacha bo\'lgan davr\"]', 0, 'To\'g\'ri javob: «1 yoshdan 3 yoshgacha bo\'lgan davr». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(334, 2, NULL, 'module', 9, 'O\'smirlik davri uchun xarakterli bo\'lgan xususiyat nimadan iborat?', '[\"Jinsiy etilish va intensiv (tezkor) rivojlanishning kuzatilishi, mustaqillik hamda o\'zini namoyish qilishga intilish\", \"Jismoniy faollikning ortishi, shaxsi sifatida o\'zini namoyish qilishga intilish\", \"Ijtimoiy faollik ko\'nikmalarining shakllanishi, mustaqillikka intilish\", \"O\'z xatti-harakatlarini mustaqil ravishda baholay olish layoqatining rivojlanishi va jismoniy faollikning ortishi\"]', 0, 'To\'g\'ri javob: «Jinsiy etilish va intensiv (tezkor) rivojlanishning kuzatilishi, mustaqillik hamda o\'zini namoyish qilishga intilish». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(335, 2, NULL, 'module', 10, 'Tarbiya nazariyasi nimani o\'rganadi?', '[\"Tarbiyaviy jarayon mazmuni, tamoyillari, qonuniyatlari, uni tashkil etish masalalari, metodikasi, shakl, metod, vosita va usullarini\", \"Tarbiyaviy jarayon mazmuni, shaxsning tarbiyaviy jarayondagi o\'rnini\", \"Tarbiya jarayoni qonuniyatlari, uni tashkil etish shakl, metod, vosita va usullarini\", \"Tarbiyaviy jarayonning o\'ziga xos xususiyatlarini\"]', 0, 'To\'g\'ri javob: «Tarbiyaviy jarayon mazmuni, tamoyillari, qonuniyatlari, uni tashkil etish masalalari, metodikasi, shakl, metod, vosita va usullarini». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(336, 2, NULL, 'module', 11, 'Tarbiya qanday jarayon?', '[\"Yosh avlodni muayyan, aniq maqsad, ijtimoiy-tarixiy tajriba asosida har tomonlama o\'stirish, uning ongi, xulq-atvori va dunyoqarashini tarkib toptirish jarayoni\", \"Yosh avlodni har tomonlama kamol toptirish, unda yuaksak ma\'naviy-axloqiy sifatlarni shakllantirish jarayoni va dunyoqarashini tarkib toptirish jarayoni\", \"Yosh avlodda ijtimoiy ong, xulq-atvor va dunyoqarashni tarkib toptirish yuksak ma\'naviy-axloqiy sifatlarni shakllantirish jarayoni\", \"Yosh avlodni ijtimoiy-tarixiy tajriba asosida har tomonlama o\'stirish jarayoni va dunyoqarashini tarkib toptirish jarayoni\"]', 0, 'To\'g\'ri javob: «Yosh avlodni muayyan, aniq maqsad, ijtimoiy-tarixiy tajriba asosida har tomonlama o\'stirish, uning ongi, xulq-atvori va dunyoqarashini tarkib toptirish jarayoni». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(337, 2, NULL, 'module', 12, 'Tarbiyaning ijtimoiy muhitning ob\'ektiv va sub\'ektiv omillariga bog\'liqligi, tarbiyaning shaxsning rivojlanishi bilan birligi va o\'zaro aloqadorligi faoliyat va munosabatni e\'tirof etish shaxsning ijtimoiy ahamiyatli fazilatlarni shakllantirishning negizi va asosiy manbai ekanligi tarbiyalanuvchilarning o\'zaro tarbiyaviy ta\'siri, o\'zaro munosabatlari hamda faol faoliyati o\'rtasidagi bog\'lanishning mavjudligi. Ular nimani ifodalaydi?', '[\"Tarbiya qonuniyatlarini\", \"Tarbiya maqsadlarini\", \"Tarbiya g\'oyalarini\", \"Tarbiya tamoyillarini\"]', 0, 'To\'g\'ri javob: «Tarbiya qonuniyatlarini». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(338, 2, NULL, 'module', 13, 'Tarbiya jarayonining o\'ziga xos xususiyatlari nimalardan iborat?', '[\"Aniq maqsadga yo\'naltirilganlik, ko\'p qirralilik, uzoq muddat davom etishi, yaxlitlik, tizimlilik, ikki tomonlama aloqaga egalik, qarama-qarshiliklarning mavjudligi\", \"Ko\'p qirralilik, bir tomonlama aloqaga egalik ikki tomonlama aloqaga egalik, qarama-qarshiliklarning mavjudligi\", \"Aniq maqsadga yo\'naltirilganlik, muayyan vaqt oralig\'ida davom etishi ikki tomonlama aloqaga egalik, qarama-qarshiliklarning mavjudligi\", \"Uzoq muddat davom etishi, yaxlitlik, tizimlilik ikki tomonlama aloqaga egalik, qarama-qarshiliklarning mavjudligi\"]', 0, 'To\'g\'ri javob: «Aniq maqsadga yo\'naltirilganlik, ko\'p qirralilik, uzoq muddat davom etishi, yaxlitlik, tizimlilik, ikki tomonlama aloqaga egalik, qarama-qarshiliklarning mavjudligi». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(339, 2, NULL, 'module', 14, 'Tarbiya turlari qaysi variantda to\'g\'ri ko\'rsatilgan?', '[\"Aqliy tarbiya, axloqiy tarbiya, jismoniy tarbiya, mehnat tarbiyasi, ekologik tarbiya, estetik tarbiya, iqtisodiy tarbiya, huquqiy tarbiya, fuqarolik tarbiyasi, jinsiy tarbiya, oila tarbiyasi va b\", \"Aqliy tarbiya, g\'oyaviy-ijtimoiy tarbiya, axloqiy tarbiya, jismoniy tarbiya, mehnat tarbiyasi, mehnat tarbiyasi, ekologik tarbiya\", \"Axloqiy tarbiya, jismoniy tarbiya, mehnat tarbiyasi, ekologik tarbiya, estetik tarbiya, jamoatchilik tarbiyasi, mehnat tarbiyasi, ekologik tarbiya va b\", \"Aqliy tarbiya, axloqiy tarbiya, jismoniy tarbiya, ekologik tarbiya, estetik tarbiya, iqtisodiy tarbiya, huquqiy tarbiya, vatanparvarlik tarbiyasi, mehnat tarbiyasi, ekologik tarbiya va b\"]', 0, 'To\'g\'ri javob: «Aqliy tarbiya, axloqiy tarbiya, jismoniy tarbiya, mehnat tarbiyasi, ekologik tarbiya, estetik tarbiya, iqtisodiy tarbiya, huquqiy tarbiya, fuqarolik tarbiyasi, jinsiy tarbiya, oila tarbiyasi va b». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(340, 2, NULL, 'module', 15, 'Tarbiya metodlari?', '[\"Shaxsga tarbiyaviy ta\'sir etish, uning hayoti va faoliyatini uyushtirish asosida unda ma\'naviy-axloqiy tushuncha, e\'tiqod va fazilatlarni tarkib toptirish usullari\", \"Shaxsga tarbiyaviy ta\'sir etish orqali uni har tomonlama kamol toptirish yo\'llari va fazilatlarni tarkib toptirish usullari\", \"Shaxsning hayoti va faoliyatini uyushtirish asosida unda ma\'naviy-axloqiy sifatlarni tarbiyalash usullari\", \"Shaxsning ijtimoiy ongini shakllantirish orqali uni fuqaro sifatida tarbiyalash yo\'llari\"]', 0, 'To\'g\'ri javob: «Shaxsga tarbiyaviy ta\'sir etish, uning hayoti va faoliyatini uyushtirish asosida unda ma\'naviy-axloqiy tushuncha, e\'tiqod va fazilatlarni tarkib toptirish usullari». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(341, 2, NULL, 'module', 16, 'Tarbiya metodlarining quyidagi turlari kim tomonidan ilgari surilgan:', '[\"G.I.Shukina\", \"A.Q.Munavvarov\", \"K.Z.Zaripov\", \"B.Farberman\"]', 0, 'To\'g\'ri javob: «G.I.Shukina». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(342, 2, NULL, 'module', 17, 'Tarbiya metodlari qaysi javob variantida keltirilgan?', '[\"Ijtimoiy ongni shakllantiruvchi metodlar, faoliyatni tashkil etish va ijtimoiy xulq-atvor ko\'nikmalarini shakllantiruvchi metodlar, pedagogik rag\'batlantirish (xulq-atvorni tuzatish) metodlari\", \"Ijtimoiy xulq-atvor ko\'nikmalarini shakllantiruvchi metodlar, ko\'rsatmali metodlar, amaliy mashg\'ulotlar metodlari\", \"Ongni shakllantiruvchi metodlar, og\'zaki bayon qilish metodlari, pedagogik rag\'batlantirish (xulq-atvorni tuzatish) metodlari\", \"Ongni shakllantiruvchi metodlar, ijtimoiy xulq-atvor ko\'nikmalarini shakllantiruvchi metodlar, og\'zaki ta\'sir ko\'rsatuvchi metodlar\"]', 0, 'To\'g\'ri javob: «Ijtimoiy ongni shakllantiruvchi metodlar, faoliyatni tashkil etish va ijtimoiy xulq-atvor ko\'nikmalarini shakllantiruvchi metodlar, pedagogik rag\'batlantirish (xulq-atvorni tuzatish) metodlari». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(343, 2, NULL, 'module', 18, 'Quyidagilarning qaysilari jazolash metodlari sanaladi?', '[\"Tanbeh berish, uyaltirish, ogohlantirish\", \"Ogohlantirish, uyaltirish, musobaqa\", \"Tenbeh berish, pedagogik talab, xayfsan berish\", \"Uyaltirish, o\'git, ogohlantirish\"]', 0, 'To\'g\'ri javob: «Tanbeh berish, uyaltirish, ogohlantirish». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(344, 2, NULL, 'module', 19, 'Pedagogik talab nima?', '[\"Turli xatti-harakatlarni bajarish va faoliyatni tashkil etish jarayonida o\'quvchi tomonidan amal qilinishi zarur bo\'lgan ijtimoiy xulq-atvor me\'yorlari\", \"Shaxsni to\'g\'ri shakllanishini ta\'min etuvchi pedagogik ko\'rsatmalar, yo\'l-yo\'riqlar\", \"Shaxsda xalq-atvor ko\'nikmalarini shakllantiruvchi me\'yoriy talablar zarur bo\'lgan ijtimoiy xulq-atvor me\'yorlari\", \"O\'quvchi va jamoa birligini qaror toptirishga xizmat qiluvchi qoidalar zarur bo\'lgan ijtimoiy xulq-atvor me\'yorlari\"]', 0, 'To\'g\'ri javob: «Turli xatti-harakatlarni bajarish va faoliyatni tashkil etish jarayonida o\'quvchi tomonidan amal qilinishi zarur bo\'lgan ijtimoiy xulq-atvor me\'yorlari». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(345, 2, NULL, 'module', 20, 'Pedagogik talab, o\'rganish, mashq qilish, tarbiyalovchi vaziyatlar, musobaqa tarbiya metodlarining qaysi guruhini tashkil etadi?', '[\"Faoliyatini tashkil etish va ijtimoiy xulq-atvor ko\'nikmalarini shakllantirish metodlari guruhini\", \"Og\'zaki ko\'nikmalarini shakllantirish metodlari guruhini metodlar guruhini\", \"Ongni shakllantirish ko\'nikmalarini shakllantirish metodlari guruhini metodlari guruhi\", \"Amaliy ko\'nikmalarini shakllantirish metodlari guruhini metodlar guruhi\"]', 0, 'To\'g\'ri javob: «Faoliyatini tashkil etish va ijtimoiy xulq-atvor ko\'nikmalarini shakllantirish metodlari guruhini». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(346, 2, NULL, 'module', 21, 'O\'z-o\'zini tarbiyalash nima?', '[\"Shaxsning iroda kuchini ishlatish asosida o\'zida muayyan fazilatlarni tarkib toptirishga qaratilgan ongli faoliyati jarayoni\", \"Shaxsning irodaviy sifatlariga tayangan holda o\'z-o\'zini baholash jarayoni\", \"Shaxs tomonidan o\'z xatti-harakatlari, faoliyatini tahlil, nazorat qilish jarayoni\", \"Shaxsning o\'z-o\'zini ob\'ektiv baholash orqali ma\'lum fazilatlarga ega bo\'lishga intilishi jarayoni\"]', 0, 'To\'g\'ri javob: «Shaxsning iroda kuchini ishlatish asosida o\'zida muayyan fazilatlarni tarkib toptirishga qaratilgan ongli faoliyati jarayoni». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(347, 2, NULL, 'module', 22, 'Ijtimoiy ongni shakllantiruvi metodlar guruhiga kiradigan metodlarni aniqlang', '[\"Tushuntirish va uqtirish, namuna ko\'rsatish, suhbat, munozara\", \"Pedagogik talab, o\'rganish, mashq qilish, tarbiyalovchi vaziyatlar, musobaqa\", \"Rag\'batlantirish va jazolash\", \"Suhbat, namuna ko\'rsatish, tarbiyalovchi vaziyatlar, musobaqa\"]', 0, 'To\'g\'ri javob: «Tushuntirish va uqtirish, namuna ko\'rsatish, suhbat, munozara». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(348, 2, NULL, 'module', 23, 'Pedagogik rag\'batlantirish (xulq-atvorni tuzatish) metodi qanday elementlardan tarkib topadi?', '[\"Rag\'batlantirish va jazolash\", \"Namuna ko\'rsatish va rag\'batlantirish\", \"Tushuntirish va uqtirish\", \"Jazolash va tushuntirish\"]', 0, 'To\'g\'ri javob: «Rag\'batlantirish va jazolash». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(349, 2, NULL, 'module', 24, 'Qaysi qatorda rag\'batlantirish (xulq-atvorni tuzatish) metodlari guruhiga kiruvchi metodlar to\'g\'ri berilgan?', '[\"Mukofotlash, tanbeh, xatti-harakatlarni jamoa o\'rtasida muhokama qilish\", \"Mashq, musobaqadan chetlatish, nasihat jamoa o\'rtasida muhokama qilish\", \"Hikoya, tushuntirish, tanbeh jamoa o\'rtasida muhokama qilish\", \"Musobaqadan chetlatish, tushuntirish, hayfsan berish\"]', 0, 'To\'g\'ri javob: «Mukofotlash, tanbeh, xatti-harakatlarni jamoa o\'rtasida muhokama qilish». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(350, 2, NULL, 'module', 25, 'Jamoa nima?', '[\"Bir necha a\'zolardan iborat bo\'lib, ijtimoiy ahamiyatga ega umumiy maqsad asosida tashkil etilgan guruh\", \"O\'zaro bir-birlarini tushuna oladigan kishilar guruhi\", \"Bir necha shaxslarning yagona manfaat atrofida birlashishlari\", \"Shaxsiy manfaatlardan ko\'pchilik manfaatini ustun qo\'yish imkoniyatiga ega kishilardan tarkib topgan guruh\"]', 0, 'To\'g\'ri javob: «Bir necha a\'zolardan iborat bo\'lib, ijtimoiy ahamiyatga ega umumiy maqsad asosida tashkil etilgan guruh». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(351, 3, NULL, 'module', 1, 'Bolalar jamoaning rivojlanishi uchun xarakterli bo\'lgan quyidagi holatlar nimani ifodalaydi: ijtimoiy ahamiyatga ega yagona maqsadning mavjudligini, birgalikdagi umumiy faoliyatning tashkil etilishini, majburiy, mas\'uliyatli munosabatning yo\'lga qo\'yilishini, saylangan umumiy rahbariy organga egalikni?', '[\"Jamoaning o\'ziga xos xususiyatlarini\", \"Jamoaning shakllanish bosqichlarini\", \"Jamoaning tuzilishini\", \"Jamoa tomonidan olib boriladigan faoliyat mazmunini\"]', 0, 'To\'g\'ri javob: «Jamoaning o\'ziga xos xususiyatlarini». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(352, 3, NULL, 'module', 2, 'Jamoa rivojlanishining qaysi bosqichida faqat pedagogik talablar qo\'yiladi?', '[\"I bosqichida\", \"Vi bosqichida\", \"Iii bosqichida\", \"Ii bosqichida\"]', 0, 'To\'g\'ri javob: «I bosqichida». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(353, 3, NULL, 'module', 3, 'A.S.Makarenkoning fikricha, “ayrim o\'zini chetga olib qochuvchi, injiq shaxslarga jamoa talab qo\'ya boshlashi” jamoa rivojlanishining qaysi bosqichida ro\'y beradi?', '[\"Iii bosqichida\", \"Vi bosqichida\", \"Ii bosqichida\", \"I bosqichida\"]', 0, 'To\'g\'ri javob: «Iii bosqichida». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(354, 3, NULL, 'module', 4, 'Jamoa rivojlanishining ikkinchi bosqichiga qanday xususiyat xos?', '[\"Jamoa faollari jamoa a\'zolari oldiga ma\'lum talablarni qo\'yadi\", \"O\'qituvchi tomonidan pedagogik talablar qo\'yiladi\", \"O\'z-o\'zini boshqarishga o\'tiladi\", \"Jamoaning har bir a\'zosi o\'z oldiga jamoa manfaatiga oid talablarni qo\'yadi\"]', 0, 'To\'g\'ri javob: «Jamoa faollari jamoa a\'zolari oldiga ma\'lum talablarni qo\'yadi». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(355, 3, NULL, 'module', 5, 'Jamoa an\'analari nima?', '[\"Jamoa a\'zolari tomonidan birdek qo\'llab-quvvatlanuvchi barqarorlashgan odatlar\", \"Jamoa a\'zolari qat\'iy amal qiladigan me\'yorlar\", \"Jamoa a\'zolari tomonidan birdek bajarilishi zarur bo\'lgan talablar\", \"Jamoa a\'zolari birdek bo\'ysunadigan majburiy qoidalar\"]', 0, 'To\'g\'ri javob: «Jamoa a\'zolari tomonidan birdek qo\'llab-quvvatlanuvchi barqarorlashgan odatlar». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(356, 3, NULL, 'module', 6, 'Dunyoqarash nima?', '[\"Tabiat, jamiyat, tafakkur hamda shaxs faoliyati mazmunining rivojlanib borishini belgilab beruvchi dialektik xarakterga ega qarashlar va e\'tiqodlar tizimi\", \"Shaxsning shakllanish jarayoni xususiyatlarini ifodalovchi g\'oyalar tizimi\", \"Shaxsning ijtimoiy jamiyatdagi o\'rnini belgilovchi xulq-atvor xususiyatlari\", \"Shaxs faoliyati mazmunini belgilab beradigan ma\'naviy-axloqiy qarashlar tizimi\"]', 0, 'To\'g\'ri javob: «Tabiat, jamiyat, tafakkur hamda shaxs faoliyati mazmunining rivojlanib borishini belgilab beruvchi dialektik xarakterga ega qarashlar va e\'tiqodlar tizimi». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(357, 3, NULL, 'module', 7, '“Metod” – bu...', '[\"Metod – bu yunoncha “yo\'l, yo\'riq”, usul orqali maqsadga erishishdir\", \"Metod – bu lotincha so\'zdan olingan bo\'lib, axborotni uzatish\", \"Metod – bu lotincha so\'zdan olingan bo\'lib, axborotni uzatish\", \"Metod – pedagogik texnologiyaning tarkibiy qismi\"]', 0, 'To\'g\'ri javob: «Metod – bu yunoncha “yo\'l, yo\'riq”, usul orqali maqsadga erishishdir». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(358, 3, NULL, 'module', 8, 'Axloqiy tarbiyaning maqsadi nimadan iborat?', '[\"Axloqiy ong, axloqiy his-tuyg\'u, axloqiy xulq-atvor ko\'nikmalari va axloqiy e\'tiqodga ega shaxsni tarbiyalash\", \"O\'quvchilar ongiga axloqiy me\'yorlarni, ijtimoiy-huquqiy qoidalarni, qonunchilik asoslarini, ijtimoiy-axloqiy talablarni singdirish\", \"O\'quvchilarda axloqiy fazilatlar, xulq-atvor ko\'nikmalarini, ijobiy xislatlarni, xushmuomalalilik, fahm-farosatni va nazokat shakllantirish\", \"O\'quvchilarda borliqqa ijobiy munosabatni, mustahkam e\'tiqodni va aniq maqsad asosida hayotiy intilishlarni\"]', 0, 'To\'g\'ri javob: «Axloqiy ong, axloqiy his-tuyg\'u, axloqiy xulq-atvor ko\'nikmalari va axloqiy e\'tiqodga ega shaxsni tarbiyalash». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(359, 3, NULL, 'module', 9, 'Muloqot nima?', '[\"Fikr almashish, bir-birini tushunish\", \"Maslaxatlashish, fikrlashish\", \"Birovlarga ta\'sir kursatish\", \"Suxbatlashish faoliyati\"]', 0, 'To\'g\'ri javob: «Fikr almashish, bir-birini tushunish». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(360, 3, NULL, 'module', 10, 'Jamiyat tomonidan tan olingan bo\'lib, unda yashovchi kishilar tomonidan bajarilishi majburiy-ixtiyoriy bo\'lgan qoida nima deb ataladi?', '[\"Axloqiy me\'yor\", \"Axloqiy harakat\", \"Axloqiy yondashuv\", \"Axloqiy qarash\"]', 0, 'To\'g\'ri javob: «Axloqiy me\'yor». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(361, 3, NULL, 'module', 11, 'Shaxsga yo\'naltirilgan ta\'limning asosiy tamoyilini ko\'rsating?', '[\"Ta\'lim markaziga o\'quvchi (o\'quvchi) qo\'yiladi\", \"Ta\'lim markaziga o\'qituvchi qo\'yiladi\", \"Ta\'lim markaziga pedagogik jamoa qo\'yiladi\", \"O\'quv yurtining moddiy texnik ta\'minoti xisobga olinad\"]', 0, 'To\'g\'ri javob: «Ta\'lim markaziga o\'quvchi (o\'quvchi) qo\'yiladi». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(362, 3, NULL, 'module', 12, 'Pedagogika olamiga savol javob va «evristik» suhbat metodini olib kirgan faylasuf olim kim?', '[\"Suqrot\", \"Platon\", \"Arastu\", \"Demokrit\"]', 0, 'To\'g\'ri javob: «Suqrot». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
