(364, 3, NULL, 'module', 14, '«Takrorlash bilimning onasidir». Ushbu ibora qaysi pedagog olimning fikriga mansub.', '[\"Ushinskiy\", \"Shakuriy\", \"Komenskiy\", \"Hamza\"]', 0, 'To\'g\'ri javob: «Ushinskiy». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(365, 3, NULL, 'module', 15, 'Ibtidoiy jamoa davridagi ma\'rifiy tafakkurning dastlabki kurtaklari', '[\"Yunon tarixchisi geradotning «tarix» kitoblarida bayon etilgan\", \"Folklorlardagi o\'z aksini topgan\", \"«Behistun» yozuvlarida ifodalangan\", \"Xalk ogzaki ijodi namunalarida\"]', 0, 'To\'g\'ri javob: «Yunon tarixchisi geradotning «tarix» kitoblarida bayon etilgan». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(366, 3, NULL, 'module', 16, 'Qaysi mehnat turli o\'quvchilarning moddiy boyliklar yaratishdagi ishtiroki, bu jarayonda ularning ishlab chiqarish munosabatlariga kirishishlarini ko\'zda tutadi?', '[\"Ishlab chiqarish mehnati\", \"O\'quv mehnati\", \"Ijtimoiy foydali mehnat\", \"O\'z-o\'ziga xizmat ko\'rsatish\"]', 0, 'To\'g\'ri javob: «Ishlab chiqarish mehnati». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(367, 3, NULL, 'module', 17, 'Zardushtiylik axloqining asosi bu...', '[\"Ezgu fikr, ezgu kalom, ezgu amal\", \"Ezgu niyat, ezgu ixlos, ezgu amal\", \"Ezgu kalom, ezgu hayol, ezgu tilak\", \"Falsafa, siyosat e\'tiqod\"]', 0, 'To\'g\'ri javob: «Ezgu fikr, ezgu kalom, ezgu amal». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(368, 3, NULL, 'module', 18, 'Ijtimoiy ongni shakllantiruvchi metodlar qanday usullar sanaladi?', '[\"Ijtimoiy ongni shakllantiruvchi metodlar o\'quvchilarda ma\'naviy -axloqiy sifatlar, e\'tiqod hamda dunyoqarashini shakllantirish maqsadida ularning ongi, xis-tuyg\'usi va irodasiga ta\'sir ko\'rsatish usullari sanaladi\", \"Ijtimoiy ongni shakllantiruvchi metodlar e\'tiqod hamda dunyoqarashni shakllantirish usullari sanaladi\", \"Ijtimoiy ongni shakllantiruvchi metodlar xis-tuyg\'usi va irodasi ta\'sir ko\'rsatish usullari sanaladi\", \"Ijtimoiy ongni shakllantiruvchi metodlar ma\'naviy axloqiy sifatlar va irodasiga ta\'sir ko\'rsatish usullari sanaladi\"]', 0, 'To\'g\'ri javob: «Ijtimoiy ongni shakllantiruvchi metodlar o\'quvchilarda ma\'naviy -axloqiy sifatlar, e\'tiqod hamda dunyoqarashini shakllantirish maqsadida ularning ongi, xis-tuyg\'usi va irodasiga ta\'sir ko\'rsatish usullari sanaladi». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(369, 3, NULL, 'module', 19, 'O\'quvchilarni mehnatga layoqatli va mehnatsevar qilib tarbiyalashda ko\'proq nimalarga e\'tibor bermoq lozim?', '[\"Mehnatda mashq qildirishga\", \"Ishbilarmonlik xislatini tarbiyalashga\", \"Ularni ijtimoiy va ruhiy jihatdan kamol toptirishga\", \"Ma\'naviy-axloqiy e\'tiqodni shaklantirishga\"]', 0, 'To\'g\'ri javob: «Mehnatda mashq qildirishga». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(370, 3, NULL, 'module', 20, 'Kasbiy konsultatsiya (maslahat)ning qanday turlari mavjud?', '[\"Individual-tashxisli, ma\'lumot axborotli, tibbiy\", \"Tibbiy, rag\'batlantiruvchi, ma\'lumot-axborotli\", \"Rag\'batlantiruvchi, individual-tashxisli, tibbiy\", \"Tarbiyalovchi, tibbiy, individual-tashxisli\"]', 0, 'To\'g\'ri javob: «Individual-tashxisli, ma\'lumot axborotli, tibbiy». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(371, 3, NULL, 'module', 21, 'Jismoniy tarbiyaning maqsadi nimadan iborat?', '[\"O\'quvchilarda jismoniy, irodaviy sifatlarni shakllantirish, ularni aqliy va jismoniy jihatdan mehnat, vatan mudofaasiga tayyorlash\", \"O\'quvchilarning saloatliklarini mustahkamlash\", \"O\'quvchilarda jismoniy mashqlarni bajarish ko\'nikma va malakalarini shakllantirish\", \"O\'quvchilarning jismoniy tarbiya va sportga bo\'lgan qiziqishlarini oshirish\"]', 0, 'To\'g\'ri javob: «O\'quvchilarda jismoniy, irodaviy sifatlarni shakllantirish, ularni aqliy va jismoniy jihatdan mehnat, vatan mudofaasiga tayyorlash». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(372, 3, NULL, 'module', 22, 'O\'quvchilar sog\'ligini mustahkamlash, organizmini chiniqtirish, jismoniy jihatdan to\'g\'ri rivojlanishini ta\'minlash, ishlash qobiliyatini rivojlantirish ularda yangi harakat turlariga nisbatan ko\'nikma, malakalar hosil qilish, ularni maxsus bilimlar bilan qurollantirish o\'quvchilarning yoshiga, jinsiga muvofiq keladigan asosiy harakat sifatlarini shakllantirish va rivojlantirish, ularda o\'z sog\'ligiga ongli munosabatni tarbiyalash. Ular jismoniy tarbiyaning... sanaladi.', '[\"Vazifalari\", \"Maqsadi\", \"Yo\'nalishlari\", \"Tamoyillari\"]', 0, 'To\'g\'ri javob: «Vazifalari». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(373, 3, NULL, 'module', 23, 'O\'quvchilarda jismoniy madaniyatni tarbiyalashning asosiy vositalariga nimalar kiradi?', '[\"Jismoniy mashqlar, organizmni chiniqtirishga yordam beruvchi tabiiy va gigienik omillar\", \"Gimnastika, harakatli o\'yinlar, turizm, sport\", \"Jismoniy ta\'sir, organizmni chiniqtirishga yordam beruvchi tabiiy va sun\'iy omillar\", \"Quyosh, suv, havo, uyqu\"]', 0, 'To\'g\'ri javob: «Jismoniy mashqlar, organizmni chiniqtirishga yordam beruvchi tabiiy va gigienik omillar». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(374, 3, NULL, 'module', 24, 'Quyida keltirilgan jismoniy tarbiya vositalaridan qaysi biri maktabgacha va boshlang\'ich ta\'lim yoshi bolalarining jismoniy quvvatini oshirishga, jismoniy, aqliy jihatdan rivojlanishiga yordam beradi?', '[\"Harakatli va didaktik o\'yinlar\", \"Shaxmat-shashka va tennis\", \"Gimnastika\", \"Sayohat\"]', 0, 'To\'g\'ri javob: «Harakatli va didaktik o\'yinlar». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(375, 3, NULL, 'module', 25, 'Jismoniy madaniyatga egalikni ifodalovchi asosiy tushunchalar qaysilar: 1) jismoniy ta\'sir 2) jismoniy harakat ko\'nikmalariga egalik 3) jismoniy mehnat 4) jismoniy kamolot 5) jismoniy ideal 6) jismoniy madaniyat 7) jismoniy jazo', '[\"2, 4, 5, 6\", \"1, 3, 4, 7\", \"1, 2, 4, 6\", \"1, 2, 5, 6\"]', 0, 'To\'g\'ri javob: «2, 4, 5, 6». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(376, 4, NULL, 'module', 1, '“Badanning salomat va quvvatli bo\'lmog\'i insonga eng kerakli narsadir. Chunki o\'qimoq, o\'qitmoq va o\'rgatmoq uchun insonga kuchlik, kasalsiz vujud kerakdir”. Ushbu fikr kim tomonidan ilgari surilgan?', '[\"Abdulla Avloniy\", \"Ibn Sino\", \"Alisher Navoiy\", \"Yan Amos Komenskiy\"]', 0, 'To\'g\'ri javob: «Abdulla Avloniy». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(377, 4, NULL, 'module', 2, 'Estetik tarbiyaning maqsadi nimadan iborat?', '[\"Shaxsning voqelikka estetik munosabatini shakllantirish\", \"O\'quvchilarni go\'zallikni his qilishga o\'rgatish\", \"O\'quvchilarda san\'at asarlari, shu jumladan, badiiy adabiyotga qiziqishni uyg\'otish\", \"O\'quvchilarda tasviriy san\'at, jumladan, rassomlik va haykaltaroshlikka oid asarlar mohiyatini tushuna olishga o\'rgatish\"]', 0, 'To\'g\'ri javob: «Shaxsning voqelikka estetik munosabatini shakllantirish». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(378, 4, NULL, 'module', 3, 'Estetik tarbiyaning asosiy vazifalari nimalardan iborat?', '[\"Shaxsda estetik tushuncha, estetik idrok, his-tuyg\'u, did, madaniyatni shakllantirish\", \"Shaxsda tabiiy go\'zallikni his qila olish ko\'nikmalarini shakllantirish\", \"Shaxsni san\'at asarlarida ilgari surilgan ma\'noni anglashga o\'rgatish\", \"Shaxsni go\'zallikni sevishga o\'rgatish\"]', 0, 'To\'g\'ri javob: «Shaxsda estetik tushuncha, estetik idrok, his-tuyg\'u, did, madaniyatni shakllantirish». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(379, 4, NULL, 'module', 4, 'Estetikaning asosiy tushunchalarini aniqlang: 1) estetik his-tuyg\'u 2) estetik tamoyil 3) estetik did 4) estetik me\'yor 5) estetik mulohaza 6) estetik ideal.', '[\"1, 3, 5, 6\", \"1, 2, 5, 6\", \"1, 2, 3, 4\", \"1, 4, 5, 6\"]', 0, 'To\'g\'ri javob: «1, 3, 5, 6». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(380, 4, NULL, 'module', 5, 'Shaxsning aniq bir estetik hodisaga munosabatini bildiruvchi aqliy harakati nima?', '[\"Estetik mulohaza\", \"Estetik ehtiyoj\", \"Estetik ong\", \"Estetik did\"]', 0, 'To\'g\'ri javob: «Estetik mulohaza». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
