(384, 4, NULL, 'module', 9, 'Ekologik tarbiyaning asosiy maqsadi va vazifalari nimalardan iborat?', '[\"O\'quvchilarga tabiatni muhofaza qilishga oid nazariy va amaliy bilimlarni berish asosida tabiatga, atrof-muhitga ijobiy munosabatni shakllantirish\", \"O\'quvchilarga ekotizim va uning xususiyatlarini o\'rganish\", \"O\'quvchilarni tabiiy jarayonlarning mohiyatidan xabardor bo\'lish\", \"O\'quvchilarda tabiat bilan o\'zaro uyg\'unlikka erishish ko\'nikmalarini shakllantirish\"]', 0, 'To\'g\'ri javob: «O\'quvchilarga tabiatni muhofaza qilishga oid nazariy va amaliy bilimlarni berish asosida tabiatga, atrof-muhitga ijobiy munosabatni shakllantirish». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(385, 4, NULL, 'module', 10, 'Ekologik tarbiyaning vazifalarini aniqlang.', '[\"1, 3, 5\", \"1, 2, 3\", \"2, 3, 5\", \"3, 4, 5\"]', 0, 'To\'g\'ri javob: «1, 3, 5». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(386, 4, NULL, 'module', 11, 'Didaktika – bu:', '[\"Ta\'lim nazariyasi\", \"Rivojlanish nazariyasi\", \"Tarbiya nazariyasi\", \"Ta\'lim-tarbiya nazariyasi\"]', 0, 'To\'g\'ri javob: «Ta\'lim nazariyasi». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(387, 4, NULL, 'module', 12, 'Didaktika nimani o\'rganadi?', '[\"O\'qitish mazmuni, qonuniyatlari, tamoyillari, shakl, metod va vositalarini\", \"Shaxsning umumiy rivojlanish qonuniyatlarini\", \"Bolaning atrofdagilar bilan o\'zaro munosabatini\", \"Shaxsga ta\'lim hamda tarbiya berishga salbiy ta\'sir etuvchi omillarni\"]', 0, 'To\'g\'ri javob: «O\'qitish mazmuni, qonuniyatlari, tamoyillari, shakl, metod va vositalarini». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(388, 4, NULL, 'module', 13, 'Ta\'lim funksiyalari qaysi javobda to\'g\'ri ko\'rsatilgan?', '[\"Bilim berish, tarbiyalash, rivojlantirish\", \"O\'quv fanlari mazmunini o\'zlashtirib olish\", \"Bilim, ko\'nikma, malaka hosil qilish\", \"Tevarak-atrofdagi voqealarni tushuntirish\"]', 0, 'To\'g\'ri javob: «Bilim berish, tarbiyalash, rivojlantirish». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
