(390, 4, NULL, 'module', 15, '“Ta\'lim beruvchi, rivojlantiruvchi va tarbiyalovchi” tushunchalari didaktikaning qaysi jihatini yoritadi?', '[\"Ta\'lim funksiyalari\", \"Ta\'lim vositalari\", \"Ta\'lim metodlari\", \"Ta\'lim natijasi\"]', 0, 'To\'g\'ri javob: «Ta\'lim funksiyalari». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(391, 4, NULL, 'module', 16, 'O\'quvchilar bilim sifatini va o\'qitish natijalarini dtsga muvofiqligini ta\'minlash uchun joriy, oraliq va yakuniy nazorat bilan birga umumiy o\'rta maktablarda yana qanday nazoratni o\'tkazish ko\'zda tutilgan?', '[\"Bosqichli nazorat\", \"Izchil nazorat\", \"Davomiy nazorat\", \"Tizimli nazorat\"]', 0, 'To\'g\'ri javob: «Bosqichli nazorat». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(392, 4, NULL, 'module', 17, 'Buyuk chex olimi ya.a.komenskiy tomonidan “didaktikaning oltin qoidasi” deb e\'tirof etilgan tamoyil qaysi?', '[\"Ko\'rsatmalilik\", \"Ta\'lim berishda ilmiy atamalardan foydalanish\", \"Ta\'limning tabiat bilan uyg\'unligi\", \"Nazariy bilimlarning o\'quvchilar uchun tushunarli bo\'lishi\"]', 0, 'To\'g\'ri javob: «Ko\'rsatmalilik». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(393, 4, NULL, 'module', 18, 'Jismoniy hamda ruhiy rivojlanishda nuqsoni bo\'lgan, shuningdek, uzoq vaqt davolanishga muhtoj bolalar va o\'smirlar qanday ta\'lim muassasalarida o\'qitiladilar?', '[\"Ixtisoslashtirilgan (maxsus) ta\'lim muassasalarida\", \"Umumiy o\'rta ta\'lim muassasalarida\", \"O\'rta maxsus kasb-hunar ta\'limi muassasalarida\", \"Sog\'lomlashtirish muassasalarida\"]', 0, 'To\'g\'ri javob: «Ixtisoslashtirilgan (maxsus) ta\'lim muassasalarida». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(394, 4, NULL, 'module', 19, 'Ta\'limni tashkil etish shakllari qaysi variant javobda to\'g\'ri ko\'rsatilgan?', '[\"An\'anaviy ta\'lim, noan\'anaviy ta\'lim, interfaol ta\'lim\", \"Yakka tartibdagi ta\'lim, repetitorlik ta\'lim, fakultativ ta\'lim\", \"Ekskursiya, ma\'ruza, viktorina\", \"An\'anaviy ta\'lim va noan\'anaviy ta\'lim\"]', 0, 'To\'g\'ri javob: «An\'anaviy ta\'lim, noan\'anaviy ta\'lim, interfaol ta\'lim». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(395, 4, NULL, 'module', 20, 'Noan\'aviy ta\'lim shakliga nimalar kiradi?', '[\"Ma\'ruza, fakultativ, seminar, laboratoriya mashg\'ulotlari, ekskursiya, bahs-munozara, davra stoli, viktorina va b\", \"Yangi bilimlarni bayon qilish darslari, takrorlash darslar va b\", \"Kirish darslari, bkmni tekshirish darslari va b\", \"Ma\'ruza, ekskursiya, uchrashuv, debat, davra stoli, viktorina, mahorat darslari va b\"]', 0, 'To\'g\'ri javob: «Ma\'ruza, fakultativ, seminar, laboratoriya mashg\'ulotlari, ekskursiya, bahs-munozara, davra stoli, viktorina va b». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(396, 4, NULL, 'module', 21, 'Darsning boshlanishini tashkil etish uy vazifasini tekshirish, maqsadi, vazifasini bayon qilish, yangi materiallarni tushuntirish, mustahkamlash, yakun yasash va uyga vazifa berish kabi vazialar hal qilinadigan dars tipini ko\'rsating:', '[\"Aralash dars\", \"Bilimlarni takrorlash\", \"Yangi bilimlarni berish\", \"Umumlashtirilgan darsi\"]', 0, 'To\'g\'ri javob: «Aralash dars». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(397, 4, NULL, 'module', 22, 'Eng qadimgi yozma ma\'rifiy yodgorlik?', '[\"Avesto\", \"Kalima va dimna\", \"Shoxnoma\", \"Qobusnoma\"]', 0, 'To\'g\'ri javob: «Avesto». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(398, 4, NULL, 'module', 23, 'Majburiy standartli tekshiruv ishlari qaysi nazorat tarkibiga kiradi?', '[\"Maxsus nazorat\", \"Oraliq nazorat\", \"Joriy nazorat\", \"Bosqichli nazorat\"]', 0, 'To\'g\'ri javob: «Maxsus nazorat». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(399, 4, NULL, 'module', 24, 'O\'quv dasturida nimalar aks etadi?', '[\"Har bir o\'quv fanining mazmuni, o\'quv yillari bo\'yicha dastur mazmuni, mavzularining tahminiy soatlari\", \"O\'quvchi shaxsini tarbiyalash maqsadi, vazifalari, ularni mutaxassis qilib etishtirish\", \"O\'quv yilining strukturasi, ta\'tillar kuni, dam olish haftalari va dars soatlari\", \"O\'quv predmetining ajratilgan haftalik soatlar miqdori va choraklarda necha soatdan mavzu bo\'lishi\"]', 0, 'To\'g\'ri javob: «Har bir o\'quv fanining mazmuni, o\'quv yillari bo\'yicha dastur mazmuni, mavzularining tahminiy soatlari». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(400, 4, NULL, 'module', 25, 'O\'quvchilarga nazariy va amaliy bilimni tartibli bayon qilishga yo\'naltirilgan jarayon qanday nomlanadi?', '[\"Ta\'lim\", \"Bilim\", \"Ma\'lumot\", \"Faoliyat\"]', 0, 'To\'g\'ri javob: «Ta\'lim». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 1, 0, 6),
(401, NULL, NULL, 'course_final', 1, 'O\'quvchining iste\'dod va qobiliyatining rivojlanishi nimaga bog\'liq?', '[\"Faoliyatga, muloqotga, ta\'lim-tarbiyaning pedagogik jihatdan o\'zaro muvofiqligiga\", \"Tarbiyaviy tug\'ma nishonlarga va yil davomida muvaffaqiyatli o\'qishga\", \"O\'zlashtirgan bilimlarning miqdori va uning to\'plagan hajmiga\", \"O\'qitish, tarbiyalash metodlariga va bilimlarni tez o\'zlashtirishga\"]', 0, 'To\'g\'ri javob: «Faoliyatga, muloqotga, ta\'lim-tarbiyaning pedagogik jihatdan o\'zaro muvofiqligiga». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 1, 10),
(402, NULL, NULL, 'course_final', 2, 'Maktab ta\'limining mazmuni qaysi me\'yoriy hujjatlarda aks etadi?', '[\"O\'quv rejasi, darsliklar, o\'quv dasturlar va dtsda\", \"O\'quv dasturlari, metodik ko\'rsatmalar va dtsda\", \"Pedagogik kengash qarorlari, metodik yo\'riqnomalar va dtsda\", \"Buyruqlar, darsliklar va dtsda\"]', 0, 'To\'g\'ri javob: «O\'quv rejasi, darsliklar, o\'quv dasturlar va dtsda». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 1, 10),
(403, NULL, NULL, 'course_final', 3, 'Boshlang\'ich sinf o\'quvchilari faoliyatida nimalar asosiy o\'rin tutadi?', '[\"O\'yin, o\'qish\", \"Mehnat, o\'yin\", \"O\'qish, mehnat\", \"Muomala, mehnat\"]', 0, 'To\'g\'ri javob: «O\'yin, o\'qish». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 1, 10),
(404, NULL, NULL, 'course_final', 4, 'Ta\'lim metodlarining asosiy turlari qaysi javobda to\'g\'ri ko\'rsatilgan?', '[\"Og\'zaki bayon qilish, ko\'rgazmali va amaliy metodlar\", \"O\'qishga qiziqishni rag\'batlantiruvchi, o\'z-o\'zini nazorat metodlari\", \"Bilish faoliyatini kuzatish, nazorat va o\'quv faoliyatini tuzatish metodlari\", \"Nazariy bayon qilish, mehnatga va muayyan kasbga qiziqishni rag\'batlantirish\"]', 0, 'To\'g\'ri javob: «Og\'zaki bayon qilish, ko\'rgazmali va amaliy metodlar». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 1, 10),
(405, NULL, NULL, 'course_final', 5, 'Ta\'limning amaliy metodlariga nimalar kirishini ko\'rsating?', '[\"Mashq qilish, laboratoriya va amaliy ishlar\", \"Illyustratsiya, namoyish qilib ko\'rsatilishi\", \"Hikoya, tushuntirish, suhbat, ma\'ruza\", \"Test, algoritmlash, qisman izlanish, induksiya\"]', 0, 'To\'g\'ri javob: «Mashq qilish, laboratoriya va amaliy ishlar». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 1, 10),
(406, NULL, NULL, 'course_final', 6, 'Kasb-hunar kolleji qanday muassasa?', '[\"O\'quvchilarning kasb-hunarga moyilligi, mahorat va malakasini chuqur rivojlantirishni, tanlagan kasblar bo\'yicha bir yoki bir necha ixtisos olishni ta\'minlaydigan uch yillik o\'rta maxsus kasb-hunar o\'quv yurti\", \"O\'quvchilarning intellektual qobiliyatlarini jadal o\'stirishni, ularning chuqur, tabaqalashtirilgan va kasb-hunar yo\'naltirilgan bilim olishlarini ta\'minlaydigan uch yillik o\'rta maxsus o\'quv yurti\", \"O\'quvchilarning yakka tartibdagi ehtiyojlarini qondirish, ularning bo\'sh vaqti va dam olishini tashkil etish uchun turli yo\'nalishlarda ta\'limni tashkil etishga yo\'naltirilgan ko\'p yillik faoliyatni olib boradigan o\'quv yurti\", \"Ta\'lim yo\'nalishlaridan biri bo\'yicha puxta bilim beradigan, o\'qish muddati kamida uch yil bo\'lgan o\'rta maxsus o\'quv yurti\"]', 0, 'To\'g\'ri javob: «O\'quvchilarning kasb-hunarga moyilligi, mahorat va malakasini chuqur rivojlantirishni, tanlagan kasblar bo\'yicha bir yoki bir necha ixtisos olishni ta\'minlaydigan uch yillik o\'rta maxsus kasb-hunar o\'quv yurti». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 1, 10);
