(411, NULL, NULL, 'course_final', 11, 'Tashxis negizida qanday ishlar amalga oshiriladi?', '[\"O\'quvchilarning bkm darajasini aniqlash, o\'lchash va baholash\", \"O\'quvchilar tomonidan o\'zlashtirilgan nazariy bilimlar darajasini hisobga olish\", \"O\'quvchilarning bilim, ko\'nikma va malakalarini baholash\", \"O\'quvchilar faoliyatini nazorat qilish\"]', 0, 'To\'g\'ri javob: «O\'quvchilarning bkm darajasini aniqlash, o\'lchash va baholash». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 1, 10),
(412, NULL, NULL, 'course_final', 12, 'Maktabgacha ta\'lim qanday maqsadni ko\'zlaydi?', '[\"Bola shaxsini sog\'lom va etuk, maktabda o\'qishga tayyorlangan tarzda shakllantirishni\", \"Bolaning savodxonlik ko\'nikmalarini shakllantirishni\", \"Bolada ijtimoiy va tabiiy borliqni anglash ko\'nikmalarini shakllantirishni\", \"Bola shaxsida nutq va faoliyat ko\'nikmalarini shakllantirishni\"]', 0, 'To\'g\'ri javob: «Bola shaxsini sog\'lom va etuk, maktabda o\'qishga tayyorlangan tarzda shakllantirishni». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 1, 10),
(413, NULL, NULL, 'course_final', 13, 'Umumiy o\'rta ta\'lim qanday bosqichlardan iborat?', '[\"Boshlang\'ich ta\'lim va umumiy o\'rta ta\'lim\", \"Boshlang\'ich ta\'lim va o\'rta maxsus, kasb-hunar ta\'limi\", \"Maktabgacha va boshlang\'ich ta\'lim\", \"Uzluksiz ta\'limning barcha bosqichlari\"]', 0, 'To\'g\'ri javob: «Boshlang\'ich ta\'lim va umumiy o\'rta ta\'lim». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 1, 10),
(414, NULL, NULL, 'course_final', 14, 'Akademik litsey qanday muassasasi?', '[\"O\'quvchilarning intellektual qobiliyatlarini jadal o\'stirishni, ularning chuqur, tabaqalashtirilgan va kasb-hunar yo\'naltirilgan bilim olishlarini ta\'minlaydigan uch yillik o\'rta maxsus o\'quv yurti\", \"O\'quvchilarning kasb-hunarga moyilligi, mahorat va malakasini chuqur rivojlantirishni ta\'minlaydigan uch yillik o\'rta maxsus o\'quv yurti\", \"Tabaqalashtirilmagan bo\'lsa-da, o\'quvchilarda kasbiy ko\'nikmalarni shaklantirishga xizmat qiladigan uch yillik o\'rta maxsus o\'quv yurti\", \"Tanlangan kasblar bo\'yicha bir yoki bir necha ixtisos olishni ta\'minlaydigan uch yillik o\'rta kasb-hunar o\'quv yurti\"]', 0, 'To\'g\'ri javob: «O\'quvchilarning intellektual qobiliyatlarini jadal o\'stirishni, ularning chuqur, tabaqalashtirilgan va kasb-hunar yo\'naltirilgan bilim olishlarini ta\'minlaydigan uch yillik o\'rta maxsus o\'quv yurti». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 1, 10),
(415, NULL, NULL, 'course_final', 15, '“Qobusnoma” asarida yoshlar tarbiyasida – juvonmardlik talablaridan eng muhimi:', '[\"Axloq tarbiyasi\", \"Aqliy tarbiya\", \"Estetik tarbiya\", \"Jismoniy tarbiya\"]', 0, 'To\'g\'ri javob: «Axloq tarbiyasi». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 1, 10),
