(418, NULL, NULL, 'course_final', 18, 'Birinchi marta jadidchilik qayerda paydo bo\'ldi?', '[\"Qirimda\", \"O\'zbekistonda\", \"Rossiyada\", \"Xorijda\"]', 0, 'To\'g\'ri javob: «Qirimda». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 1, 10),
(419, NULL, NULL, 'course_final', 19, 'Oliy ta\'lim yo\'nalishlaridan biri bo\'yicha puxta bilim beradigan, o\'qish muddati kamida to\'rt yil bo\'lgan tayanch oliy ta\'lim – bu...', '[\"Bakalvriat\", \"Adyunktura\", \"Doktarantura\", \"Magistratura\"]', 0, 'To\'g\'ri javob: «Bakalvriat». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 1, 10),
