(436, NULL, NULL, 'course_final', 36, '“Maktab, mahalla, oila, hamkorligi” kontseptsiyasi qachon ishlab chiqilgan?', '[\"1999 y\", \"1993 y\", \"1994 y\", \"1995 y\"]', 0, 'To\'g\'ri javob: «1999 y». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 1, 10),
(437, NULL, NULL, 'course_final', 37, 'Nechanchi yili “Yoshlar yili ” deb qabul qilingan?', '[\"2008 y\", \"2009 y\", \"2011 y\", \"2011 y\"]', 0, 'To\'g\'ri javob: «2008 y». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 1, 10),
(438, NULL, NULL, 'course_final', 38, 'Quyidagi pedagogik nazokatga oid fikrga o\'z munosabatingizni bildiring.', '[\"Pedagogik nazokat – o\'qituvchining kasbiy sifati va maxoratining bir yunalishi, uning odobi esa o\'qituvchining obrusini tartibga solib turadi, uni saklashga yordam beradi, kollektivdagi urnini belgilaydi\", \"Pedagogik nazokat – dustlik, xizmatdagi moslik, chikishib, xamjixat bo\'lish, mayinlik, uni saklashga yordam beradi, kollektivdagi urnini belgilaydi\", \"Pedagogik nazokat – tadbirni tanlash, uning rejasini to\'zish, o\'tkazish va tahlil qilish, uni saklashga yordam beradi, kollektivdagi urnini belgilaydi\", \"Pedagogik nazokat - nafas olish, ovozni o\'zgaruvchanligi, talaffo\'z ravon notiq, uni saklashga yordam beradi, kollektivdagi urnini belgilaydi\"]', 0, 'To\'g\'ri javob: «Pedagogik nazokat – o\'qituvchining kasbiy sifati va maxoratining bir yunalishi, uning odobi esa o\'qituvchining obrusini tartibga solib turadi, uni saklashga yordam beradi, kollektivdagi urnini belgilaydi». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 1, 10),
(439, NULL, NULL, 'course_final', 39, '“Maktab, oila, mahalla hamkorligi” kontseptsiyasining maqsad va vazifalari nimalardan iborat?', '[\"Yoshlarni milliy istiqlol g\'oyalariga sadoqatli ma\'naviy barkamol vatanparvarlik ruhida tarbiyalash\", \"Yoshlar sportini ommaviy rivojlantirish tizimini yaratish, vatanparvarlik ruhida tarbiyalash\", \"Vositalar tavsiyalar ishlab chiqishdan iborat, vatanparvarlik ruhida tarbiyalash\", \"Xuquq va manfaatlarini himoyalashga qaratilgan ish, vatanparvarlik ruhida tarbiyalash\"]', 0, 'To\'g\'ri javob: «Yoshlarni milliy istiqlol g\'oyalariga sadoqatli ma\'naviy barkamol vatanparvarlik ruhida tarbiyalash». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 1, 10),
(440, NULL, NULL, 'course_final', 40, 'O\'qituvchining notiqlik qobiliyatiga berilgan tahrif qaysi banda tugri ko\'rsatilgan?', '[\"O\'qituvchining tarbiyalanuvchi ichki duyosiga kira olish qobiliyati\", \"To\'g\'ri talaffuz qila olishi\", \"To\'g\'ri muomala qila olish qobiliyati\", \"No\'tiq erdamida o\'z fikr-tuyg\'ularini aniq va ravshan ifodalash qobiliyati\"]', 0, 'To\'g\'ri javob: «O\'qituvchining tarbiyalanuvchi ichki duyosiga kira olish qobiliyati». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 1, 10),
(441, NULL, NULL, 'course_final', 41, 'Pedagogik mahoratning tarkibiy qismlari to\'ri ko\'rsatilgan javobni ko\'rsating', '[\"Insonparvarlik, kasbiy bilimlar, pedagogik qobiliyat, pedagogik texnika\", \"Bilim, ko\'nikma, malaka, kasbiy ko\'nikma va malaka, kasbiy bilim va tushunchasi\", \"Kasbiy qadriyat va (ustanovka) tayyorgarligi, kasbiy ko\'nikma va malaka, kasbiy bilim va tushunchasi\", \"Pedagogik qobiliyatlar, pedagogik layoqat, kasbiy ko\'nikma va malaka, kasbiy bilim va tushunchasi\"]', 0, 'To\'g\'ri javob: «Insonparvarlik, kasbiy bilimlar, pedagogik qobiliyat, pedagogik texnika». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 1, 10),
(442, NULL, NULL, 'course_final', 42, 'O\'qituvchining qiziqishi, intilishi, uzoq vaqt izlanishi natijasida hosil bo\'lgan, o\'ziga xos o\'yin, mehnat, musobaqa elementlari bo\'lgan yangi bir dars turi darsni tashkil etishning qaysi usuliga kiradi?', '[\"Noan\'anaviy\", \"Repetitorlik\", \"An\'anaviy\", \"Individual\"]', 0, 'To\'g\'ri javob: «Noan\'anaviy». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 1, 10),
(443, NULL, NULL, 'course_final', 43, 'Metodlarni optimal tanlashga qanday talablar qo\'yiladi? (metodning optimalligini nima belgilaydi?)', '[\"Dars maqsadi, predmetning va mavzuning xususiyati, vaqt, sharoit, o\'quv bazasi, o\'qituvchi mahorati, o\'quvchilarning yoshi va tayyorlik darajasi\", \"Sinf o\'quvchilarining imkoniyati, o\'qituvchining shaxsiy imkoniyati va mahorati, maktab sharoiti\", \"Faoliyatning xususiyati, bolaning anatom-fiziologik xususiyati, ruhiyati, ilmiy fikr mantig\'i\", \"O\'quvchi o\'zlashtirishga ta\'sir etadigan ichki va tashqi sabablar, maktabning o\'quv bazasi\"]', 0, 'To\'g\'ri javob: «Dars maqsadi, predmetning va mavzuning xususiyati, vaqt, sharoit, o\'quv bazasi, o\'qituvchi mahorati, o\'quvchilarning yoshi va tayyorlik darajasi». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 1, 10),
(444, NULL, NULL, 'course_final', 44, 'Dars tiplari qaysilar?', '[\"Yangi bilim berish darsi, umumlashtirish-tizimlashtirish darsi, takroriy-qaytarish darsi, nazorat darslari, aralash dars\", \"Turli mashg\'ulotlar qatnashadigan dars, sinov-mavzuli dars, kino dars, ma\'ruza darsi\", \"Konferentsiya-darsi, matbuot konferentsiyasi darslari, uchrashuv\", \"Aralash dars, kitob bilan ishlash, umumlashtirish\"]', 0, 'To\'g\'ri javob: «Yangi bilim berish darsi, umumlashtirish-tizimlashtirish darsi, takroriy-qaytarish darsi, nazorat darslari, aralash dars». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 1, 10),
(445, NULL, NULL, 'course_final', 45, 'Innovatsion yondoshuv nima?', '[\"Muammoni yechish uchun yangicha yondashuv yoki yangi texnologik jarayonni qo\'llash\", \"Turli maqsadlar shajarasini ishlab chiqish va vazifalarni amalga oshirish\", \"Tartibga solish va nazorat qilish\", \"Zamon ehtiyojiy talablaridan kelib chiqib boshqarishni yo\'lga qo\'yish\"]', 0, 'To\'g\'ri javob: «Muammoni yechish uchun yangicha yondashuv yoki yangi texnologik jarayonni qo\'llash». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 1, 10),
(446, NULL, NULL, 'course_final', 46, 'O\'qitish usuli (metodlari) deganda nima tushuniladi?', '[\"O\'qituvchi va o\'quvchilarning o\'qish vazifalarini bajarishga qaratilgan nazariy va amaliy bilish faoliyatini uyushtirish usuli va amalga oshirish yo\'li\", \"Bilimlarni bayon qilish, mashqlantirish, amaliy ishlar olib borish\", \"Ta\'lim vazifasini hal qilishga qaratilgan o\'qituvchi va o\'quvchilarning birgalikdagi faoliyatini belgilash yo\'li va vositasi\", \"O\'qitishni amalga oshirish va bolalar bilish faoliyatiga rahbarlik qilish\"]', 0, 'To\'g\'ri javob: «O\'qituvchi va o\'quvchilarning o\'qish vazifalarini bajarishga qaratilgan nazariy va amaliy bilish faoliyatini uyushtirish usuli va amalga oshirish yo\'li». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 1, 10),
(447, NULL, NULL, 'course_final', 47, 'O\'qitish jarayonida nazoratning rivojlantiruvchi funksiyasini toping', '[\"O\'z-o\'zini nazorat qilish va baholash\", \"Xotirani mustahkamlash\", \"O\'quvchilarda barqaror diqqatni vujudga keltirish\", \"Baholash\"]', 0, 'To\'g\'ri javob: «O\'z-o\'zini nazorat qilish va baholash». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 1, 10),
(448, NULL, NULL, 'course_final', 48, 'Masofadan o\'qitish qanday amalga oshiriladi?', '[\"Kommunikatsion texnologiyalar orqali\", \"O\'quv adabiyotlari orqali\", \"Kompyuter texnikasi orqali\", \"T\'yutorlar yordamida\"]', 0, 'To\'g\'ri javob: «Kommunikatsion texnologiyalar orqali». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 1, 10),
(449, NULL, NULL, 'course_final', 49, 'Innovatsiya nima?', '[\"Innovatsiya – yangilik kiritish\", \"Innovatsiya – yangicha ta\'lim\", \"Innovatsiya - dasturlashtirilgan ta\'lim\", \"Innovatsiya - muammoli ta\'lim\"]', 0, 'To\'g\'ri javob: «Innovatsiya – yangilik kiritish». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 1, 10),
(450, NULL, NULL, 'course_final', 50, 'Kompetensiya nima?', '[\"Kompetensiya-bilim, ko\'nikma, malaka, qobiliyat, qarashlar, shaxsning malakasi yoki ish yuritish qobiliyatlarining namoyon bo\'lishini belgilab beradigan shaxsiy sifatlar va qadriyatlar yig\'indisi\", \"Kompetensiya-xulq-atvor, bilim, malaka, munosabat, motiv\", \"Kompetensiya- o\'z-o\'zini namoyon qilish, boshqa odamlar bilan ijtimoiy muloqotda bo\'lish, o\'z ustida tinimsiz ishlash\", \"Kompetensiya- vaziyatni baholash va muammolarni yechish ko\'nikmasiga ega bo\'lish, tashkilotchilik, ijodiy yondashuv, boshqaruv ko\'nikmasiga ega bo\'lish\"]', 0, 'To\'g\'ri javob: «Kompetensiya-bilim, ko\'nikma, malaka, qobiliyat, qarashlar, shaxsning malakasi yoki ish yuritish qobiliyatlarining namoyon bo\'lishini belgilab beradigan shaxsiy sifatlar va qadriyatlar yig\'indisi». Didaktika va pedagogika qonuniyatlariga asosan to\'g\'ri hisoblanadi.', 0, 1, 10);
